import type { Bilingual } from '../../lib/lesson-types';
import optimizationAuthor from './optimization-learning';

type TeachingEntry = {
  application: Bilingual;
  formula: Bilingual;
  steps: [Bilingual, Bilingual, Bilingual];
};
type Row = [string, TeachingEntry];

const B = (en: string, vi: string): Bilingual => ({ en, vi });
const L = (
  id: string,
  appEn: string,
  appVi: string,
  formulaEn: string,
  formulaVi: string,
  step1: [string, string],
  step2: [string, string],
  step3: [string, string],
): Row => [id, {
  application: B(appEn, appVi),
  formula: B(formulaEn, formulaVi),
  steps: [B(...step1), B(...step2), B(...step3)],
}];

// Each row is keyed to one authored exercise. Keep the concrete setup tied to
// that prompt; the imported author file remains the source of exercise IDs.
const rows: Row[] = [
  L('m2-w061-e1', 'A two-resource production plan is a point (x₁,x₂) in the unit simplex: each quantity is nonnegative and their total is at most one.', 'Một kế hoạch sản xuất dùng hai nguồn lực là điểm (x₁,x₂) trong đơn hình đơn vị: mỗi lượng không âm và tổng không quá một.', 'C is convex iff (1−t)x+ty ∈ C for every x,y ∈ C and t ∈ [0,1]; the simplex vertices are (0,0),(1,0),(0,1).', 'C lồi khi (1−t)x+ty ∈ C với mọi x,y ∈ C, t ∈ [0,1]; các đỉnh đơn hình là (0,0),(1,0),(0,1).', ['Take arbitrary feasible x,y and form z=(1−t)x+ty; convexity is a statement about every pair, not just vertices.', 'Lấy x,y khả thi tùy ý và lập z=(1−t)x+ty; tính lồi nói về mọi cặp, không chỉ các đỉnh.'], ['Check each coordinate stays nonnegative because it is a weighted average; separately bound z₁+z₂ by the same weighted-average argument.', 'Kiểm tra từng tọa độ vẫn không âm vì là trung bình có trọng số; riêng tổng z₁+z₂ cũng bị chặn bằng lập luận ấy.'], ['Write the barycentric weights 1−x₁−x₂,x₁,x₂; they are nonnegative and sum to one, so they also identify all extreme points.', 'Viết trọng số barycentric 1−x₁−x₂,x₁,x₂; chúng không âm và tổng bằng một, qua đó xác định các điểm cực biên.']),
  L('m2-w061-e2', 'A quadratic cost in two design variables has a candidate operating point where both marginal costs vanish; the Hessian checks whether that point is the unique global design.', 'Hàm chi phí bậc hai theo hai biến thiết kế có điểm vận hành ứng viên nơi hai chi phí biên bằng không; Hessian kiểm tra đó có là nghiệm toàn cục duy nhất không.', 'For differentiable convex f on Rⁿ, ∇f(x*)=0 implies f(y)≥f(x*) for all y; H≻0 makes a quadratic strictly convex and its minimizer unique.', 'Với f khả vi lồi trên Rⁿ, ∇f(x*)=0 suy ra f(y)≥f(x*) với mọi y; H≻0 làm quadratic lồi nghiêm ngặt và nghiệm duy nhất.', ['Differentiate each coordinate of x²+2y²−2x+4y and solve the two zero-gradient equations.', 'Lấy đạo hàm theo từng tọa độ của x²+2y²−2x+4y rồi giải hai phương trình gradient bằng không.'], ['Evaluate the Hessian diag(2,4); its positive eigenvalues establish strict convexity, so the first-order certificate is global.', 'Tính Hessian diag(2,4); các trị riêng dương chứng minh lồi nghiêm ngặt, nên chứng chỉ bậc nhất là toàn cục.'], ['Substitute the point into f only after the location and uniqueness argument; keep function value separate from optimality proof.', 'Chỉ thế điểm vào f sau khi đã chứng minh vị trí và tính duy nhất; tách giá trị hàm khỏi chứng minh tối ưu.']),
  L('m2-w061-e3', 'A cost depending on u but not v lets a whole line of designs tie for the same minimum; the zero-curvature direction explains that nonuniqueness.', 'Chi phí phụ thuộc u nhưng không phụ thuộc v khiến cả một đường thiết kế cùng đạt cực tiểu; hướng độ cong bằng không giải thích sự không duy nhất.', 'For f(u,v)=(u−2)², ∇f=(2(u−2),0), H=diag(2,0); minimizers satisfy ∇f=0 and have value 0.', 'Với f(u,v)=(u−2)², ∇f=(2(u−2),0), H=diag(2,0); nghiệm cực tiểu thỏa ∇f=0 và có giá trị 0.', ['Set both gradient coordinates to zero; the second equation imposes no restriction on v.', 'Cho cả hai tọa độ gradient bằng không; phương trình thứ hai không đặt điều kiện lên v.'], ['Evaluate f on every stationary point to establish the full minimizer set, not merely one example.', 'Tính f tại mọi điểm dừng để xác định toàn bộ tập nghiệm, không chỉ một ví dụ.'], ['Diagonalize H: eigenvalue 2 curves across u, while eigenvalue 0 makes the (0,1) direction flat and the minimizer nonunique.', 'Chéo hóa H: trị riêng 2 tạo độ cong theo u, còn trị riêng 0 làm hướng (0,1) phẳng và nghiệm không duy nhất.']),
  L('m2-w061-e4', 'To certify a stationary point of a differentiable convex loss on a restricted domain, compare it to an arbitrary feasible point along the segment joining them.', 'Để chứng nhận điểm dừng của loss lồi khả vi trên miền giới hạn, so sánh nó với điểm khả thi tùy ý dọc đoạn nối hai điểm.', 'Convexity gives f(y)≥f(x*)+∇f(x*)ᵀ(y−x*); the segment argument requires x*+t(y−x*) ∈ C for every t∈[0,1].', 'Tính lồi cho f(y)≥f(x*)+∇f(x*)ᵀ(y−x*); lập luận theo đoạn cần x*+t(y−x*) ∈ C với mọi t∈[0,1].', ['Fix arbitrary y∈C and define the one-dimensional restriction φ(t)=f(x*+t(y−x*)). Convexity of C keeps the entire path inside the domain.', 'Chọn y∈C tùy ý và đặt φ(t)=f(x*+t(y−x*)). Tính lồi của C giữ cả đường đi trong miền xác định.'], ['Apply the one-dimensional convex slope inequality between t=0 and t=1 to obtain the first-order lower bound.', 'Áp dụng bất đẳng thức độ dốc lồi một chiều giữa t=0 và t=1 để được cận dưới bậc nhất.'], ['Use ∇f(x*)=0 at the final line; for a nonconvex domain, the path may leave C, so this proof step is unavailable.', 'Dùng ∇f(x*)=0 ở dòng cuối; với miền không lồi, đường đi có thể rời C nên bước chứng minh này không còn dùng được.']),
  L('m2-w061-e5', 'A stationary point of a nonconvex objective can be a maximum, while a flat convex objective can have many minima; these test different claims.', 'Điểm dừng của hàm không lồi có thể là cực đại, còn hàm lồi phẳng có thể có nhiều cực tiểu; hai ví dụ kiểm tra hai mệnh đề khác nhau.', 'Stationarity ∇f(x)=0 is only necessary at an interior differentiable extremum; convexity gives global minimality, strict convexity gives uniqueness.', 'Điều kiện ∇f(x)=0 chỉ cần tại cực trị nội khả vi; tính lồi cho cực tiểu toàn cục, lồi nghiêm ngặt cho tính duy nhất.', ['For f(x)=−x², evaluate f′(0) and compare f(0) with a nearby value such as f(1).', 'Với f(x)=−x², tính f′(0) rồi so f(0) với giá trị lân cận như f(1).'], ['For g(x)=0 on [0,1], verify convexity and show every point attains the same minimum.', 'Với g(x)=0 trên [0,1], kiểm tra tính lồi và chỉ ra mọi điểm cùng đạt cực tiểu.'], ['State precisely which hypothesis each example removes: globality needs convexity; uniqueness needs strict convexity or another identifying condition.', 'Nêu rõ mỗi ví dụ bỏ giả thiết nào: tính toàn cục cần lồi; tính duy nhất cần lồi nghiêm ngặt hoặc điều kiện nhận diện khác.']),
  L('m2-w062-e1', 'At the kink of an absolute-value penalty, list every supporting slope rather than trying to assign one ordinary derivative.', 'Tại góc gãy của penalty trị tuyệt đối, liệt kê mọi độ dốc đỡ thay vì cố gán một đạo hàm thông thường.', '∂f(x)={g: f(y)≥f(x)+g(y−x) for every y}; for f(x)=|x| at 0 this requires −1≤g≤1.', '∂f(x)={g: f(y)≥f(x)+g(y−x) với mọi y}; với f(x)=|x| tại 0 cần −1≤g≤1.', ['Insert x=0 into the defining support inequality and split test points into y>0 and y<0.', 'Thế x=0 vào bất đẳng thức đỡ và tách điểm thử thành y>0 và y<0.'], ['For y>0, cancel y to get the upper bound on g; for y<0, divide by a negative y carefully to get the lower bound.', 'Với y>0, rút g để được cận trên; với y<0, chia cho y âm cẩn thận để được cận dưới.'], ['Check every g in the resulting interval against both signs of y, proving sufficiency as well as necessity.', 'Kiểm tra mọi g trong khoảng thu được với cả hai dấu của y, chứng minh cả tính đủ lẫn tính cần.']),
  L('m2-w062-e2', 'A scalar estimate trades squared error against a three-times-absolute-value sparsity cost; the kink can pin the optimum exactly at zero.', 'Ước lượng vô hướng cân bằng sai số bình phương với penalty thưa bằng ba lần trị tuyệt đối; góc gãy có thể ghim nghiệm đúng tại không.', 'For convex f, x* minimizes f iff 0∈∂f(x*); here ∂[3|x|+½(x−1)²]=3∂|x|+(x−1).', 'Với f lồi, x* cực tiểu khi và chỉ khi 0∈∂f(x*); ở đây ∂[3|x|+½(x−1)²]=3∂|x|+(x−1).', ['Analyze x>0 and x<0 separately so the absolute-value slope is explicit on each smooth branch.', 'Xét riêng x>0 và x<0 để độ dốc của trị tuyệt đối tường minh trên từng nhánh trơn.'], ['At x=0, use ∂|0|=[−1,1] and add the quadratic derivative; test whether zero belongs to this interval.', 'Tại x=0, dùng ∂|0|=[−1,1] và cộng đạo hàm phần bậc hai; kiểm tra khoảng có chứa không.'], ['The quadratic contributes strict convexity, so a valid zero-subgradient certificate identifies the unique minimizer.', 'Phần bậc hai tạo lồi nghiêm ngặt, nên chứng chỉ dưới-gradient chứa không xác định nghiệm duy nhất.']),
  L('m2-w062-e3', 'A piecewise-linear cost is the larger of two affine quotes; its kink occurs where the active quote switches.', 'Chi phí tuyến tính từng khúc là giá trị lớn hơn của hai báo giá affine; điểm gãy xuất hiện nơi báo giá đang hoạt động đổi.', 'For f(x)=max_j(a_jx+b_j), ∂f(x) is the convex hull of slopes a_j for branches active at x.', 'Với f(x)=max_j(a_jx+b_j), ∂f(x) là bao lồi của các độ dốc a_j thuộc nhánh hoạt động tại x.', ['Solve equality of the two affine pieces to locate the switching point and evaluate their common value there.', 'Giải phương trình bằng nhau của hai nhánh affine để tìm điểm chuyển và tính giá trị chung tại đó.'], ['Determine which branch is larger on either side; only active slopes enter the subdifferential.', 'Xác định nhánh nào lớn hơn ở mỗi phía; chỉ độ dốc nhánh hoạt động mới vào dưới-gradient.'], ['Take all convex combinations of the two active slopes and verify each supports the maximum function at the kink.', 'Lấy mọi tổ hợp lồi của hai độ dốc đang hoạt động và kiểm tra chúng đều đỡ hàm max tại điểm gãy.']),
  L('m2-w062-e4', 'Minimizing |x| while x must lie in [2,5] puts the solution at the left endpoint, where the constraint supplies the missing opposing force.', 'Cực tiểu |x| với x∈[2,5] nằm tại đầu trái; ràng buộc cung cấp lực đối kháng còn thiếu.', 'For convex C, the constrained certificate is 0∈∂f(x*)+N_C(x*), where N_C(x*)={v:v(y−x*)≤0 for all y∈C}.', 'Với C lồi, chứng chỉ có ràng buộc là 0∈∂f(x*)+N_C(x*), với N_C(x*)={v:v(y−x*)≤0 với mọi y∈C}.', ['Identify x*=2 from monotonicity of |x| on positive x and compute the function subgradient there.', 'Dựa vào tính tăng của |x| trên miền dương để tìm x*=2 rồi tính dưới-gradient của hàm tại đó.'], ['Derive the normal cone at the left endpoint directly from v(y−2)≤0 for every y∈[2,5].', 'Suy nón pháp tuyến tại đầu trái trực tiếp từ v(y−2)≤0 với mọi y∈[2,5].'], ['Choose a normal vector canceling the function slope; explain why the unconstrained test 0∈∂f alone is inappropriate.', 'Chọn vector pháp tuyến triệt tiêu độ dốc hàm; giải thích vì sao điều kiện không ràng buộc 0∈∂f không phù hợp.']),
  L('m2-w062-e5', 'An absolute-value objective reaches its minimum at a nondifferentiable kink, so a derivative-equals-zero search misses the relevant point.', 'Hàm mục tiêu trị tuyệt đối đạt cực tiểu tại góc không khả vi, nên tìm nghiệm đạo hàm bằng không sẽ bỏ sót điểm cần tìm.', 'The subgradient rule is 0∈∂f(x*); for |x|, ∂f(x)={1} if x>0, {−1} if x<0, and [−1,1] at 0.', 'Quy tắc dưới-gradient là 0∈∂f(x*); với |x|, ∂f(x)={1} nếu x>0, {−1} nếu x<0, và [−1,1] tại 0.', ['Locate the minimum by comparing |x| on both sides of zero, then note that the ordinary derivative is undefined at the candidate.', 'Tìm cực tiểu bằng cách so sánh |x| ở hai phía số không, rồi lưu ý đạo hàm thông thường không xác định tại ứng viên.'], ['Compute the subdifferential separately on x<0, x>0, and the kink x=0.', 'Tính dưới-gradient riêng trên x<0, x>0 và tại góc x=0.'], ['Use inclusion of zero at the kink as the correct optimality certificate; away from it the singleton slope excludes zero.', 'Dùng việc khoảng dưới-gradient tại góc chứa không làm chứng chỉ tối ưu; ngoài đó độ dốc đơn trị không chứa không.']),
  L('m2-w063-e1', 'The conjugate converts a positive-curvature quadratic cost into a quadratic price function by optimizing over the original decision x.', 'Liên hợp biến chi phí quadratic có độ cong dương thành hàm giá quadratic bằng cách tối ưu theo quyết định gốc x.', 'f*(y)=sup_x(yx−f(x)); for f(x)=½ax² with a>0, the unique maximizer solves y=ax.', 'f*(y)=sup_x(yx−f(x)); với f(x)=½ax², a>0, điểm cực đại duy nhất giải y=ax.', ['Differentiate the concave expression yx−½ax² and use a>0 to verify its stationary point is the global maximizer.', 'Lấy đạo hàm biểu thức lõm yx−½ax² và dùng a>0 để xác nhận điểm dừng là cực đại toàn cục.'], ['Substitute x=y/a into the supremum and simplify without losing the factor one-half.', 'Thế x=y/a vào supremum và rút gọn, giữ đúng hệ số một phần hai.'], ['Check Fenchel–Young equality: it holds exactly when y∈∂f(x), here y=ax.', 'Kiểm tra đẳng thức Fenchel–Young: đẳng thức đúng khi y∈∂f(x), ở đây là y=ax.']),
  L('m2-w063-e2', 'An indicator cost forbids choices outside [−1,2]; its conjugate reports the greatest linear payoff over the allowed interval.', 'Chi phí chỉ thị cấm chọn ngoài [−1,2]; liên hợp cho payoff tuyến tính lớn nhất trên khoảng được phép.', 'δ_C*(y)=sup_{x∈C}yx=σ_C(y); for C=[−1,2], the maximizing endpoint depends on the sign of y.', 'δ_C*(y)=sup_{x∈C}yx=σ_C(y); với C=[−1,2], đầu mút tối ưu phụ thuộc dấu của y.', ['For y<0, the linear objective decreases with x, so inspect the left endpoint; for y>0 inspect the right endpoint.', 'Với y<0, mục tiêu tuyến tính giảm theo x nên xét đầu trái; với y>0 xét đầu phải.'], ['At y=0 every feasible x ties with payoff zero; state this case separately.', 'Tại y=0 mọi x khả thi cùng có payoff không; nêu riêng trường hợp này.'], ['Combine the three cases into the support-function expression and keep the domain C explicit.', 'Gộp ba trường hợp thành biểu thức hàm support và giữ miền C tường minh.']),
  L('m2-w063-e3', 'The absolute-value penalty has a conjugate that acts as a hard dual constraint: prices outside the unit interval have unbounded payoff.', 'Penalty trị tuyệt đối có liên hợp hoạt động như ràng buộc dual cứng: giá ngoài khoảng đơn vị tạo payoff vô hạn.', 'f*(y)=sup_x(yx−|x|)=0 for |y|≤1 and +∞ for |y|>1, so f*=δ_[−1,1].', 'f*(y)=sup_x(yx−|x|)=0 khi |y|≤1 và +∞ khi |y|>1, nên f*=δ_[−1,1].', ['Split the supremum into x≥0 and x≤0; each branch is linear in x with slope y−1 or y+1.', 'Tách supremum thành x≥0 và x≤0; mỗi nhánh tuyến tính theo x với hệ số y−1 hoặc y+1.'], ['When both slopes point toward a finite maximum, x=0 gives value zero; determine the exact y interval.', 'Khi cả hai hệ số cho cực đại hữu hạn, x=0 cho giá trị không; xác định chính xác khoảng y.'], ['Outside that interval choose x with matching sign and send its magnitude to infinity to prove the conjugate is infinite.', 'Ngoài khoảng ấy, chọn x cùng dấu rồi cho độ lớn tiến vô hạn để chứng minh liên hợp bằng vô hạn.']),
  L('m2-w063-e4', 'A dual vector q prices the linear map Ax; applying Fenchel–Young to both component costs cancels the price paid through Ax.', 'Vector dual q định giá ánh xạ Ax; áp dụng Fenchel–Young cho hai chi phí thành phần làm triệt tiêu giá qua Ax.', 'f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q) for every x,q; equality requires the matching subgradient conditions.', 'f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q) với mọi x,q; đẳng thức cần các điều kiện dưới-gradient tương ứng.', ['Apply Fenchel–Young to f at x with dual argument −Aᵀq, keeping the negative sign attached to the adjoint.', 'Áp Fenchel–Young cho f tại x với đối số dual −Aᵀq, giữ đúng dấu âm của chuyển vị liên hợp.'], ['Apply it again to g at Ax with dual argument q; write both inequalities before combining.', 'Áp dụng lần nữa cho g tại Ax với đối số dual q; viết riêng hai bất đẳng thức trước khi cộng.'], ['Add the inequalities so −qᵀAx and qᵀAx cancel; distinguish the resulting lower bound from strong duality or attainment.', 'Cộng hai bất đẳng thức để −qᵀAx và qᵀAx triệt tiêu; phân biệt cận dưới thu được với đối ngẫu mạnh hay tính đạt được.']),
  L('m2-w063-e5', 'If x must be nonnegative, the conjugate of its indicator blocks positive dual slopes entirely, unlike a soft finite quadratic price.', 'Nếu x phải không âm, liên hợp của chỉ thị miền này chặn hoàn toàn độ dốc dual dương, khác penalty quadratic hữu hạn.', 'For f=δ_[0,∞), f*(y)=sup_{x≥0}yx equals 0 for y≤0 and +∞ for y>0.', 'Với f=δ_[0,∞), f*(y)=sup_{x≥0}yx bằng 0 khi y≤0 và +∞ khi y>0.', ['Use x=0 as a feasible baseline, then test the sign of y in the linear objective.', 'Dùng x=0 làm mốc khả thi rồi xét dấu y trong mục tiêu tuyến tính.'], ['For y≤0, increasing x cannot improve on zero; for y>0, let x grow without bound.', 'Với y≤0, tăng x không thể vượt giá trị không; với y>0, cho x tăng không giới hạn.'], ['Compare domains of finite conjugate values: the indicator creates an exact dual feasibility set, while a quadratic remains finite everywhere.', 'So sánh miền có liên hợp hữu hạn: chỉ thị tạo tập khả thi dual chính xác, còn quadratic hữu hạn ở mọi nơi.']),
  L('m2-w064-e1', 'A decision x is constrained to be nonnegative while its unconstrained quadratic target is −1, so the optimum lies at the boundary.', 'Quyết định x bị buộc không âm trong khi đích quadratic không ràng buộc là −1, nên nghiệm nằm trên biên.', 'For g(x)=−x≤0, KKT requires stationarity f′(x)+λg′(x)=0, feasibility, λ≥0, and λg(x)=0.', 'Với g(x)=−x≤0, KKT cần f′(x)+λg′(x)=0, tính khả thi, λ≥0 và λg(x)=0.', ['Compare the unconstrained minimizer with x≥0 to identify the active boundary candidate.', 'So sánh cực tiểu không ràng buộc với điều kiện x≥0 để xác định ứng viên biên hoạt động.'], ['Write g=−x and compute f′ and g′; solve stationarity at the candidate for λ.', 'Viết g=−x rồi tính f′, g′; giải điều kiện dừng tại ứng viên để tìm λ.'], ['Check primal feasibility, dual sign and complementary slackness; convexity makes the full KKT certificate sufficient.', 'Kiểm tra khả thi primal, dấu dual và complementary slackness; tính lồi làm chứng chỉ KKT đầy đủ trở thành điều kiện đủ.']),
  L('m2-w064-e2', 'For one convex inequality plus a linear equality, KKT multipliers transform a feasible comparison into a nonnegative objective difference.', 'Với một bất đẳng thức lồi và một đẳng thức tuyến tính, multiplier KKT biến so sánh khả thi thành chênh lệch mục tiêu không âm.', 'Use f(y)≥f(x*)+∇f(x*)ᵀ(y−x*) and stationarity ∇f=−λ∇g−Aᵀν, with λ≥0.', 'Dùng f(y)≥f(x*)+∇f(x*)ᵀ(y−x*) và stationarity ∇f=−λ∇g−Aᵀν, với λ≥0.', ['Start from the first-order convex lower bound for any feasible y, then substitute the KKT stationarity equation.', 'Bắt đầu từ cận dưới lồi bậc nhất với y khả thi tùy ý, rồi thế phương trình stationarity KKT.'], ['Use Ay=Ax*=b to cancel the equality-multiplier term exactly; ν has no sign restriction.', 'Dùng Ay=Ax*=b để triệt tiêu đúng hạng tử multiplier đẳng thức; ν không cần giới hạn dấu.'], ['Apply convexity of g and g(y)≤0, then use λ≥0 to sign the inequality term; complementary slackness makes its value at x* vanish.', 'Áp tính lồi của g và g(y)≤0, rồi dùng λ≥0 để xác định dấu hạng tử; complementary slackness làm giá trị tại x* bằng không.']),
  L('m2-w064-e3', 'Projecting c=(2,−1) onto x₁≤1 and x₂≥0 clips each violated coordinate to its nearest feasible boundary.', 'Chiếu c=(2,−1) lên miền x₁≤1, x₂≥0 đưa từng tọa độ vi phạm về biên khả thi gần nhất.', 'Projection minimizes ½||x−c||²; with g₁=x₁−1≤0,g₂=−x₂≤0, stationarity is x−c+λ₁∇g₁+λ₂∇g₂=0.', 'Phép chiếu cực tiểu ½||x−c||²; với g₁=x₁−1≤0,g₂=−x₂≤0, stationarity là x−c+λ₁∇g₁+λ₂∇g₂=0.', ['Project coordinatewise onto (−∞,1]×[0,∞) to obtain the candidate and mark which constraints bind.', 'Chiếu từng tọa độ lên (−∞,1]×[0,∞) để tìm ứng viên và đánh dấu ràng buộc nào chặt.'], ['Use gradients (1,0) and (0,−1) in stationarity; solve the two coordinates for λ₁,λ₂.', 'Dùng gradient (1,0) và (0,−1) trong stationarity; giải hai tọa độ để tìm λ₁,λ₂.'], ['Verify nonnegative multipliers, active-constraint equalities and zero products λᵢgᵢ; invoke convex sufficiency.', 'Kiểm tra multiplier không âm, đẳng thức ràng buộc hoạt động và tích λᵢgᵢ bằng không; dùng tính đủ lồi.']),
  L('m2-w064-e4', 'The constraint x²≤0 leaves only x=0, but its gradient is also zero there, so the objective slope cannot be balanced by a finite multiplier.', 'Ràng buộc x²≤0 chỉ cho phép x=0, nhưng gradient ràng buộc cũng bằng không tại đó nên không multiplier hữu hạn nào cân bằng được độ dốc mục tiêu.', 'KKT stationarity is f′(x)+λg′(x)=0; Slater requires some x with g(x)<0, which is impossible for g(x)=x².', 'Stationarity KKT là f′(x)+λg′(x)=0; Slater cần có x thỏa g(x)<0, điều bất khả thi với g(x)=x².', ['Infer feasibility directly from x²≤0 and establish the sole feasible point is therefore optimal.', 'Suy trực tiếp từ x²≤0 để thấy điểm khả thi duy nhất, do đó cũng là nghiệm tối ưu.'], ['Evaluate f′ and g′ at zero and test the stationarity equation for any λ; isolate the contradiction.', 'Tính f′, g′ tại không và thử phương trình stationarity với mọi λ; chỉ ra mâu thuẫn.'], ['Check Slater fails, and distinguish “any KKT point is sufficient” from the separate existence of multipliers at an optimizer.', 'Kiểm tra Slater thất bại và phân biệt “điểm KKT nào cũng đủ tối ưu” với việc nghiệm tối ưu có multiplier.']),
  L('m2-w064-e5', 'A redundant always-satisfied inequality can have zero multiplier at a feasible point even when the objective is still descending.', 'Bất đẳng thức dư luôn thỏa có thể có multiplier bằng không tại điểm khả thi dù mục tiêu vẫn đang giảm.', 'Complementary slackness λg(x)=0 alone does not imply stationarity; a convex optimum needs the full KKT system under a valid qualification.', 'Chỉ complementary slackness λg(x)=0 không suy ra stationarity; nghiệm lồi cần toàn bộ hệ KKT dưới một qualification phù hợp.', ['Choose the constant constraint g(x)=−1 and verify it is feasible for every x; set λ=0.', 'Chọn ràng buộc hằng g(x)=−1 và kiểm tra nó khả thi với mọi x; đặt λ=0.'], ['At x=0, compute the objective derivative for (x−2)² and check it is nonzero.', 'Tại x=0, tính đạo hàm mục tiêu (x−2)² và kiểm tra khác không.'], ['Compare its objective value with x=2 to disprove optimality; name stationarity as the missing KKT condition.', 'So sánh giá trị mục tiêu với x=2 để bác bỏ tối ưu; nêu stationarity là điều kiện KKT còn thiếu.']),
  L('m2-w065-e1', 'A scalar decision must exceed two; dualizing that lower bound produces a concave quadratic lower-bound function to maximize.', 'Quyết định vô hướng phải ít nhất bằng hai; dual hóa cận dưới tạo hàm cận dưới quadratic lõm để cực đại.', 'For g(x)=2−x≤0, q(λ)=inf_x[½x²+λ(2−x)]=2λ−½λ², λ≥0.', 'Với g(x)=2−x≤0, q(λ)=inf_x[½x²+λ(2−x)]=2λ−½λ², λ≥0.', ['Write the Lagrangian with λ≥0 and minimize it over unrestricted x by setting its derivative to zero.', 'Viết Lagrangian với λ≥0 rồi cực tiểu theo x tự do bằng cách cho đạo hàm bằng không.'], ['Substitute the minimizing x back into L to get q(λ), then maximize the concave scalar function on λ≥0.', 'Thế x tối ưu ngược vào L để được q(λ), rồi cực đại hàm lõm trên λ≥0.'], ['Solve the primal boundary problem and compare p* with d*; equality certifies zero gap for this instance.', 'Giải bài toán primal tại biên rồi so p* với d*; bằng nhau chứng nhận gap bằng không ở ví dụ này.']),
  L('m2-w065-e2', 'Dual multipliers price inequality constraints, while equality multipliers can have either sign because every feasible point makes the equality residual zero.', 'Multiplier dual định giá ràng buộc bất đẳng thức, còn multiplier đẳng thức nhận mọi dấu vì residual đẳng thức luôn bằng không trên điểm khả thi.', 'For λ≥0 and feasible x, L(x,λ,ν)=f₀(x)+λᵀg(x)+νᵀ(Ax−b)≤f₀(x); q(λ,ν)=inf_z L(z,λ,ν).', 'Với λ≥0 và x khả thi, L(x,λ,ν)=f₀(x)+λᵀg(x)+νᵀ(Ax−b)≤f₀(x); q(λ,ν)=inf_z L(z,λ,ν).', ['At an arbitrary feasible x, sign each term: λᵢgᵢ(x)≤0 and νᵀ(Ax−b)=0 for any real ν.', 'Với x khả thi tùy ý, xác định dấu từng hạng: λᵢgᵢ(x)≤0 còn νᵀ(Ax−b)=0 với mọi ν thực.'], ['Use the infimum over z to get q≤L(x,λ,ν)≤f₀(x), then take the primal infimum.', 'Dùng infimum theo z để có q≤L(x,λ,ν)≤f₀(x), rồi lấy infimum primal.'], ['Explain that ν is unrestricted because its term vanishes on feasibility, whereas a negative λ could reverse the inequality bound.', 'Giải thích ν tự do vì hạng tử biến mất khi khả thi, còn λ âm có thể đảo chiều bất đẳng thức.']),
  L('m2-w065-e3', 'Raising the required minimum x from u to a larger value raises the best achievable quadratic cost; the active multiplier equals this marginal cost.', 'Tăng mức sàn x từ u lên cao làm chi phí quadratic nhỏ nhất tăng; multiplier đang hoạt động bằng chi phí biên này.', 'For u>0, p*(u)=min_{x≥u}½x²=u²/2 and dp*/du=u; with g=u−x≤0, stationarity gives λ*=u.', 'Với u>0, p*(u)=min_{x≥u}½x²=u²/2 và dp*/du=u; với g=u−x≤0, stationarity cho λ*=u.', ['Since the unconstrained minimizer zero violates x≥u, identify the active solution x*=u.', 'Vì nghiệm không ràng buộc bằng không vi phạm x≥u, xác định nghiệm hoạt động x*=u.'], ['Substitute into the objective to obtain the value function, then differentiate with respect to u.', 'Thế vào mục tiêu để được hàm giá trị, rồi lấy đạo hàm theo u.'], ['Write KKT stationarity for g=u−x and compare λ* with dp*/du; state the active-regime assumption u>0.', 'Viết stationarity KKT cho g=u−x rồi so λ* với dp*/du; nêu giả thiết miền hoạt động u>0.']),
  L('m2-w065-e4', 'A feasible operating point plus any dual-feasible prices yield a certified lower bound even before the unknown primal optimizer is found.', 'Một điểm vận hành khả thi cộng với giá dual khả thi tạo cận dưới được chứng nhận trước khi biết nghiệm primal.', 'Weak duality gives q(λ,ν)≤p*≤f₀(x) for every feasible x and every dual-feasible (λ,ν).', 'Đối ngẫu yếu cho q(λ,ν)≤p*≤f₀(x) với mọi x khả thi và mọi (λ,ν) dual khả thi.', ['Keep the primal feasibility check separate from the dual multiplier sign/domain check.', 'Tách kiểm tra khả thi primal khỏi kiểm tra dấu/miền multiplier dual.'], ['Apply weak duality to bracket the optimum between dual value and feasible primal value.', 'Áp dụng đối ngẫu yếu để kẹp tối ưu giữa giá trị dual và giá trị primal khả thi.'], ['If the two computed values agree, conclude both candidates are optimal and the gap is zero; no search-history assumption is needed.', 'Nếu hai giá trị tính được bằng nhau, kết luận cả hai ứng viên tối ưu và gap bằng không; không cần giả thiết về cách tìm.']),
  L('m2-w065-e5', 'The feasible set x²≤0 contains only zero, yet the dual lower bounds approach the primal value only as λ tends to infinity.', 'Tập khả thi x²≤0 chỉ có không, nhưng cận dual chỉ tiến tới giá trị primal khi λ tiến vô hạn.', 'For L=−x+λx², q(λ)=−1/(4λ) for λ>0 and q(0)=−∞; d*=sup_{λ≥0}q(λ)=0=p*, unattained.', 'Với L=−x+λx², q(λ)=−1/(4λ) khi λ>0 và q(0)=−∞; d*=sup_{λ≥0}q(λ)=0=p*, nhưng không đạt.', ['Use x²≤0 to calculate p* directly, then minimize the Lagrangian quadratic over x for λ>0.', 'Dùng x²≤0 để tính p* trực tiếp, rồi cực tiểu quadratic Lagrangian theo x khi λ>0.'], ['Handle λ=0 separately because the linear function −x has infimum −∞.', 'Xét riêng λ=0 vì hàm tuyến tính −x có infimum −∞.'], ['Take λ→∞ to identify the dual supremum and distinguish unattained equality from a positive primal-dual value gap.', 'Cho λ→∞ để tìm supremum dual và phân biệt đẳng thức không đạt với gap giá trị dương.']),
  L('m2-w066-e1', 'A one-step gradient update on a one-dimensional quadratic can be checked against a theorem’s guaranteed decrease.', 'Một bước gradient trên quadratic một chiều có thể kiểm tra trực tiếp với mức giảm định lý bảo đảm.', 'For L-smooth f, f(x−∇f(x)/L)≤f(x)−||∇f(x)||²/(2L); here ∇f=6x−6.', 'Với f trơn L, f(x−∇f(x)/L)≤f(x)−||∇f(x)||²/(2L); ở đây ∇f=6x−6.', ['Evaluate the derivative at x₀=0, then apply the prescribed η=1/L update rather than guessing a step.', 'Tính đạo hàm tại x₀=0 rồi áp dụng bước η=1/L đã cho, không tự chọn bước.'], ['Substitute x₁ into f and calculate actual decrease f(x₀)−f(x₁).', 'Thế x₁ vào f và tính độ giảm thực tế f(x₀)−f(x₁).'], ['Compute the certificate ||∇f(x₀)||²/(2L) and compare; explain why equality here is a fixture-specific tight case.', 'Tính chứng chỉ ||∇f(x₀)||²/(2L) rồi so sánh; giải thích đây là trường hợp chặt của ví dụ cụ thể.']),
  L('m2-w066-e2', 'To bound the change in a smooth objective between two points, integrate its directional derivative along the straight path.', 'Để chặn biến thiên của hàm trơn giữa hai điểm, tích phân đạo hàm theo hướng dọc đường thẳng nối chúng.', 'If ∇f is L-Lipschitz and d=y−x, f(y)≤f(x)+∇f(x)ᵀd+(L/2)||d||².', 'Nếu ∇f Lipschitz hằng L và d=y−x, f(y)≤f(x)+∇f(x)ᵀd+(L/2)||d||².', ['Define φ(t)=f(x+td); the fundamental theorem of calculus expresses the remainder as an integral of gradient differences.', 'Đặt φ(t)=f(x+td); định lý cơ bản của giải tích biểu diễn phần dư bằng tích phân hiệu gradient.'], ['Apply Cauchy–Schwarz and Lipschitz continuity to bound the integrand by Lt||d||².', 'Áp dụng Cauchy–Schwarz và tính Lipschitz để chặn tích phân bởi Lt||d||².'], ['Integrate t from 0 to 1, producing L||d||²/2; specify continuous differentiability and global Lipschitz-gradient assumptions.', 'Tích phân t từ 0 đến 1 để được L||d||²/2; nêu giả thiết khả vi liên tục và gradient Lipschitz toàn cục.']),
  L('m2-w066-e3', 'For a quadratic with diagonal curvature 1 and 9, one shared gradient step must serve both the shallow and steep directions.', 'Quadratic có độ cong chéo 1 và 9 buộc cùng một bước gradient phải phục vụ cả hướng thoải lẫn hướng dốc.', 'For f(x)=½xᵀQx with Q≻0, μ=λmin(Q), L=λmax(Q), and κ=L/μ.', 'Với f(x)=½xᵀQx, Q≻0, μ=λmin(Q), L=λmax(Q), κ=L/μ.', ['Read the extreme eigenvalues from Q=diag(1,9) to identify the strong-convexity and smoothness constants.', 'Đọc trị riêng cực trị từ Q=diag(1,9) để tìm hằng số lồi mạnh và trơn.'], ['Compute κ and compare axis curvature; the ellipse axis-length ratio is √κ.', 'Tính κ và so độ cong theo trục; tỷ lệ độ dài trục ellipse là √κ.'], ['Connect the steep-axis step restriction to slower motion on the shallow axis; do not confuse condition number with objective scale.', 'Liên hệ giới hạn bước theo trục dốc với chuyển động chậm trên trục thoải; không nhầm condition number với quy mô mục tiêu.']),
  L('m2-w066-e4', 'On a quadratic ridge objective, diagonalizing the Hessian turns the gradient update into independent scalar contractions along eigenvectors.', 'Trên mục tiêu ridge quadratic, chéo hóa Hessian biến cập nhật gradient thành co theo vô hướng độc lập dọc các vector riêng.', 'For μI⪯Q⪯LI and η=1/L, e⁺=(I−Q/L)e, whose eigenvalues lie in [0,1−μ/L].', 'Với μI⪯Q⪯LI và η=1/L, e⁺=(I−Q/L)e, có trị riêng thuộc [0,1−μ/L].', ['Write the error recurrence around the exact minimizer and diagonalize the symmetric Hessian Q.', 'Viết truy hồi sai số quanh nghiệm chính xác rồi chéo hóa Hessian đối xứng Q.'], ['Bound each eigen-coordinate multiplier 1−h_j/L between zero and 1−μ/L; μ≤L ensures the interval is valid.', 'Chặn hệ số từng tọa độ riêng 1−h_j/L từ không đến 1−μ/L; μ≤L bảo đảm khoảng hợp lệ.'], ['Square the norm contraction, then weight coordinates by h_j/2 to obtain objective-error contraction; limit the proof to the stated quadratic setting.', 'Bình phương co chuẩn rồi gắn trọng số h_j/2 cho từng tọa độ để được co sai số mục tiêu; giới hạn chứng minh trong trường hợp quadratic đã nêu.']),
  L('m2-w066-e5', 'A step size larger than the stable range flips the scalar iterate past the minimizer and increases its magnitude each round.', 'Bước lớn hơn miền ổn định làm iterate vô hướng vượt qua nghiệm và tăng độ lớn qua mỗi vòng.', 'For f(x)=½x², gradient descent obeys xₙ₊₁=(1−η)xₙ; descent requires |1−η|<1.', 'Với f(x)=½x², gradient descent tuân xₙ₊₁=(1−η)xₙ; giảm dần cần |1−η|<1.', ['Apply η=2.2 to x₀=1 to compute the first iterate and observe the sign reversal.', 'Áp η=2.2 cho x₀=1 để tính iterate đầu và thấy dấu bị đảo.'], ['Apply the same recurrence again; compare |xₙ| and f(xₙ)=xₙ²/2 across iterations.', 'Áp dụng truy hồi lần nữa; so sánh |xₙ| và f(xₙ)=xₙ²/2 qua các bước.'], ['Locate the failed step condition relative to L=1; smoothness of f does not compensate for violating η≤1/L.', 'Xác định điều kiện bước bị vi phạm so với L=1; độ trơn của f không bù được η>1/L.']),
  L('m2-w067-e1', 'For an ℓ1-regularized vector update, each coordinate is pulled toward zero by threshold γλ, with signs preserved outside the threshold.', 'Trong cập nhật vector có regularization ℓ1, mỗi tọa độ bị kéo về không với ngưỡng γλ và giữ dấu khi vượt ngưỡng.', 'prox_{τ||·||₁}(v)_j=sign(v_j)(|v_j|−τ)_+, where τ=γλ.', 'prox_{τ||·||₁}(v)_j=sign(v_j)(|v_j|−τ)_+, với τ=γλ.', ['Compute the common threshold τ=.5·2 before touching any coordinate.', 'Tính ngưỡng chung τ=.5·2 trước khi xử lý từng tọa độ.'], ['Compare each absolute coordinate to τ; values inside the threshold interval map to zero.', 'So sánh trị tuyệt đối từng tọa độ với τ; giá trị trong ngưỡng được đưa về không.'], ['For surviving coordinates subtract τ from the magnitude and restore the original sign; preserve coordinate order.', 'Với tọa độ còn lại, trừ τ khỏi độ lớn rồi giữ dấu ban đầu; giữ đúng thứ tự tọa độ.']),
  L('m2-w067-e2', 'A proximal update chooses the point balancing h(x) against squared distance from a proposal v; optimality equates that distance force with a subgradient.', 'Bước proximal chọn điểm cân bằng h(x) với khoảng cách bình phương tới đề xuất v; điều kiện tối ưu cân bằng lực khoảng cách với dưới-gradient.', 'prox_{γh}(v)=argmin_x[h(x)+||x−v||²/(2γ)]; differentiable case gives v−x=γ∇h(x), convex nonsmooth case (v−x)/γ∈∂h(x).', 'prox_{γh}(v)=argmin_x[h(x)+||x−v||²/(2γ)]; trường hợp khả vi cho v−x=γ∇h(x), trường hợp lồi không trơn cho (v−x)/γ∈∂h(x).', ['Write the proximal objective and differentiate its quadratic distance term with the correct factor 1/γ.', 'Viết mục tiêu proximal và lấy đạo hàm hạng khoảng cách quadratic với đúng hệ số 1/γ.'], ['Set the gradient to zero in the differentiable case and rearrange to isolate v−x.', 'Cho gradient bằng không trong trường hợp khả vi rồi biến đổi để tách v−x.'], ['Replace gradient by the convex subdifferential inclusion for nonsmooth h; proper closed convexity ensures the optimality condition applies.', 'Thay gradient bằng bao hàm dưới vi phân lồi khi h không trơn; tính lồi đóng proper bảo đảm điều kiện tối ưu áp dụng.']),
  L('m2-w067-e3', 'Comparing two proximal outputs reveals contraction: monotonicity of the same convex subdifferential couples the two input-output pairs.', 'So sánh hai đầu ra proximal cho thấy tính co: tính đơn điệu của cùng dưới vi phân lồi liên kết hai cặp đầu vào-đầu ra.', 'If x=prox_{γh}(u), y=prox_{γh}(v), then (u−x)/γ∈∂h(x), (v−y)/γ∈∂h(y), implying ||x−y||²≤(x−y)ᵀ(u−v).', 'Nếu x=prox_{γh}(u), y=prox_{γh}(v), thì (u−x)/γ∈∂h(x), (v−y)/γ∈∂h(y), suy ra ||x−y||²≤(x−y)ᵀ(u−v).', ['Write both proximal inclusions before combining them; keep the common positive γ visible.', 'Viết cả hai bao hàm proximal trước khi kết hợp; giữ γ dương chung tường minh.'], ['Add the two subgradient support inequalities to obtain monotonicity: (a−b)ᵀ(x−y)≥0.', 'Cộng hai bất đẳng thức đỡ dưới-gradient để được đơn điệu: (a−b)ᵀ(x−y)≥0.'], ['Substitute a,b and rearrange; use Cauchy–Schwarz afterward to obtain ordinary nonexpansiveness if desired.', 'Thế a,b rồi biến đổi; sau đó có thể dùng Cauchy–Schwarz để suy tính không giãn thông thường.']),
  L('m2-w067-e4', 'The proximal map of a nonnegative-domain indicator is simply projection onto the half-line, and its subgradient is the endpoint normal cone.', 'Proximal map của chỉ thị miền không âm chính là phép chiếu lên nửa trục; dưới-gradient tại đầu mút là nón pháp tuyến.', 'prox_{γδ_C}(v)=Π_C(v)=max(v,0); ∂δ_C(x)=N_C(x).', 'prox_{γδ_C}(v)=Π_C(v)=max(v,0); ∂δ_C(x)=N_C(x).', ['Minimize the squared distance over x≥0: the unconstrained proposal is retained if feasible, otherwise use the nearest endpoint.', 'Cực tiểu khoảng cách bình phương trên x≥0: giữ đề xuất nếu khả thi, nếu không dùng đầu mút gần nhất.'], ['If v≥0, x=v and the scaled residual (v−x)/γ is zero in the interior normal cone.', 'Nếu v≥0, x=v và residual chia γ bằng không, thuộc nón pháp tuyến nội.'], ['If v<0, x=0 and v/γ≤0 belongs to N_[0,∞)(0); verify the inclusion in both cases.', 'Nếu v<0, x=0 và v/γ≤0 thuộc N_[0,∞)(0); kiểm tra bao hàm ở cả hai trường hợp.']),
  L('m2-w067-e5', 'A nonconvex double-well proximal objective can have two equally close minimizers, so its “map” becomes set-valued.', 'Mục tiêu proximal hai đáy không lồi có thể có hai nghiệm bằng nhau, khiến “ánh xạ” thành đa trị.', 'For h(x)=−|x|, γ=1,v=0, minimize −|x|+x²/2; convex firm-nonexpansive proofs require monotone subgradients.', 'Với h(x)=−|x|, γ=1,v=0, cực tiểu −|x|+x²/2; chứng minh firm nonexpansive lồi cần dưới-gradient đơn điệu.', ['Split at x=0 and rewrite each branch as a completed square.', 'Tách tại x=0 và viết mỗi nhánh bằng cách hoàn thành bình phương.'], ['Find the minimizer on each half-line and compare the two objective values to retain both global solutions.', 'Tìm cực tiểu trên mỗi nửa trục rồi so giá trị mục tiêu để giữ cả hai nghiệm toàn cục.'], ['Identify convexity as the missing premise: the subgradient monotonicity step used for firm nonexpansiveness no longer holds.', 'Chỉ ra tiền đề thiếu là tính lồi: bước đơn điệu của dưới-gradient dùng cho firm nonexpansive không còn đúng.']),
  L('m2-w068-e1', 'A projected-gradient learner has a diameter/noise tradeoff: choose η to balance its initial-distance term against accumulated gradient noise.', 'Learner gradient có chiếu có đánh đổi giữa đường kính và nhiễu: chọn η để cân bằng khoảng cách đầu với nhiễu gradient tích lũy.', 'B(η)=D²/(2η)+ηG²T/2 is minimized at η*=D/(G√T), giving cumulative DG√T and average DG/√T.', 'B(η)=D²/(2η)+ηG²T/2 đạt min tại η*=D/(G√T), cho cận tổng DG√T và trung bình DG/√T.', ['Differentiate B with respect to η and set its derivative to zero; check the positive solution is the minimum.', 'Lấy đạo hàm B theo η rồi cho bằng không; kiểm tra nghiệm dương là cực tiểu.'], ['Substitute D=3,G=2,T=100 to compute η*, then evaluate each bound term separately.', 'Thế D=3,G=2,T=100 để tính η*, rồi tính riêng từng hạng cận.'], ['Divide the cumulative bound by T for average excess; keep units and distinguish the optimized guarantee from observed performance.', 'Chia cận tổng cho T để được excess trung bình; giữ đơn vị và phân biệt bảo đảm tối ưu với hiệu năng quan sát.']),
  L('m2-w068-e2', 'Projection keeps an iterate inside a feasible set while the squared distance to a feasible comparator serves as a potential.', 'Phép chiếu giữ iterate trong tập khả thi, còn khoảng cách bình phương tới comparator khả thi làm potential.', 'For p=Π_C(z), x*∈C: ||p−x*||²≤||z−x*||²; with z=x_t−ηg_t expand to ||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||².', 'Với p=Π_C(z), x*∈C: ||p−x*||²≤||z−x*||²; với z=x_t−ηg_t, khai triển thành ||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||².', ['Use the projection variational inequality (z−p)ᵀ(x*−p)≤0 for the feasible comparator.', 'Dùng bất đẳng thức biến phân phép chiếu (z−p)ᵀ(x*−p)≤0 cho comparator khả thi.'], ['Expand ||z−x*||² around p and sign the cross term via the variational inequality to prove distance cannot increase.', 'Khai triển ||z−x*||² quanh p và xác định dấu tích chéo theo bất đẳng thức biến phân để chứng minh khoảng cách không tăng.'], ['Substitute the stochastic-gradient proposal and expand the square; preserve the linear inner-product term needed in the regret sum.', 'Thế đề xuất gradient ngẫu nhiên rồi khai triển bình phương; giữ hạng tích vô hướng tuyến tính cần cho tổng regret.']),
  L('m2-w068-e3', 'A sampled gradient moves x₁=1.8 toward a comparator inside [0,2]; projection is checked before measuring the new potential.', 'Gradient lấy mẫu đưa x₁=1.8 về comparator trong [0,2]; cần kiểm tra phép chiếu trước khi đo potential mới.', 'x₂=Π_[0,2](x₁−ηg₁); potential V_t=|x_t−x*|².', 'x₂=Π_[0,2](x₁−ηg₁); potential V_t=|x_t−x*|².', ['Compute the tentative update 1.8−.4·3 and check whether it lies in [0,2].', 'Tính bước tạm 1.8−.4·3 rồi kiểm tra có thuộc [0,2] không.'], ['Apply projection only if the tentative value violates a boundary; here retain the feasible proposal.', 'Chỉ chiếu nếu giá trị tạm vi phạm biên; ở đây giữ nguyên đề xuất khả thi.'], ['Evaluate squared distance to .5 before and after; verify with the expanded potential identity using the supplied sampled gradient.', 'Tính khoảng cách bình phương tới .5 trước và sau; kiểm tra bằng đồng nhất thức potential khai triển với gradient đã cho.']),
  L('m2-w068-e4', 'A biased gradient oracle has a conditional drift bₜ; its inner product with the bounded comparator displacement adds a cumulative error.', 'Oracle gradient chệch có độ lệch có điều kiện bₜ; tích vô hướng với độ dịch chuyển comparator bị chặn tạo sai số tích lũy.', 'If E[gₜ|Fₜ]=∇f(xₜ)+bₜ, ||bₜ||≤β and ||xₜ−x*||≤D, then expected regret bound gains βDT (average βD).', 'Nếu E[gₜ|Fₜ]=∇f(xₜ)+bₜ, ||bₜ||≤β và ||xₜ−x*||≤D, cận regret kỳ vọng tăng βDT (trung bình βD).', ['Let dₜ=xₜ−x* and use convexity to upper-bound f(xₜ)−f(x*) by ∇f(xₜ)ᵀdₜ.', 'Đặt dₜ=xₜ−x* rồi dùng tính lồi chặn f(xₜ)−f(x*) bởi ∇f(xₜ)ᵀdₜ.'], ['Replace ∇f by E[gₜ|Fₜ]−bₜ; bound −bₜᵀdₜ with Cauchy–Schwarz by βD.', 'Thay ∇f bằng E[gₜ|Fₜ]−bₜ; dùng Cauchy–Schwarz chặn −bₜᵀdₜ bởi βD.'], ['Add βD each round to the standard potential total, then divide by T only if reporting average regret.', 'Cộng βD mỗi vòng vào cận potential chuẩn, rồi chỉ chia T nếu báo regret trung bình.']),
  L('m2-w068-e5', 'An oracle can be unbiased yet have an exploding second moment, so a theorem requiring a uniform gradient bound loses force.', 'Oracle có thể không chệch nhưng moment bậc hai bùng nổ, khiến định lý cần chặn gradient đều mất hiệu lực.', 'For g=M with probability 1/M and 0 otherwise, E[g]=1 but E[g²]=M; a uniform ||g||≤G assumption fails as M grows.', 'Với g=M xác suất 1/M và bằng 0 nếu khác, E[g]=1 nhưng E[g²]=M; giả thiết ||g||≤G đều thất bại khi M tăng.', ['Compute the oracle expectation and match it to the derivative f′(1)=1 to verify unbiasedness.', 'Tính kỳ vọng oracle rồi so với đạo hàm f′(1)=1 để xác nhận không chệch.'], ['Square the two possible oracle values before averaging; do not square the mean.', 'Bình phương hai giá trị oracle trước khi lấy trung bình; không bình phương trung bình.'], ['As M increases, identify which bound parameter must increase and explain why unbiasedness alone cannot ensure a uniform regret rate.', 'Khi M tăng, xác định tham số cận nào phải tăng và giải thích vì sao không chệch đơn thuần không đảm bảo rate regret đều.']),
  L('m2-w069-e1', 'A least-squares matrix with singular values 5, 1 and .01 amplifies errors along its weakest singular direction.', 'Ma trận bình phương tối thiểu có singular value 5, 1 và .01 khuếch đại sai số theo hướng singular yếu nhất.', 'κ₂(A)=σmax/σmin; for full column rank, κ₂(AᵀA)=κ₂(A)².', 'κ₂(A)=σmax/σmin; khi A đủ hạng cột, κ₂(AᵀA)=κ₂(A)².', ['Read σmax and σmin to compute κ₂(A) directly.', 'Đọc σmax và σmin để tính trực tiếp κ₂(A).'], ['Square both extreme singular values for AᵀA and recompute its spectral condition number.', 'Bình phương hai singular value cực trị cho AᵀA rồi tính condition number phổ.'], ['Compare the two results as an amplification ratio; note normal equations square the condition scale.', 'So hai kết quả như tỷ số khuếch đại; lưu ý phương trình chuẩn bình phương thang condition.']),
  L('m2-w069-e2', 'For full-column-rank least squares, the SVD exposes the eigenvalues of the normal matrix and makes the squared sensitivity exact.', 'Với least squares đủ hạng cột, SVD cho thấy trị riêng của ma trận chuẩn và làm rõ chính xác độ nhạy bị bình phương.', 'A=UΣVᵀ implies AᵀA=VΣ²Vᵀ, hence κ₂(AᵀA)=σmax²/σmin²=κ₂(A)² when σmin>0.', 'A=UΣVᵀ suy ra AᵀA=VΣ²Vᵀ, nên κ₂(AᵀA)=σmax²/σmin²=κ₂(A)² khi σmin>0.', ['Insert the SVD and use UᵀU=I to simplify AᵀA.', 'Thế SVD và dùng UᵀU=I để rút gọn AᵀA.'], ['Read eigenvalues of VΣ²Vᵀ as squared singular values of A.', 'Đọc trị riêng của VΣ²Vᵀ là bình phương singular value của A.'], ['State the full-column-rank condition; if σmin=0, the normal matrix is singular and its condition number is infinite.', 'Nêu điều kiện đủ hạng cột; nếu σmin=0 thì ma trận chuẩn suy biến và condition number vô hạn.']),
  L('m2-w069-e3', 'A tiny absolute residual for an ill-conditioned compatible solve cannot be interpreted until it is scaled by matrix, solution and data magnitudes.', 'Residual tuyệt đối nhỏ trong hệ tương thích kém điều kiện chưa thể diễn giải nếu chưa chuẩn hóa theo độ lớn ma trận, nghiệm và dữ liệu.', 'η=||Ax̂−b||/(||A||||x̂||+||b||); for fixed-A compatible solves, relative forward error is typically O(κ(A)η) when κ(A)η is small.', 'η=||Ax̂−b||/(||A||||x̂||+||b||); với hệ tương thích và A cố định, sai số tiến tương đối thường O(κ(A)η) khi κ(A)η nhỏ.', ['Compute or request the denominator before treating residual 10⁻⁸ as a backward-error measure.', 'Tính hoặc yêu cầu mẫu số trước khi coi residual 10⁻⁸ là thước đo backward error.'], ['Apply the condition-scaled relation only under its small-backward-error and compatible fixed-matrix setting.', 'Chỉ áp dụng quan hệ có condition khi backward error nhỏ và bài toán tương thích với ma trận cố định.'], ['For inconsistent least squares with perturbations in A, include residual-coupled sensitivity; stable QR/SVD avoids squaring κ but cannot erase intrinsic conditioning.', 'Với least squares không tương thích và A bị nhiễu, xét độ nhạy ghép residual; QR/SVD ổn định tránh bình phương κ nhưng không xóa conditioning nội tại.']),
  L('m2-w069-e4', 'When A=QR with orthonormal Q, only the projection of b into the column space affects the fitted coefficients; the orthogonal residual is constant.', 'Khi A=QR với Q trực chuẩn, chỉ phép chiếu b lên không gian cột ảnh hưởng hệ số fitted; residual vuông góc là hằng số.', '||QRx−b||²=||Rx−Qᵀb||²+||(I−QQᵀ)b||²; solve triangular R x=Qᵀb.', '||QRx−b||²=||Rx−Qᵀb||²+||(I−QQᵀ)b||²; giải tam giác R x=Qᵀb.', ['Orthogonally decompose b into QQᵀb and (I−QQᵀ)b; use QᵀQ=I to separate squared norms.', 'Phân rã trực giao b thành QQᵀb và (I−QQᵀ)b; dùng QᵀQ=I để tách tổng bình phương.'], ['The second term is independent of x, so minimize the first by matching Rx to Qᵀb.', 'Hạng tử thứ hai không phụ thuộc x, nên cực tiểu hạng đầu bằng cách cho Rx=Qᵀb.'], ['Use a triangular solve; explain that this avoids explicitly constructing AᵀA and its squared spectrum.', 'Dùng phép giải tam giác; giải thích cách này tránh dựng AᵀA và phổ bị bình phương.']),
  L('m2-w069-e5', 'With A=diag(1,ε), a residual of size ε can coexist with a unit parameter error because the second direction is weakly observed.', 'Với A=diag(1,ε), residual cỡ ε vẫn có thể đi với sai số tham số bằng một vì hướng thứ hai được quan sát yếu.', 'Exact x=A⁻¹b; for x̃=(1,0), ||Ax̃−b||=ε while ||x̃−x||=1 and κ₂(A)=1/ε.', 'Nghiệm chính xác x=A⁻¹b; với x̃=(1,0), ||Ax̃−b||=ε trong khi ||x̃−x||=1 và κ₂(A)=1/ε.', ['Solve each diagonal coordinate of Ax=b to find the exact parameter vector.', 'Giải từng tọa độ đường chéo của Ax=b để tìm vector tham số chính xác.'], ['Subtract b from A x̃ and take the residual norm; then separately compute x̃−x.', 'Lấy A x̃ trừ b và tính chuẩn residual; sau đó riêng tính x̃−x.'], ['Let ε→0 and explain the discrepancy through the vanishing singular value and diverging condition number.', 'Cho ε→0 và giải thích chênh lệch qua singular value tiến về không và condition number tăng vô hạn.']),
  L('m2-w070-e1', 'A measured gradient of norm .04 at an iterate can bound objective gap only when a global strong-curvature constant is known.', 'Gradient đo được có chuẩn .04 chỉ chặn được gap mục tiêu khi biết hằng số độ cong mạnh toàn cục.', 'If f is μ-strongly convex, f(x)−f*≤||∇f(x)||²/(2μ).', 'Nếu f lồi mạnh μ, f(x)−f*≤||∇f(x)||²/(2μ).', ['Record μ=.5 and the gradient norm as the exact inputs to the certificate.', 'Ghi μ=.5 và chuẩn gradient làm đầu vào chính xác của chứng chỉ.'], ['Square the gradient norm and divide by 2μ, keeping the gap units consistent with f.', 'Bình phương chuẩn gradient rồi chia 2μ, giữ đơn vị gap phù hợp với f.'], ['State the global strong-convexity premise; without it a small gradient need not certify distance in objective value.', 'Nêu tiền đề lồi mạnh toàn cục; thiếu nó thì gradient nhỏ không chứng nhận khoảng cách giá trị mục tiêu.']),
  L('m2-w070-e2', 'The gap theorem follows by maximizing a linear gradient term minus a quadratic curvature penalty over all possible displacements.', 'Định lý gap suy ra bằng cách cực đại hạng tuyến tính gradient trừ penalty độ cong quadratic trên mọi độ dịch chuyển.', 'Strong convexity gives gap≤aᵀd−(μ/2)||d||²≤||a||²/(2μ), where a=∇f(x), d=x−x*.', 'Lồi mạnh cho gap≤aᵀd−(μ/2)||d||²≤||a||²/(2μ), với a=∇f(x), d=x−x*.', ['Apply strong convexity at x with endpoint x* and rearrange to isolate f(x)−f(x*).', 'Áp lồi mạnh tại x với đầu cuối x* rồi biến đổi để tách f(x)−f(x*).'], ['Complete the square explicitly: center d at a/μ and retain the negative squared norm.', 'Hoàn thành bình phương tường minh: dời tâm d tại a/μ và giữ hạng chuẩn bình phương âm.'], ['Drop only the nonpositive square and use optimality f(x*)≤f(x); identify μ>0 as essential.', 'Chỉ bỏ hạng bình phương không dương và dùng tối ưu f(x*)≤f(x); nêu μ>0 là thiết yếu.']),
  L('m2-w070-e3', 'A KKT report for a nearly feasible two-variable iterate should preserve separate primal, dual, stationarity and complementarity diagnostics.', 'Báo cáo KKT cho iterate hai biến gần khả thi cần giữ riêng chẩn đoán primal, dual, stationarity và complementarity.', 'Primal residuals: max_i[g_i(x)]_+ and |Ax−b|; dual: max_i[−λ_i]_+; stationarity: ||∇f+Σλ_i∇g_i+Aᵀν||₂; complementarity: |λ_i g_i(x)|.', 'Residual primal: max_i[g_i(x)]_+ và |Ax−b|; dual: max_i[−λ_i]_+; stationarity: ||∇f+Σλ_i∇g_i+Aᵀν||₂; complementarity: |λ_i g_i(x)|.', ['Evaluate both inequality functions and the equality residual at x=(1.02,−.01); report violations separately.', 'Tính hai hàm bất đẳng thức và residual đẳng thức tại x=(1.02,−.01); báo riêng từng vi phạm.'], ['Check negative multiplier parts, then compute ∇f and each constraint gradient before assembling stationarity residual.', 'Kiểm tra phần multiplier âm rồi tính ∇f và gradient từng ràng buộc trước khi ghép residual stationarity.'], ['Multiply each λᵢ by its own gᵢ(x) for complementarity; do not collapse different units or residual types into one scalar.', 'Nhân từng λᵢ với đúng gᵢ(x) để tính complementarity; không gộp các đơn vị hay loại residual khác nhau thành một số.']),
  L('m2-w070-e4', 'An approximate gradient g-hat is uncertain by at most ε, so a valid certificate must include this oracle error before squaring.', 'Gradient xấp xỉ ĝ sai khác tối đa ε, nên chứng chỉ hợp lệ phải cộng sai số oracle trước khi bình phương.', '||∇f(x)||≤||ĝ||+ε, hence f(x)−f*≤(||ĝ||+ε)²/(2μ) under μ-strong convexity.', '||∇f(x)||≤||ĝ||+ε, do đó f(x)−f*≤(||ĝ||+ε)²/(2μ) nếu f lồi mạnh μ.', ['Use the triangle inequality to bound the unknown true gradient by the observed norm plus error radius.', 'Dùng bất đẳng thức tam giác chặn gradient thật chưa biết bởi chuẩn quan sát cộng bán kính sai số.'], ['Substitute that upper bound into the strong-convexity gap theorem.', 'Thế cận trên ấy vào định lý gap lồi mạnh.'], ['Explain why substituting ||ĝ|| alone can understate the certified gap whenever ε>0.', 'Giải thích vì sao chỉ thế ||ĝ|| có thể đánh giá thấp gap chứng nhận khi ε>0.']),
  L('m2-w070-e5', 'For x⁴, the gradient becomes tiny near zero because curvature flattens, so the strong-convexity gap formula has no uniform μ to use.', 'Với x⁴, gradient rất nhỏ gần không vì độ cong phẳng dần, nên công thức gap lồi mạnh không có μ đều để dùng.', 'f′(x)=4x³, f″(x)=12x², and inf_{x∈R}f″(x)=0; no fixed μ>0 satisfies global strong convexity.', 'f′(x)=4x³, f″(x)=12x², và inf_{x∈R}f″(x)=0; không μ>0 cố định nào bảo đảm lồi mạnh toàn cục.', ['Evaluate f and |f′| separately at .01 and 1 to contrast small-scale behavior.', 'Tính riêng f và |f′| tại .01 và 1 để so sánh hành vi gần/xa gốc.'], ['Inspect f″=12x² and its infimum over the domain; a positive pointwise curvature is not a positive uniform lower bound.', 'Xét f″=12x² và infimum trên miền; độ cong dương tại từng điểm không tạo cận dưới đều dương.'], ['Conclude the certificate premise fails even though this example happens to have a small gap near zero.', 'Kết luận tiền đề chứng chỉ thất bại dù ví dụ này tình cờ có gap nhỏ gần không.']),
  L('m2-w071-e1', 'The smooth square-loss step moves x₀=0 to a proposal of 4, then the ℓ1 proximal map shrinks it to a sparse coefficient.', 'Bước square loss trơn đưa x₀=0 tới đề xuất 4, rồi proximal ℓ1 co nó thành hệ số thưa.', 'x⁺=prox_{ηh}(x−η∇f(x)); for h=|x| and η=1, prox is soft threshold at 1.', 'x⁺=prox_{ηh}(x−η∇f(x)); với h=|x| và η=1, prox là soft-threshold ngưỡng 1.', ['Compute ∇f(0) for ½(x−4)² and form the gradient proposal v=x₀−η∇f(x₀).', 'Tính ∇f(0) cho ½(x−4)² rồi lập đề xuất gradient v=x₀−η∇f(x₀).'], ['Apply the threshold-one prox to v, retaining sign and subtracting one from its magnitude.', 'Áp dụng prox ngưỡng một cho v, giữ dấu và trừ một khỏi độ lớn.'], ['Evaluate both the smooth-plus-nonsmooth objective values F(0) and F(x₁); identify the full composite objective.', 'Tính cả hai giá trị mục tiêu trơn-cộng-không-trơn F(0), F(x₁); xác định đúng mục tiêu hợp thành.']),
  L('m2-w071-e2', 'The proximal-gradient update minimizes a local quadratic model of the smooth part plus the exact nonsmooth penalty.', 'Cập nhật proximal-gradient cực tiểu mô hình quadratic cục bộ của phần trơn cộng penalty không trơn chính xác.', 'x⁺=argmin_u[h(u)+∇f(x)ᵀ(u−x)+||u−x||²/(2η)]=prox_{ηh}(x−η∇f(x)); 0∈∂h(x⁺)+∇f(x)+(x⁺−x)/η.', 'x⁺=argmin_u[h(u)+∇f(x)ᵀ(u−x)+||u−x||²/(2η)]=prox_{ηh}(x−η∇f(x)); 0∈∂h(x⁺)+∇f(x)+(x⁺−x)/η.', ['Collect the u-dependent linear and quadratic terms and complete the square around x−η∇f(x).', 'Gom các hạng tuyến tính và quadratic phụ thuộc u rồi hoàn thành bình phương quanh x−η∇f(x).'], ['Recognize the resulting minimization as the proximal definition; constants independent of u do not affect its argmin.', 'Nhận diện phép cực tiểu thu được là định nghĩa proximal; hằng số không phụ thuộc u không ảnh hưởng argmin.'], ['Write the convex optimality inclusion and rearrange to the requested subgradient form.', 'Viết bao hàm tối ưu lồi rồi biến đổi về dạng dưới-gradient được yêu cầu.']),
  L('m2-w071-e3', 'A one-step composite objective inequality can be summed across iterates; squared-distance terms telescope and convexity controls the averaged point.', 'Bất đẳng thức mục tiêu hợp thành một bước có thể cộng qua iterate; hạng khoảng cách bình phương triệt tiêu và tính lồi chặn điểm trung bình.', 'Σ_{t=1}^T[F(x_{t+1})−F(x*)]≤||x₁−x*||²/(2η); convexity gives F(T⁻¹Σx_{t+1})≤T⁻¹ΣF(x_{t+1}).', 'Σ_{t=1}^T[F(x_{t+1})−F(x*)]≤||x₁−x*||²/(2η); tính lồi cho F(T⁻¹Σx_{t+1})≤T⁻¹ΣF(x_{t+1}).', ['Set comparator z=x* in the stated one-step inequality and write its distance potential explicitly.', 'Đặt comparator z=x* trong bất đẳng thức một bước rồi viết tường minh potential khoảng cách.'], ['Sum over t so every intermediate squared distance cancels, retaining only the first and final terms.', 'Cộng theo t để mọi khoảng cách bình phương trung gian triệt tiêu, chỉ còn hạng đầu và cuối.'], ['Drop the nonnegative final distance, divide by T, then apply Jensen to the average of x₂,…,x_{T+1}.', 'Bỏ khoảng cách cuối không âm, chia T, rồi áp Jensen cho trung bình x₂,…,x_{T+1}.']),
  L('m2-w071-e4', 'LASSO splits into a differentiable squared residual and a nonsmooth sparsity cost, so each iteration needs matrix-vector products and thresholding.', 'LASSO tách thành residual bình phương khả vi và penalty thưa không trơn, nên mỗi vòng chỉ cần nhân ma trận-vector và threshold.', 'For f(x)=½||Ax−b||², ∇f=Aᵀ(Ax−b), L=||A||₂²; h=λ||x||₁ gives x⁺=S_{ηλ}(x−ηAᵀ(Ax−b)) for η≤1/L.', 'Với f(x)=½||Ax−b||², ∇f=Aᵀ(Ax−b), L=||A||₂²; h=λ||x||₁ cho x⁺=S_{ηλ}(x−ηAᵀ(Ax−b)) nếu η≤1/L.', ['Assign the data-fit term to f and the ℓ1 term to h; do not force the nonsmooth part into a gradient.', 'Gán hạng khớp dữ liệu cho f và ℓ1 cho h; không ép phần không trơn thành gradient.'], ['Differentiate the squared residual and identify its Lipschitz constant through AᵀA.', 'Lấy đạo hàm residual bình phương và tìm hằng số Lipschitz qua AᵀA.'], ['Write one safe-step update and apply coordinatewise soft thresholding; no matrix inverse is required.', 'Viết cập nhật với bước an toàn rồi threshold từng tọa độ; không cần nghịch đảo ma trận.']),
  L('m2-w071-e5', 'With h=0, proximal gradient reduces to ordinary gradient descent; η=3 on a unit-curvature quadratic overshoots and raises the objective.', 'Khi h=0, proximal-gradient trở thành gradient descent thường; η=3 trên quadratic độ cong một sẽ quá bước và tăng mục tiêu.', 'For L-smooth convex f, use η≤1/L; here x⁺=x−ηx and F(x)=x²/2.', 'Với f lồi trơn L, dùng η≤1/L; ở đây x⁺=x−ηx và F(x)=x²/2.', ['Set prox of zero to the identity and compute x⁺ from x=1, η=3.', 'Prox của hàm không là đồng nhất; tính x⁺ từ x=1, η=3.'], ['Evaluate the objective at both points to quantify the increase.', 'Tính mục tiêu tại cả hai điểm để lượng hóa độ tăng.'], ['Compare the chosen step with 1/L=1 and name the violated step-size premise.', 'So sánh bước chọn với 1/L=1 và nêu tiền đề bước bị vi phạm.']),
  L('m2-w072-e1', 'A box-constrained SPD quadratic gives an integrated certificate: one coordinate hits its upper bound, while a second tiny-curvature coordinate exposes sensitivity to data perturbations.', 'Quadratic SPD ràng buộc hộp tạo chứng chỉ tích hợp: một tọa độ chạm cận trên, còn tọa độ độ cong rất nhỏ bộc lộ độ nhạy dữ liệu.', 'For L=½(x−c)ᵀQ(x−c)+λᵀ(x−1)−μᵀx, q=½cᵀQc−1ᵀλ−½(−Qc+λ−μ)ᵀQ⁻¹(−Qc+λ−μ); κ₂(Q)=λmax/λmin.', 'Với L=½(x−c)ᵀQ(x−c)+λᵀ(x−1)−μᵀx, q=½cᵀQc−1ᵀλ−½(−Qc+λ−μ)ᵀQ⁻¹(−Qc+λ−μ); κ₂(Q)=λmax/λmin.', ['Derive the dual by minimizing the Lagrangian over x; retain both multiplier signs and constraints λ,μ≥0.', 'Suy dual bằng cách cực tiểu Lagrangian theo x; giữ đúng dấu multiplier và điều kiện λ,μ≥0.'], ['At x*=(1,.5), verify box feasibility, stationarity Q(x−c)+λ−μ=0 and complementary slackness before comparing primal and dual values.', 'Tại x*=(1,.5), kiểm tra miền hộp, stationarity Q(x−c)+λ−μ=0 và complementary slackness trước khi so giá trị primal-dual.'], ['Solve Qx=b and Qx̃=b̃ coordinatewise; report κ, relative input/output changes and a scaled residual to separate stability from conditioning.', 'Giải Qx=b và Qx̃=b̃ theo tọa độ; báo κ, thay đổi tương đối đầu vào/đầu ra và residual chuẩn hóa để tách ổn định số khỏi conditioning.']),
  L('m2-w072-e2', 'Equality-constrained ridge combines a primal-dual KKT certificate with spectral gradient convergence, so solve the constraint first and then analyze every Hessian mode.', 'Ridge có ràng buộc đẳng thức ghép chứng chỉ KKT primal-dual với hội tụ gradient phổ; trước hết giải ràng buộc rồi phân tích từng mode Hessian.', 'q(ν)=−½(b−νa)ᵀH⁻¹(b−νa)−νd; for ridge Hessian M=AᵀA+λI with mI⪯M⪯LI, GD η=1/L gives objective factor (1−m/L)².', 'q(ν)=−½(b−νa)ᵀH⁻¹(b−νa)−νd; với Hessian ridge M=AᵀA+λI, mI⪯M⪯LI, GD η=1/L cho hệ số mục tiêu (1−m/L)².', ['Form the equality Lagrangian, minimize over x to get q(ν), then use stationarity and aᵀx=d to determine ν and x.', 'Lập Lagrangian đẳng thức, cực tiểu theo x để có q(ν), rồi dùng stationarity và aᵀx=d tìm ν,x.'], ['Substitute the primal-dual pair into both objectives and verify equal values; do not infer the gap from stationarity alone.', 'Thế cặp primal-dual vào hai mục tiêu và xác nhận giá trị bằng nhau; không suy gap chỉ từ stationarity.'], ['For convergence, diagonalize M, bound each eigenvalue in [m,L], and compare weighted squared errors before asserting the contraction factor.', 'Với hội tụ, chéo hóa M, chặn trị riêng trong [m,L] rồi so sai số bình phương có trọng số trước khi kết luận hệ số co.']),
  L('m2-w072-e3', 'A least-squares perturbation concentrated in the weak singular direction changes the fitted parameter visibly while the data move very little.', 'Nhiễu least-squares tập trung ở hướng singular yếu làm tham số fitted đổi thấy rõ dù dữ liệu chỉ đổi rất ít.', 'κ₂(A)=σmax/σmin and κ₂(AᵀA)=κ₂(A)²; use η=||Ax̂−b̃||/(||A||||x̂||+||b̃||) for scaled residual.', 'κ₂(A)=σmax/σmin và κ₂(AᵀA)=κ₂(A)²; dùng η=||Ax̂−b̃||/(||A||||x̂||+||b̃||) làm residual chuẩn hóa.', ['Read the diagonal singular values to calculate both condition numbers and solve x̃=A⁻¹b̃ coordinatewise.', 'Đọc singular value đường chéo để tính hai condition number rồi giải x̃=A⁻¹b̃ theo tọa độ.'], ['Compute relative perturbations in b and x separately; the second coordinate reveals the amplification.', 'Tính riêng nhiễu tương đối của b và x; tọa độ thứ hai bộc lộ khuếch đại.'], ['Explain why normal equations square conditioning; recommend QR/SVD and report scaled residual plus singular-value diagnostics.', 'Giải thích phương trình chuẩn bình phương conditioning; đề xuất QR/SVD và báo residual chuẩn hóa cùng chẩn đoán singular value.']),
  L('m2-w072-e4', 'A LASSO primal vector x and residual dual vector u can certify optimality when the residual identity and ℓ∞ dual constraint align.', 'Vector primal x của LASSO và vector dual residual u chứng nhận tối ưu khi đồng nhất thức residual và ràng buộc dual ℓ∞ khớp nhau.', 'For P=½||Ax−b||²+λ||x||₁, D(u)=−½||u||²−bᵀu subject to ||Aᵀu||∞≤λ; equality uses u=Ax−b and −Aᵀu∈λ∂||x||₁.', 'Với P=½||Ax−b||²+λ||x||₁, D(u)=−½||u||²−bᵀu với ||Aᵀu||∞≤λ; đẳng thức cần u=Ax−b và −Aᵀu∈λ∂||x||₁.', ['Express the objective as g(Ax−b)+h(x), then use quadratic and scaled-ℓ1 conjugates to write the dual.', 'Viết mục tiêu thành g(Ax−b)+h(x), rồi dùng liên hợp quadratic và ℓ1 tỷ lệ để lập dual.'], ['Check dual feasibility coordinatewise through ||Aᵀu||∞≤λ and verify the proposed residual relation.', 'Kiểm tra khả thi dual theo từng tọa độ qua ||Aᵀu||∞≤λ và xác nhận quan hệ residual đề xuất.'], ['Apply equality conditions for both Fenchel–Young inequalities; their sum proves equal primal/dual values and optimality.', 'Áp dụng điều kiện đẳng thức cho cả hai bất đẳng thức Fenchel–Young; cộng lại cho giá trị primal/dual bằng nhau và tối ưu.']),
  L('m2-w072-e5', 'Projected online updates on a compact feasible set compare every round with one fixed feasible comparator; the bound says nothing about market payoffs.', 'Cập nhật online có chiếu trên tập khả thi compact so sánh từng vòng với một comparator khả thi cố định; cận không nói về payoff thị trường.', 'Σₜ[fₜ(xₜ)−fₜ(u)]≤D²/(2η)+ηG²T/2 for convex fₜ on C, diam(C)≤D and ||∇fₜ||≤G.', 'Σₜ[fₜ(xₜ)−fₜ(u)]≤D²/(2η)+ηG²T/2 với fₜ lồi trên C, diam(C)≤D và ||∇fₜ||≤G.', ['Set gₜ=∇fₜ(xₜ) and use projection nonexpansiveness against fixed u∈C to bound the next squared distance.', 'Đặt gₜ=∇fₜ(xₜ), dùng tính không giãn của phép chiếu so với u∈C cố định để chặn khoảng cách bình phương kế tiếp.'], ['Expand the square, rearrange for gₜᵀ(xₜ−u), and use convexity to upper-bound the round loss difference.', 'Khai triển bình phương, biến đổi để chặn gₜᵀ(xₜ−u), rồi dùng tính lồi chặn chênh loss mỗi vòng.'], ['Sum and telescope; bound the initial distance by D² and gradients by G², then name missing uncertainty, execution and cost models for significance/profit claims.', 'Cộng và telescoping; chặn khoảng cách đầu bởi D², gradient bởi G², rồi nêu thiếu mô hình bất định, thực thi và chi phí để kết luận ý nghĩa/lợi nhuận.']),
  L('m2-w073-e1', 'For an AR(1)-shaped covariance γ(h)=.25(.6)^|h|, sum all positive and negative lag contributions to measure variance of a long sample mean.', 'Với covariance dạng AR(1) γ(h)=.25(.6)^|h|, cộng đóng góp mọi lag dương và âm để đo phương sai trung bình mẫu dài.', 'Ω=Σ_{h∈Z}γ(h)=γ(0)+2Σ_{h≥1}γ(h); for |φ|<1 and γ(h)=γ(0)φ^|h|, Ω=γ(0)(1+φ)/(1−φ).', 'Ω=Σ_{h∈Z}γ(h)=γ(0)+2Σ_{h≥1}γ(h); nếu |φ|<1 và γ(h)=γ(0)φ^|h| thì Ω=γ(0)(1+φ)/(1−φ).', ['Evaluate γ at zero and at ±1; use symmetry γ(−h)=γ(h).', 'Tính γ tại không và ±1; dùng tính đối xứng γ(−h)=γ(h).'], ['Sum the positive-lag geometric series and include its equal negative-lag contribution.', 'Cộng cấp số nhân lag dương và tính thêm phần lag âm bằng nó.'], ['Check positivity numerically and conceptually: this valid covariance has a nonnegative spectral density and the stated positive Ω.', 'Kiểm tra tính dương bằng số và khái niệm: covariance hợp lệ này có mật độ phổ không âm và Ω dương như đã tính.']),
  L('m2-w073-e2', 'The variance of a finite dependent average counts how many observation pairs share each signed time lag.', 'Phương sai trung bình phụ thuộc hữu hạn đếm số cặp quan sát ứng với từng độ trễ có dấu.', 'Var(X̄ₙ)=n⁻²Σ_{|h|<n}(n−|h|)γ(h), so nVar(X̄ₙ)=Σ_{|h|<n}(1−|h|/n)γ(h).', 'Var(X̄ₙ)=n⁻²Σ_{|h|<n}(n−|h|)γ(h), nên nVar(X̄ₙ)=Σ_{|h|<n}(1−|h|/n)γ(h).', ['Expand Var(ΣXₜ) as a double sum and replace each covariance by γ(s−t) using weak stationarity.', 'Khai triển Var(ΣXₜ) thành tổng kép và thay mỗi covariance bằng γ(s−t) theo tính dừng yếu.'], ['For a fixed signed lag h, count the n−|h| pairs (s,t); omit lags whose count is zero.', 'Với lag có dấu h cố định, đếm n−|h| cặp (s,t); bỏ lag không có cặp.'], ['Divide by n² for the average and factor out 1/n to expose the triangular Bartlett weights.', 'Chia n² cho trung bình rồi tách 1/n để thấy trọng số Bartlett tam giác.']),
  L('m2-w073-e3', 'A blockwise process can keep the same means and covariances while a deterministic triple-product pattern reveals a changing joint law.', 'Quá trình theo khối có thể giữ nguyên mean và covariance trong khi mẫu tích ba xác định làm lộ luật chung thay đổi.', 'Weak stationarity fixes E[Xₜ] and Cov(Xₜ,Xₛ) by lag; strict stationarity requires every finite-dimensional distribution to be shift-invariant.', 'Dừng yếu cố định E[Xₜ] và Cov(Xₜ,Xₛ) theo lag; dừng nghiêm ngặt đòi mọi phân phối hữu hạn chiều bất biến khi dịch thời gian.', ['Use the independent Rademacher construction to check every coordinate has mean zero and variance one.', 'Dùng cấu trúc Rademacher độc lập để kiểm tra từng tọa độ có mean không và phương sai một.'], ['Check within-block pair products and cross-block independence to show nonzero-lag covariances vanish at every time position.', 'Kiểm tra tích cặp trong khối và độc lập giữa khối để thấy covariance lag khác không triệt tiêu ở mọi vị trí thời gian.'], ['Compute the consecutive triple product; its alternating deterministic value changes under a one-step shift, contradicting strict stationarity.', 'Tính tích ba biến liên tiếp; giá trị xác định luân phiên đổi khi dịch một bước, trái với dừng nghiêm ngặt.']),
  L('m2-w073-e4', 'Any linear contrast of a random vector has nonnegative variance, which makes its covariance matrix positive semidefinite.', 'Mọi tổ hợp tuyến tính của vector ngẫu nhiên có phương sai không âm, nên ma trận covariance là nửa xác định dương.', 'For finite-second-moment X, aᵀΓa=Var(aᵀX)≥0 for every a; exact Γ therefore satisfies Γ⪰0.', 'Với X có moment bậc hai hữu hạn, aᵀΓa=Var(aᵀX)≥0 với mọi a; do đó Γ chính xác thỏa Γ⪰0.', ['Expand the scalar variance of aᵀX as aᵀCov(X)a.', 'Khai triển phương sai vô hướng của aᵀX thành aᵀCov(X)a.'], ['Use nonnegativity of variance for arbitrary a to prove the PSD definition.', 'Dùng tính không âm của phương sai với a tùy ý để chứng minh định nghĩa PSD.'], ['Separate mathematical PSD from computed estimates: rounding, asymmetric truncation or separately estimated entries can create negative eigenvalues.', 'Tách PSD toán học khỏi ước lượng số: làm tròn, cắt lag bất đối xứng hay ước lượng từng phần tử riêng có thể tạo trị riêng âm.']),
  L('m2-w073-e5', 'To identify the long-run variance as the limit of n times sample-mean variance, pass the finite triangular lag weights through an absolutely summable covariance series.', 'Để nhận diện long-run variance là giới hạn n lần phương sai trung bình, cho trọng số lag tam giác hữu hạn đi qua chuỗi covariance khả tổng tuyệt đối.', 'If Σ_h|γ(h)|<∞, then nVar(X̄ₙ)=Σ_h 1{|h|<n}(1−|h|/n)γ(h)→Ω=Σ_hγ(h).', 'Nếu Σ_h|γ(h)|<∞ thì nVar(X̄ₙ)=Σ_h 1{|h|<n}(1−|h|/n)γ(h)→Ω=Σ_hγ(h).', ['Write the finite-n sum as a series over all integer h with an indicator for |h|<n.', 'Viết tổng hữu hạn theo mọi số nguyên h với chỉ thị |h|<n.'], ['For each fixed h, show its coefficient converges to one and is bounded in absolute value by one.', 'Với h cố định, chứng minh hệ số tiến đến một và có trị tuyệt đối không quá một.'], ['Use |γ(h)| as the summable dominating sequence; state that this variance limit alone is not a central limit theorem.', 'Dùng |γ(h)| làm dãy trội khả tổng; nêu riêng giới hạn phương sai này chưa phải định lý giới hạn trung tâm.']),
  L('m2-w074-e1', 'An AR(1) coefficient .8 with innovation variance 1.44 determines variance and lag covariances through a geometric decay.', 'Hệ số AR(1) .8 với phương sai innovation 1.44 xác định phương sai và covariance lag theo suy giảm hình học.', 'For |φ|<1, γ(0)=σ²/(1−φ²), γ(h)=φ^|h|γ(0).', 'Với |φ|<1, γ(0)=σ²/(1−φ²), γ(h)=φ^|h|γ(0).', ['Check |φ|<1, then substitute σ² and φ into the stationary variance formula.', 'Kiểm tra |φ|<1 rồi thế σ² và φ vào công thức phương sai dừng.'], ['Use γ(1)=φγ(0), preserving the sign of φ.', 'Dùng γ(1)=φγ(0), giữ nguyên dấu φ.'], ['Apply the recurrence three times for lag three, or raise φ to the third power; no new variance term is added.', 'Áp dụng truy hồi ba lần cho lag ba hoặc lấy φ mũ ba; không cộng thêm hạng phương sai.']),
  L('m2-w074-e2', 'Multiplying an AR(1) equation by a past observation eliminates the innovation cross-term when the innovation is orthogonal to the past.', 'Nhân phương trình AR(1) với quan sát quá khứ làm mất hạng chéo innovation khi innovation trực giao với quá khứ.', 'For h≥1, γ(h)=φγ(h−1) if E[εₜXₜ₋ₕ]=0; at h=0, γ(0)=φγ(1)+σ².', 'Với h≥1, γ(h)=φγ(h−1) nếu E[εₜXₜ₋ₕ]=0; tại h=0, γ(0)=φγ(1)+σ².', ['Multiply both sides of Xₜ=φXₜ₋₁+εₜ by Xₜ₋ₕ and take expectations.', 'Nhân hai vế Xₜ=φXₜ₋₁+εₜ với Xₜ₋ₕ rồi lấy kỳ vọng.'], ['For h≥1, identify Xₜ₋ₕ as past-measurable and use innovation orthogonality; match the remaining term to γ(h−1).', 'Với h≥1, nhận diện Xₜ₋ₕ thuộc quá khứ và dùng trực giao innovation; đồng nhất hạng còn lại với γ(h−1).'], ['Treat h=0 separately because E[εₜXₜ]=σ²; this supplies the variance equation rather than the past-orthogonality step.', 'Xét riêng h=0 vì E[εₜXₜ]=σ²; đây là phương trình phương sai, không dùng bước trực giao quá khứ.']),
  L('m2-w074-e3', 'The AR polynomial controls causal stationarity while the MA polynomial controls invertibility; both are checked by root locations under the stated convention.', 'Đa thức AR kiểm soát tính nhân quả/dừng, còn đa thức MA kiểm soát khả nghịch; cả hai được kiểm tra bằng vị trí nghiệm theo quy ước đã nêu.', 'For AR(1), 1−φz=0 must have root |z|>1; for MA(1), 1+θz=0 must have root |z|>1 for invertibility.', 'Với AR(1), nghiệm 1−φz=0 phải có |z|>1; với MA(1), nghiệm 1+θz=0 phải có |z|>1 để khả nghịch.', ['Solve each polynomial separately, using the problem’s lag-polynomial convention.', 'Giải riêng từng đa thức, dùng đúng quy ước lag-polynomial của đề.'], ['Compare each root modulus with one; report AR causality/stationarity and MA invertibility as distinct properties.', 'So modulus từng nghiệm với một; báo tính nhân quả/dừng AR và khả nghịch MA như hai tính chất riêng.'], ['Check signs and reciprocal conventions before concluding; do not infer one property from the other model’s root.', 'Kiểm tra dấu và quy ước nghịch đảo trước khi kết luận; không suy tính chất này từ nghiệm của mô hình kia.']),
  L('m2-w074-e4', 'Differencing a random walk yields stationary white-noise increments even though the level itself has variance that grows over time.', 'Lấy sai phân random walk cho increments nhiễu trắng dừng dù mức có phương sai tăng theo thời gian.', 'If Xₜ=Xₜ₋₁+εₜ, then ΔXₜ=εₜ; with fixed X₀, Var(Xₜ)=tσ².', 'Nếu Xₜ=Xₜ₋₁+εₜ thì ΔXₜ=εₜ; với X₀ cố định, Var(Xₜ)=tσ².', ['Apply the difference operator to cancel Xₜ₋₁ and identify the increment process.', 'Áp dụng toán tử sai phân để triệt tiêu Xₜ₋₁ và nhận diện quá trình increment.'], ['Use IID innovation moments to verify weak stationarity of ΔXₜ.', 'Dùng moment innovation IID để kiểm tra tính dừng yếu của ΔXₜ.'], ['Compute level variance over time and explain why a theorem requiring stationary levels or summable fixed-lag covariance cannot be invoked for Xₜ.', 'Tính phương sai mức theo thời gian và giải thích vì sao không dùng định lý cần mức dừng hoặc covariance lag khả tổng cho Xₜ.']),
  L('m2-w074-e5', 'A one-time mean shift keeps within-regime noise variance fixed, unlike a random walk whose accumulated innovations make variance grow.', 'Dịch chuyển mean một lần giữ phương sai nhiễu trong từng chế độ, khác random walk tích lũy innovation làm phương sai tăng.', 'For Xₜ=μₜ+εₜ with fixed shift date, Var(Xₜ)=σ²; a random walk has Var(Xₜ)=Var(X₀)+tσ².', 'Với Xₜ=μₜ+εₜ có ngày shift cố định, Var(Xₜ)=σ²; random walk có Var(Xₜ)=Var(X₀)+tσ².', ['Compare time-specific means and variances under a fixed structural break versus accumulated innovations.', 'So sánh mean và variance theo thời gian của break cố định với innovation tích lũy.'], ['Identify persistent level deviations and altered sample autocorrelations after the break.', 'Nhận diện độ lệch mức kéo dài và tự tương quan mẫu đổi sau break.'], ['Explain how omitting a deterministic break can mimic persistence without claiming it is a unit root; model the break or qualify diagnosis.', 'Giải thích bỏ sót break xác định có thể giả dạng persistence nhưng không khẳng định là unit root; mô hình hóa break hoặc giới hạn chẩn đoán.']),
  L('m2-w075-e1', 'A two-tap filter combines today’s white-noise shock and half of yesterday’s shock, reshaping variance by frequency.', 'Bộ lọc hai tap ghép shock nhiễu trắng hôm nay với một nửa shock hôm qua, làm biến đổi phương sai theo tần số.', 'For Xₜ=Ψ(L)εₜ, f_X(ω)=σ²|Ψ(e^{-iω})|²/(2π); here Ψ=1+.5e^{-iω}.', 'Với Xₜ=Ψ(L)εₜ, f_X(ω)=σ²|Ψ(e^{-iω})|²/(2π); ở đây Ψ=1+.5e^{-iω}.', ['Write the transfer function and multiply by its complex conjugate to get |Ψ|²=1.25+cosω.', 'Viết hàm truyền và nhân với liên hợp phức để được |Ψ|²=1.25+cosω.'], ['Multiply by innovation variance four and divide by 2π under the stated spectral convention.', 'Nhân với phương sai innovation bốn rồi chia 2π theo quy ước phổ đã nêu.'], ['Evaluate cosω at zero and π and verify the zero-frequency power is larger than the high-frequency power.', 'Tính cosω tại không và π, kiểm tra công suất tần số không lớn hơn công suất tần số cao.']),
  L('m2-w075-e2', 'An absolutely summable linear filter lets the covariance and spectral sums be rearranged without changing their values.', 'Bộ lọc tuyến tính khả tổng tuyệt đối cho phép đổi thứ tự tổng covariance và phổ mà không đổi giá trị.', 'For Xₜ=Σ_jψ_jεₜ₋ⱼ, γ_X(h)=σ²Σ_jψ_jψ_{j−h}; f_X(ω)=σ²|Ψ(e^{-iω})|²/(2π).', 'Với Xₜ=Σ_jψ_jεₜ₋ⱼ, γ_X(h)=σ²Σ_jψ_jψ_{j−h}; f_X(ω)=σ²|Ψ(e^{-iω})|²/(2π).', ['Expand XₜXₜ₋ₕ and use E[ε_aε_b]=σ²1{a=b} to leave only matched innovation indices.', 'Khai triển XₜXₜ₋ₕ và dùng E[ε_aε_b]=σ²1{a=b} để chỉ còn chỉ số innovation trùng.'], ['Fourier-transform the covariance expression and collect the ψ terms into Ψ and its conjugate.', 'Biến đổi Fourier biểu thức covariance rồi gom các ψ thành Ψ và liên hợp.'], ['Use absolute summability to justify Fubini and reindexing; this is the condition controlling the double series.', 'Dùng khả tổng tuyệt đối để hợp thức hóa Fubini và đổi chỉ số; đây là điều kiện kiểm soát tổng kép.']),
  L('m2-w075-e3', 'Integrating spectral density across frequencies recovers variance because all nonzero Fourier modes integrate to zero.', 'Tích phân mật độ phổ theo tần số khôi phục phương sai vì mọi mode Fourier khác không đều có tích phân bằng không.', 'If Σ_h|γ(h)|<∞, f(ω)=(2π)⁻¹Σ_hγ(h)e^{-ihω} and ∫_{−π}^{π}f(ω)dω=γ(0).', 'Nếu Σ_h|γ(h)|<∞, f(ω)=(2π)⁻¹Σ_hγ(h)e^{-ihω} và ∫_{−π}^{π}f(ω)dω=γ(0).', ['Insert the Fourier series definition of f and use absolute summability to exchange sum and integral.', 'Thế chuỗi Fourier của f và dùng khả tổng tuyệt đối để đổi tổng với tích phân.'], ['Integrate each complex exponential; only h=0 contributes 2π.', 'Tích phân từng hàm mũ phức; chỉ h=0 đóng góp 2π.'], ['Cancel the 1/(2π) normalization and recognize γ(0)=Var(Xₜ).', 'Khử hệ số chuẩn hóa 1/(2π) và nhận diện γ(0)=Var(Xₜ).']),
  L('m2-w075-e4', 'For a stationary AR(1), the long-run variance equals its zero-frequency spectral power times 2π and also equals the summed geometric autocovariance.', 'Với AR(1) dừng, long-run variance bằng 2π nhân công suất phổ tại tần số không và cũng bằng tổng autocovariance hình học.', 'Ω=Σ_hγ(h)=2πf(0); AR(1) gives f(0)=σ²/[2π(1−φ)²] and Ω=σ²/(1−φ)².', 'Ω=Σ_hγ(h)=2πf(0); AR(1) cho f(0)=σ²/[2π(1−φ)²] và Ω=σ²/(1−φ)².', ['Set ω=0 in the absolutely convergent Fourier series and identify the covariance sum.', 'Cho ω=0 trong chuỗi Fourier hội tụ tuyệt đối và nhận diện tổng covariance.'], ['Use the AR(1) transfer function at frequency zero to obtain its spectral value.', 'Dùng hàm truyền AR(1) tại tần số không để tìm giá trị phổ.'], ['Independently sum γ(0)[1+2Σφʰ] and simplify; agreement checks both conventions and algebra.', 'Độc lập cộng γ(0)[1+2Σφʰ] rồi rút gọn; sự trùng khớp kiểm tra quy ước và đại số.']),
  L('m2-w075-e5', 'A random-walk level has no lag-only stationary covariance sequence, but its first difference has a flat white-noise spectrum.', 'Mức random walk không có covariance dừng chỉ phụ thuộc lag, nhưng sai phân bậc nhất có phổ phẳng nhiễu trắng.', 'A stationary spectral density requires γ(h)=Cov(Xₜ,Xₜ₋ₕ) independent of t and a summable Fourier series; for ΔXₜ=εₜ, f=σ²/(2π).', 'Mật độ phổ dừng cần γ(h)=Cov(Xₜ,Xₜ₋ₕ) không phụ thuộc t và chuỗi Fourier khả tổng; với ΔXₜ=εₜ, f=σ²/(2π).', ['Compute Var(Xₜ) and Cov(Xₜ,Xₛ) for the random walk and note their dependence on calendar time.', 'Tính Var(Xₜ), Cov(Xₜ,Xₛ) của random walk và nhận thấy phụ thuộc thời gian lịch.'], ['Conclude that the stationary γ(h) required for the level’s Fourier series is unavailable.', 'Kết luận không có γ(h) dừng cần cho chuỗi Fourier của mức.'], ['Difference the process and give the white-noise spectrum, carefully labeling it as the spectrum of increments rather than levels.', 'Lấy sai phân quá trình và nêu phổ nhiễu trắng, ghi rõ đó là phổ increments chứ không phải mức.']),
  L('m2-w076-e1', 'A geometrically mixing process with a finite third moment satisfies the stated summability test, allowing the selected dependent CLT when Ω>0.', 'Quá trình mixing giảm hình học và có moment bậc ba hữu hạn thỏa kiểm tra khả tổng, cho phép dùng CLT phụ thuộc đã chọn khi Ω>0.', 'The mixing requirement is Σ_k α(k)^{δ/(2+δ)}<∞ with E|X₀|^{2+δ}<∞; here δ=1 gives exponent 1/3.', 'Điều kiện mixing là Σ_k α(k)^{δ/(2+δ)}<∞ và E|X₀|^{2+δ}<∞; ở đây δ=1 cho số mũ 1/3.', ['Substitute α(k)=.2ᵏ and δ=1 to identify a geometric ratio .2^(1/3)<1.', 'Thế α(k)=.2ᵏ và δ=1 để nhận ra công bội hình học .2^(1/3)<1.'], ['Conclude the mixing series converges and verify stationarity, centering and the required moment separately.', 'Kết luận chuỗi mixing hội tụ rồi kiểm tra riêng tính dừng, mean không và moment yêu cầu.'], ['Only after confirming Ω>0 invoke the stated CLT and identify its normalized sum and limiting variance.', 'Chỉ sau khi xác nhận Ω>0 mới dùng CLT đã nêu, ghi rõ tổng chuẩn hóa và phương sai giới hạn.']),
  L('m2-w076-e2', 'If the variance of an average shrinks faster than 1/n, Chebyshev directly yields convergence in probability to its mean.', 'Nếu phương sai trung bình giảm nhanh hơn 1/n, Chebyshev trực tiếp suy ra hội tụ xác suất về mean.', 'P(|X̄ₙ−μ|>ε)≤Var(X̄ₙ)/ε²; if nVar(X̄ₙ)→0, the bound tends to zero.', 'P(|X̄ₙ−μ|>ε)≤Var(X̄ₙ)/ε²; nếu nVar(X̄ₙ)→0 thì cận tiến về không.', ['Center the average using E[X̄ₙ]=μ and apply Chebyshev for a fixed ε>0.', 'Trừ mean của trung bình nhờ E[X̄ₙ]=μ rồi áp Chebyshev với ε>0 cố định.'], ['Rewrite the right side as [nVar(X̄ₙ)]/(nε²) to expose the assumed rate.', 'Viết vế phải thành [nVar(X̄ₙ)]/(nε²) để thấy rate giả thiết.'], ['Contrast nVar→Ω>0 as the usual n⁻¹/² fluctuation scale, while stating it alone is not a distributional CLT.', 'Đối chiếu nVar→Ω>0 là thang dao động n⁻¹/² thường gặp, đồng thời nêu điều đó chưa tự thành CLT phân phối.']),
  L('m2-w076-e3', 'First differences of IID noise have negative adjacent covariance that exactly cancels the zero-lag term in their long-run variance.', 'Sai phân của nhiễu IID có covariance kề âm triệt tiêu đúng hạng lag không trong long-run variance.', 'Xₜ=Yₜ−Yₜ₋₁ gives γ(0)=2τ², γ(±1)=−τ², Ω=Σ_hγ(h)=0; ΣₜXₜ=Yₙ−Y₀.', 'Xₜ=Yₜ−Yₜ₋₁ cho γ(0)=2τ², γ(±1)=−τ², Ω=Σ_hγ(h)=0; ΣₜXₜ=Yₙ−Y₀.', ['Expand Var(Yₜ−Yₜ₋₁) and the adjacent covariance using independence of the Y variables.', 'Khai triển Var(Yₜ−Yₜ₋₁) và covariance kề bằng tính độc lập của các Y.'], ['Sum the finite set of nonzero autocovariances to calculate Ω.', 'Cộng tập autocovariance khác không hữu hạn để tính Ω.'], ['Telescope the partial sum and show its variance stays bounded; division by √n therefore gives a degenerate L² limit.', 'Telescoping tổng riêng phần và chứng minh phương sai bị chặn; chia √n vì vậy cho giới hạn L² suy biến.']),
  L('m2-w076-e4', 'A finite moving-average Gaussian process lets us verify mixing separation, moments and positive long-run variance before citing a dependent CLT.', 'Quá trình Gaussian trung bình trượt hữu hạn cho phép kiểm tra phân tách mixing, moment và long-run variance dương trước khi dẫn CLT phụ thuộc.', 'For Xₜ=εₜ+θεₜ₋₁, α(k)=0 for k≥2; Ω=σ²(1+θ)²>0 when θ≠−1.', 'Với Xₜ=εₜ+θεₜ₋₁, α(k)=0 khi k≥2; Ω=σ²(1+θ)²>0 nếu θ≠−1.', ['List the innovation indices used by the past sigma-field and the future starting at k≥2; they are disjoint.', 'Liệt kê chỉ số innovation của sigma-field quá khứ và tương lai bắt đầu k≥2; hai tập rời nhau.'], ['Use Gaussian moments and finite dependence to verify the moment and mixing-series requirements.', 'Dùng moment Gaussian và phụ thuộc hữu hạn để kiểm tra điều kiện moment và chuỗi mixing.'], ['Compute γ(0), γ(1), and remaining lags, sum to Ω, then check θ≠−1 ensures nondegeneracy.', 'Tính γ(0), γ(1), các lag còn lại rồi cộng thành Ω; kiểm tra θ≠−1 bảo đảm không suy biến.']),
  L('m2-w076-e5', 'Three pairwise uncorrelated Rademacher variables can still have a deterministic triple relation, showing covariance decay misses higher-order dependence.', 'Ba biến Rademacher không tương quan từng cặp vẫn có thể có quan hệ bộ ba xác định, cho thấy covariance không thấy phụ thuộc bậc cao.', 'With independent U,V and W=UV, E[UV]=E[UW]=E[VW]=0 while UVW=1 surely.', 'Với U,V độc lập và W=UV, E[UV]=E[UW]=E[VW]=0 trong khi UVW=1 chắc chắn.', ['Compute each pairwise product expectation using U²=V²=1 and zero means.', 'Tính kỳ vọng từng tích cặp bằng U²=V²=1 và mean bằng không.'], ['Use the deterministic identity UVW=U²V²=1 to prove the triple cannot be independent.', 'Dùng đồng nhất thức xác định UVW=U²V²=1 để chứng minh bộ ba không độc lập.'], ['Connect the example to CLT scope: covariance decay alone need not supply the event-mixing assumptions required by the theorem.', 'Liên hệ với phạm vi CLT: covariance suy giảm đơn thuần không bảo đảm điều kiện mixing sự kiện mà định lý cần.']),
  L('m2-w077-e1', 'A Bartlett HAC estimate combines lag-zero variance with downweighted lag-one and lag-two covariances at bandwidth two.', 'Ước lượng HAC Bartlett ghép phương sai lag không với covariance lag một, hai được giảm trọng số tại bandwidth hai.', 'Ω̂_b=γ̂₀+2Σ_{h=1}^b(1−h/(b+1))γ̂_h.', 'Ω̂_b=γ̂₀+2Σ_{h=1}^b(1−h/(b+1))γ̂_h.', ['Write the Bartlett weight at h=1 and h=2 using b=2.', 'Viết trọng số Bartlett tại h=1 và h=2 khi b=2.'], ['Multiply each sample covariance by its weight and include the factor two for positive/negative lag pairs.', 'Nhân từng covariance mẫu với trọng số và tính hệ số hai cho cặp lag dương/âm.'], ['Add γ̂₀ and preserve adequate precision until the final rounding; label this finite-bandwidth estimate, not its asymptotic limit.', 'Cộng γ̂₀ và giữ đủ độ chính xác trước khi làm tròn; gọi đây là ước lượng bandwidth hữu hạn, không phải giới hạn tiệm cận.']),
  L('m2-w077-e2', 'A zero-padded moving-window sum of squares generates the Bartlett lag weights and proves the covariance estimate is positive semidefinite.', 'Tổng bình phương cửa sổ trượt zero-padding sinh trọng số Bartlett và chứng minh ước lượng covariance nửa xác định dương.', 'Ω̂_b=[n(b+1)]⁻¹Σ_s(Σ_{j=0}^b u_{s−j})²=Σ_h(1−|h|/(b+1))γ̂_h.', 'Ω̂_b=[n(b+1)]⁻¹Σ_s(Σ_{j=0}^b u_{s−j})²=Σ_h(1−|h|/(b+1))γ̂_h.', ['Expand each squared window into ordered pairs and index each pair by signed lag h.', 'Khai triển bình phương từng cửa sổ thành cặp có thứ tự và gắn mỗi cặp với lag có dấu h.'], ['Count b+1−|h| windows containing a pair at lag h, recovering the triangular Bartlett coefficient.', 'Đếm b+1−|h| cửa sổ chứa cặp lag h để khôi phục hệ số Bartlett tam giác.'], ['Recognize the original sum of squares as nonnegative; keep the zero-padding and normalization consistent with the sample covariance definition.', 'Nhận ra tổng bình phương ban đầu không âm; giữ zero-padding và chuẩn hóa nhất quán với định nghĩa covariance mẫu.']),
  L('m2-w077-e3', 'An asymptotically linear estimator inherits score-sum covariance through the inverse Jacobian on both sides.', 'Ước lượng tuyến tính hóa tiệm cận nhận covariance tổng score qua inverse Jacobian ở cả hai phía.', 'If √n(θ̂−θ₀)=A⁻¹Z+o_p(1) and Cov(Z)=Ω, then asymptotic covariance is A⁻¹ΩA⁻ᵀ.', 'Nếu √n(θ̂−θ₀)=A⁻¹Z+o_p(1) và Cov(Z)=Ω thì covariance tiệm cận là A⁻¹ΩA⁻ᵀ.', ['Treat the score-sum limit as the random vector Z and apply the linear covariance transformation rule.', 'Xem giới hạn tổng score là vector ngẫu nhiên Z rồi áp quy tắc biến đổi covariance tuyến tính.'], ['Multiply by A⁻¹ on the left and its transpose on the right; preserve matrix order.', 'Nhân A⁻¹ bên trái và chuyển vị của nó bên phải; giữ đúng thứ tự ma trận.'], ['State Slutsky conditions for replacing A by A-hat and explain when serial covariance makes IID information insufficient.', 'Nêu điều kiện Slutsky để thay A bằng A-hat và giải thích khi covariance chuỗi khiến information IID không đủ.']),
  L('m2-w077-e4', 'Two h-step forecasts issued on adjacent dates share target returns, so their paired loss differences can remain dependent for h−1 lags.', 'Hai dự báo h bước ở ngày kề nhau chia sẻ return đích, nên chênh loss paired có thể phụ thuộc đến lag h−1.', 'Overlapping h-day targets share h−k returns at lag k<h; uncertainty for mean d needs a long-run variance estimator under dependence assumptions.', 'Target h ngày chồng lấn chia sẻ h−k return ở lag k<h; bất định của mean d cần ước lượng long-run variance dưới giả thiết phụ thuộc.', ['Draw the two target windows at lag k and count their shared return observations.', 'Vẽ hai cửa sổ target cách k lag rồi đếm return quan sát chung.'], ['Translate shared targets into possible serial dependence through lag h−1; pairing aligns methods but does not make dates independent.', 'Chuyển phần target chung thành phụ thuộc chuỗi đến lag h−1; ghép cặp căn chỉnh phương pháp nhưng không làm ngày độc lập.'], ['Propose HAC with justified bandwidth/dependence or a justified block method, and state the estimand and assumptions.', 'Đề xuất HAC với bandwidth/phụ thuộc được biện minh hoặc block method hợp lệ, đồng thời nêu estimand và giả thiết.']),
  L('m2-w077-e5', 'Truncating a negative lag covariance at full weight can produce an impossible negative variance estimate; Bartlett downweighting preserves PSD.', 'Cắt lag covariance âm với trọng số đầy đủ có thể cho phương sai âm bất khả thi; giảm trọng số Bartlett giữ PSD.', 'Raw γ̂₀+2γ̂₁ can be negative; Bartlett b=1 uses γ̂₀+2(1/2)γ̂₁.', 'γ̂₀+2γ̂₁ thô có thể âm; Bartlett b=1 dùng γ̂₀+2(1/2)γ̂₁.', ['Compute the raw lag-one truncation with the supplied covariance.', 'Tính cắt lag một thô với covariance đã cho.'], ['Apply Bartlett weight 1−1/(1+1)=1/2 and recompute.', 'Áp trọng số Bartlett 1−1/(1+1)=1/2 rồi tính lại.'], ['Attribute nonnegativity to the positive-definite window construction, not to every possible covariance truncation.', 'Quy tính không âm cho cấu trúc cửa sổ xác định dương, không phải mọi cách cắt covariance.']),
  L('m2-w078-e1', 'A moving-block replicate concatenates the specified adjacent pairs, preserving local order within each sampled block.', 'Một mẫu bootstrap moving-block nối các cặp kề được chỉ định, giữ thứ tự cục bộ bên trong mỗi block.', 'For starts s₁,…,s_k and block length b, X*=(X_{s₁:s₁+b−1},…,X_{s_k:s_k+b−1}); choose k so kb=n.', 'Với điểm đầu s₁,…,s_k và độ dài block b, X*=(X_{s₁:s₁+b−1},…,X_{s_k:s_k+b−1}); chọn k sao kb=n.', ['Read each 1-indexed start and take exactly b consecutive values.', 'Đọc từng điểm đầu đánh số từ một và lấy đúng b giá trị liên tiếp.'], ['Concatenate sampled blocks in the stated order and verify the replicate length equals six.', 'Nối block theo đúng thứ tự và kiểm tra mẫu bootstrap có độ dài sáu.'], ['Sum and divide by six for the mean; distinguish preserved within-block adjacency from artificial block joins.', 'Cộng rồi chia sáu để lấy mean; phân biệt kề nhau được giữ trong block với mối nối block nhân tạo.']),
  L('m2-w078-e2', 'Under bounded stationary m-dependence, conditional bootstrap variance is controlled by empirical block-square averages plus a centering correction.', 'Dưới dừng và m-dependence bị chặn, phương sai bootstrap có điều kiện được kiểm soát bởi trung bình bình phương block mẫu cộng hiệu chỉnh tâm.', 'For block sums S_j, A_n=(Nb)⁻¹ΣS_j²→pΩ when b→∞, b/n→0, b³/n→0; Var_*(√(kb)Z̄*)=A_n−bM_n².', 'Với tổng block S_j, A_n=(Nb)⁻¹ΣS_j²→pΩ khi b→∞, b/n→0, b³/n→0; Var_*(√(kb)Z̄*)=A_n−bM_n².', ['Compute E[A_n]=E[S₁²]/b and expand the block-sum variance into Bartlett-weighted covariances, which tends to Ω under fixed m-dependence.', 'Tính E[A_n]=E[S₁²]/b và khai triển phương sai tổng block thành covariance trọng số Bartlett, tiến về Ω dưới m-dependence cố định.'], ['Bound block squares and count only O(N(b+m)) potentially dependent block pairs; this yields Var(A_n)=O(b³/n) and convergence by Chebyshev.', 'Chặn bình phương tổng block và chỉ đếm O(N(b+m)) cặp block có thể phụ thuộc; suy Var(A_n)=O(b³/n) và hội tụ nhờ Chebyshev.'], ['Control empirical centering via edge multiplicities and show bM_n²=o_p(1); contrast IID b=1, where the sample variance remains consistent, with dependent b=1.', 'Kiểm soát việc trừ trung bình mẫu qua trọng số biên và chứng minh bM_n²=o_p(1); phân biệt IID b=1 nhất quán với b=1 khi có phụ thuộc.']),
  L('m2-w078-e3', 'At four common forecast origins, paired A-minus-B losses estimate one mean contrast; a dependent interval targets its long-run sampling uncertainty.', 'Tại bốn mốc forecast chung, loss A trừ B theo cặp ước lượng một chênh mean; khoảng phụ thuộc nhắm bất định lấy mẫu dài hạn.', 'dₜ=ℓ_A,t−ℓ_B,t; d̄=n⁻¹Σdₜ, and Var(d̄ₙ)≈Ω_d/n under a stationary dependence CLT.', 'dₜ=ℓ_A,t−ℓ_B,t; d̄=n⁻¹Σdₜ, và Var(d̄ₙ)≈Ω_d/n dưới CLT phụ thuộc dừng.', ['Subtract B’s loss from A’s at each matching origin, preserving pairing.', 'Lấy loss B trừ khỏi A tại mỗi mốc tương ứng, giữ ghép cặp.'], ['Average the four differences and translate the sign using the stated A−B convention.', 'Lấy trung bình bốn chênh lệch và diễn giải dấu theo quy ước A−B.'], ['Describe a block/HAC interval as uncertainty about the stationary mean contrast, not as independent evidence or a future-profit guarantee.', 'Mô tả khoảng block/HAC là bất định về chênh mean dừng, không phải bằng chứng độc lập hay bảo đảm lợi nhuận tương lai.']),
  L('m2-w078-e4', 'A sign-flip randomization test is exact only when the joint conditional law is invariant under independent sign changes; pairwise symmetry is not enough.', 'Kiểm định sign-flip chính xác khi luật có điều kiện chung bất biến qua đổi dấu độc lập; đối xứng từng cặp là chưa đủ.', 'With fixed magnitudes and IID fair signs, p=2⁻ⁿΣ_g1{T(gd)≥T(d)} is super-uniform; ties count in the upper tail.', 'Với trị tuyệt đối cố định và dấu công bằng IID, p=2⁻ⁿΣ_g1{T(gd)≥T(d)} là super-uniform; tính cả hòa ở đuôi trên.', ['Condition on magnitudes and count all 2ⁿ sign vectors with multiplicity; state the joint independent-fair-sign assumption.', 'Điều kiện theo trị tuyệt đối và đếm đủ 2ⁿ vector dấu có lặp; nêu giả thiết dấu chung độc lập, công bằng.'], ['Rank the observed statistic among all flipped statistics and include ties to ensure the upper-tail p-value is conservative.', 'Xếp hạng statistic quan sát trong toàn bộ statistic đổi dấu và tính hòa để p-value đuôi trên bảo thủ.'], ['For (Z,Z), enumerate four independent flips and compare their p-value with the true paired law; identify failure of joint invariance.', 'Với (Z,Z), liệt kê bốn lần đổi dấu độc lập rồi so p-value với luật paired thật; chỉ ra thiếu bất biến chung.']),
  L('m2-w078-e5', 'Pooling blocks from before and after a mean break creates a mixture, not repeated samples from one stationary law.', 'Gộp block trước và sau mean break tạo hỗn hợp, không phải mẫu lặp từ một luật dừng.', 'A stationary block-bootstrap target assumes one time-invariant distribution/dependence structure for the resampled series.', 'Target bootstrap block dừng giả định một cấu trúc phân phối/phụ thuộc bất biến theo thời gian cho chuỗi lấy mẫu.', ['Compute the two regime means from Xₜ=εₜ and Xₜ=5+εₜ.', 'Tính mean hai chế độ từ Xₜ=εₜ và Xₜ=5+εₜ.'], ['Explain how pooled resampling randomizes regime composition and boundary placement across replicates.', 'Giải thích lấy mẫu gộp làm ngẫu nhiên thành phần chế độ và vị trí biên giữa các lần lặp.'], ['Choose a different target: model the break, resample within prespecified stable regimes, or define a regime-specific estimand.', 'Chọn target khác: mô hình hóa break, bootstrap trong chế độ ổn định định trước, hoặc xác định estimand theo chế độ.']),
  L('m2-w079-e1', 'A two-dimensional hidden state observed through one scalar measurement requires a dimension audit before computing the Kalman update.', 'Trạng thái ẩn hai chiều quan sát qua một phép đo vô hướng cần kiểm tra kích thước trước khi cập nhật Kalman.', 'S=HP⁻Hᵀ+R; K=P⁻HᵀS⁻¹; m⁺=m⁻+K(y−Hm⁻); P⁺=P⁻−P⁻HᵀS⁻¹HP⁻.', 'S=HP⁻Hᵀ+R; K=P⁻HᵀS⁻¹; m⁺=m⁻+K(y−Hm⁻); P⁺=P⁻−P⁻HᵀS⁻¹HP⁻.', ['Check shapes: P is 2×2, H is 1×2, S is scalar and K is 2×1.', 'Kiểm tra kích thước: P là 2×2, H là 1×2, S vô hướng và K là 2×1.'], ['Compute HP⁻Hᵀ and add R, then calculate P⁻Hᵀ/S and multiply by the scalar innovation.', 'Tính HP⁻Hᵀ rồi cộng R, sau đó tính P⁻Hᵀ/S và nhân innovation vô hướng.'], ['Update covariance with the stated formula, check symmetry and eigenvalues, and keep prior/posterior notation distinct.', 'Cập nhật covariance theo công thức, kiểm tra đối xứng và trị riêng, đồng thời phân biệt ký hiệu prior/posterior.']),
  L('m2-w079-e2', 'The Kalman gain is chosen so the updated state error is uncorrelated with the observation residual; Gaussianity turns that into a conditional-mean formula.', 'Kalman gain được chọn để sai số trạng thái sau cập nhật không tương quan với residual quan sát; Gaussian biến điều này thành công thức kỳ vọng có điều kiện.', 'For e=x−m and r=He+v, Cov(e−Kr,r)=PHᵀ−KS=0, so K=PHᵀS⁻¹.', 'Với e=x−m và r=He+v, Cov(e−Kr,r)=PHᵀ−KS=0, nên K=PHᵀS⁻¹.', ['Compute Cov(e,r)=PHᵀ and Cov(r,r)=S from independent state error and observation noise.', 'Tính Cov(e,r)=PHᵀ và Cov(r,r)=S từ sai số trạng thái và nhiễu quan sát độc lập.'], ['Solve the orthogonality equation for K, checking S is invertible.', 'Giải phương trình trực giao để tìm K, kiểm tra S khả nghịch.'], ['Use joint Gaussianity: zero covariance implies independence of residual and r, hence conditional expectation of residual is zero.', 'Dùng Gaussian chung: covariance bằng không suy ra residual độc lập với r, nên kỳ vọng có điều kiện của residual bằng không.']),
  L('m2-w079-e3', 'State prediction maps prior covariance through F and adds independent process noise Q to account for uncertainty introduced during transition.', 'Dự báo trạng thái biến đổi covariance prior qua F rồi cộng nhiễu quá trình Q độc lập để tính bất định chuyển tiếp.', 'If xₜ=Fxₜ₋₁+wₜ with independent Cov(wₜ)=Q, then P⁻ₜ=FPₜ₋₁Fᵀ+Q.', 'Nếu xₜ=Fxₜ₋₁+wₜ với Cov(wₜ)=Q độc lập thì P⁻ₜ=FPₜ₋₁Fᵀ+Q.', ['Multiply covariance by F on the left and Fᵀ on the right for the transformed state.', 'Nhân covariance với F bên trái và Fᵀ bên phải cho trạng thái đã biến đổi.'], ['Use independence to remove cross-covariance terms, then add Q.', 'Dùng tính độc lập để bỏ hạng covariance chéo rồi cộng Q.'], ['For the supplied matrices compute FFᵀ entrywise and add the diagonal noise matrix; state what omission of Q would do.', 'Với ma trận đã cho, tính FFᵀ từng phần tử rồi cộng ma trận nhiễu đường chéo; nêu hậu quả nếu bỏ Q.']),
  L('m2-w079-e4', 'A deterministic state is recoverable from a finite observation sequence exactly when the stacked observability matrix has no hidden state direction.', 'Trạng thái xác định khôi phục được từ chuỗi quan sát hữu hạn khi ma trận quan sát xếp chồng không có hướng trạng thái ẩn.', 'Y=Ox₀; x₀ is unique iff ker(O)={0}, equivalently rank(O)=d.', 'Y=Ox₀; x₀ duy nhất khi và chỉ khi ker(O)={0}, tương đương rank(O)=d.', ['Stack y₀,…,y_{d−1} to obtain O x₀ with block rows H,HF,…,HF^{d−1}.', 'Xếp y₀,…,y_{d−1} để được Ox₀ với các hàng khối H,HF,…,HF^{d−1}.'], ['If O has full column rank, subtract two candidate equations and infer their state difference is zero.', 'Nếu O đủ hạng cột, trừ hai phương trình ứng viên và suy ra hiệu trạng thái bằng không.'], ['If rank is deficient, choose nonzero δ in ker(O); x₀ and x₀+δ yield identical observations.', 'Nếu thiếu hạng, chọn δ khác không trong ker(O); x₀ và x₀+δ cho quan sát giống nhau.']),
  L('m2-w079-e5', 'A sensor that reads only the first coordinate of a static two-state system never reveals changes in its second coordinate.', 'Cảm biến chỉ đọc tọa độ đầu của hệ hai trạng thái tĩnh không bao giờ phát hiện thay đổi tọa độ thứ hai.', 'For F=I₂ and H=[1,0], O=[H;HF]=[[1,0],[1,0]], so rank(O)=1<2 and (0,1)∈ker(O).', 'Với F=I₂, H=[1,0], O=[H;HF]=[[1,0],[1,0]], nên rank(O)=1<2 và (0,1)∈ker(O).', ['Build the two block rows H and HF using F=I₂.', 'Lập hai hàng khối H và HF với F=I₂.'], ['Calculate rank and find a nonzero null vector explicitly.', 'Tính hạng và tìm tường minh vector không khác không.'], ['Interpret the null direction as an observationally invisible state; a prior may regularize it but data do not identify it.', 'Diễn giải hướng null là trạng thái vô hình với quan sát; prior có thể regularize nhưng dữ liệu không nhận diện được.']),
  L('m2-w080-e1', 'A scalar Gaussian innovation r=−1.5 with variance 2.25 contributes one normalized residual and one log-determinant penalty.', 'Innovation Gaussian vô hướng r=−1.5, variance 2.25 đóng góp residual chuẩn hóa và penalty log-determinant.', 'ℓₜ=−½[log(2π)+log|Sₜ|+rₜᵀSₜ⁻¹rₜ] for an m-dimensional Gaussian observation.', 'ℓₜ=−½[log(2π)+log|Sₜ|+rₜᵀSₜ⁻¹rₜ] cho quan sát Gaussian m chiều.', ['Compute the Mahalanobis term r²/S using the supplied scalar values.', 'Tính hạng Mahalanobis r²/S từ giá trị vô hướng đã cho.'], ['Insert log(2π), log(S) and the quadratic term with the common factor −1/2.', 'Thế log(2π), log(S) và hạng quadratic với hệ số chung −1/2.'], ['Round only at the end and call this the observation’s conditional log-likelihood contribution.', 'Chỉ làm tròn cuối cùng và gọi đây là đóng góp log-likelihood có điều kiện của quan sát.']),
  L('m2-w080-e2', 'A dependent time series still factors into sequential conditional observation densities by the chain rule; each density carries the observed history.', 'Chuỗi phụ thuộc vẫn phân tích thành tích mật độ có điều kiện tuần tự theo quy tắc dây chuyền; mỗi mật độ giữ thông tin lịch sử.', 'p(y₁:T)=∏ₜp(yₜ|y₁:t−1); under Gaussian innovations, sum −½[m log(2π)+log|Sₜ|+rₜᵀSₜ⁻¹rₜ].', 'p(y₁:T)=∏ₜp(yₜ|y₁:t−1); với innovation Gaussian, cộng −½[m log(2π)+log|Sₜ|+rₜᵀSₜ⁻¹rₜ].', ['Apply the probability chain rule to the joint density without asserting identical or independent observations.', 'Áp dụng quy tắc dây chuyền xác suất cho mật độ chung mà không giả định quan sát giống nhau hay độc lập.'], ['Insert the model’s conditional Gaussian mean and covariance for each history-dependent factor.', 'Thế mean và covariance Gaussian có điều kiện theo lịch sử của từng thừa số.'], ['Take logs to turn the product into a sum; explain that dependence is represented in the conditional parameters.', 'Lấy log để đổi tích thành tổng; giải thích phụ thuộc nằm trong tham số có điều kiện.']),
  L('m2-w080-e3', 'A scalar Riccati measurement update shrinks prior variance by the information supplied through a noisy observation.', 'Cập nhật đo lường Riccati vô hướng làm giảm phương sai prior nhờ thông tin của phép đo có nhiễu.', 'S=H²P⁻+R; K=P⁻H/S; P⁺=P⁻−(P⁻H)²/S.', 'S=H²P⁻+R; K=P⁻H/S; P⁺=P⁻−(P⁻H)²/S.', ['Compute innovation variance S from H, P⁻ and R.', 'Tính phương sai innovation S từ H, P⁻ và R.'], ['Compute gain K and covariance reduction term using the same S.', 'Tính gain K và hạng giảm covariance với cùng S.'], ['Subtract from P⁻ and verify nonnegativity; a positive observation-noise variance prevents overconfident collapse in this fixture.', 'Trừ khỏi P⁻ rồi kiểm tra không âm; phương sai nhiễu quan sát dương ngăn sụp tự tin trong ví dụ này.']),
  L('m2-w080-e4', 'Standardized innovations should be conditionally standard normal and serially independent under a correctly specified Gaussian state-space model.', 'Innovation chuẩn hóa cần Gaussian chuẩn có điều kiện và độc lập theo thời gian nếu mô hình state-space Gaussian đúng.', 'zₜ=Sₜ⁻¹/²rₜ should have conditional N(0,I) law and no serial dependence under the exact model.', 'zₜ=Sₜ⁻¹/²rₜ cần có luật N(0,I) có điều kiện và không phụ thuộc chuỗi theo mô hình chính xác.', ['Check location, scale, tails and quantile calibration of standardized residuals.', 'Kiểm tra vị trí, độ phân tán, đuôi và hiệu chỉnh phân vị của residual chuẩn hóa.'], ['Separately inspect temporal order with an ACF or portmanteau diagnostic; this tests a property a histogram cannot see.', 'Riêng kiểm tra thứ tự thời gian bằng ACF hoặc chẩn đoán portmanteau; histogram không thấy được tính chất này.'], ['State that model parameters and forecast information must respect the conditioning history; distinguish diagnostic evidence from proof of correctness.', 'Nêu tham số mô hình và thông tin dự báo phải tôn trọng lịch sử điều kiện; phân biệt bằng chứng chẩn đoán với chứng minh mô hình đúng.']),
  L('m2-w080-e5', 'Alternating +1 and −1 innovations can create a symmetric pooled histogram while exposing deterministic lag-one dependence.', 'Innovation luân phiên +1, −1 tạo histogram gộp đối xứng nhưng bộc lộ phụ thuộc lag một xác định.', 'A marginal histogram estimates the one-time law; lag-one covariance/correlation and a portmanteau statistic use temporal order.', 'Histogram biên ước lượng luật tại một thời điểm; covariance/tương quan lag một và statistic portmanteau dùng thứ tự thời gian.', ['Compute the pooled mean and variance, noting they can look centered and unit-scale.', 'Tính mean và phương sai gộp, lưu ý chúng có thể trông như tâm không và scale một.'], ['Pair consecutive values to calculate lag-one dependence, which is strongly negative for the alternating sequence.', 'Ghép cặp giá trị liên tiếp để tính phụ thuộc lag một, âm mạnh với dãy luân phiên.'], ['Choose an ordered-residual diagnostic and explain why pooling destroys the evidence of the pattern.', 'Chọn chẩn đoán residual có thứ tự và giải thích việc gộp làm mất bằng chứng của quy luật.']),
  L('m2-w081-e1', 'One Rauch–Tung–Striebel smoothing step uses the next filtered-to-predicted correction to revise the previous state and uncertainty.', 'Một bước làm trơn Rauch–Tung–Striebel dùng hiệu chỉnh filtered-so-với-predicted ở bước sau để sửa trạng thái và bất định trước.', 'm_{t|T}=m_{t|t}+J_t(m_{t+1|T}−m_{t+1|t}); P_{t|T}=P_{t|t}+J_t(P_{t+1|T}−P_{t+1|t})J_tᵀ.', 'm_{t|T}=m_{t|t}+J_t(m_{t+1|T}−m_{t+1|t}); P_{t|T}=P_{t|t}+J_t(P_{t+1|T}−P_{t+1|t})J_tᵀ.', ['Compute the future mean correction 1−3 and multiply by J=.25 before adding to the filtered mean.', 'Tính hiệu chỉnh mean tương lai 1−3, nhân J=.25 rồi cộng vào mean filtered.'], ['Compute the covariance correction 1−4 and multiply by J² before adding to P_{t|t}.', 'Tính hiệu chỉnh covariance 1−4, nhân J² rồi cộng vào P_{t|t}.'], ['Check that the smoother reduces this scalar uncertainty and keep future-conditioned notation t|T distinct from real-time t|t.', 'Kiểm tra smoother giảm bất định vô hướng này và phân biệt ký hiệu điều kiện tương lai t|T với thời gian thực t|t.']),
  L('m2-w081-e2', 'Conditioning xₜ on the next predicted state uses their cross-covariance divided by the next-state covariance.', 'Điều kiện xₜ theo trạng thái dự báo kế tiếp dùng covariance chéo của chúng chia covariance trạng thái kế tiếp.', 'Jₜ=Cov(xₜ,xₜ₊₁|y₁:ₜ)Pₜ₊₁|ₜ⁻¹=Pₜ|ₜFᵀPₜ₊₁|ₜ⁻¹.', 'Jₜ=Cov(xₜ,xₜ₊₁|y₁:ₜ)Pₜ₊₁|ₜ⁻¹=Pₜ|ₜFᵀPₜ₊₁|ₜ⁻¹.', ['Write the conditional Gaussian regression coefficient as cross-covariance times inverse covariance of the conditioning vector.', 'Viết hệ số hồi quy Gaussian có điều kiện bằng covariance chéo nhân nghịch đảo covariance vector điều kiện.'], ['Insert Cov(xₜ,xₜ₊₁|past)=Pₜ|ₜFᵀ and derive the conditional mean around the predicted means.', 'Thế Cov(xₜ,xₜ₊₁|quá khứ)=Pₜ|ₜFᵀ và suy mean có điều kiện quanh các mean dự báo.'], ['Check invertibility of Pₜ₊₁|ₜ; for a singular covariance condition on its support instead of blindly inverting.', 'Kiểm tra Pₜ₊₁|ₜ khả nghịch; nếu covariance suy biến thì điều kiện trên support thay vì nghịch đảo máy móc.']),
  L('m2-w081-e3', 'The second state coordinate evolves by an unstable factor 1.2 but is never observed when H=[1,0].', 'Tọa độ trạng thái thứ hai nhân với hệ số bất ổn 1.2 nhưng không bao giờ được quan sát khi H=[1,0].', 'O=[H;HF;…]; unobservable eigenmodes lie in ker(O); detectability requires every unobservable mode to be stable.', 'O=[H;HF;…]; mode không quan sát được nằm trong ker(O); detectability đòi mọi mode đó phải ổn định.', ['Compute HFᵏ for the diagonal F and show the second column remains zero.', 'Tính HFᵏ với F chéo và chứng minh cột thứ hai luôn bằng không.'], ['Identify the invisible eigenvalue from F and compare its modulus with one.', 'Nhận diện trị riêng vô hình từ F rồi so modulus với một.'], ['Apply the stated detectability definition: this mode is unobservable and unstable, so the pair fails detectability.', 'Áp dụng định nghĩa detectability: mode này không quan sát được và bất ổn nên cặp không detectability.']),
  L('m2-w081-e4', 'Sizing a position at time t with a fixed-interval smoothed state uses observations after t, which were not available at the decision.', 'Định cỡ vị thế tại t bằng trạng thái smoother khoảng cố định dùng quan sát sau t, vốn chưa có lúc ra quyết định.', 'Real-time filtering uses x_{t|t}=E[xₜ|y₁:ₜ]; smoothing x_{t|T}=E[xₜ|y₁:T] includes future data when T>t.', 'Filtering thời gian thực dùng x_{t|t}=E[xₜ|y₁:ₜ]; smoothing x_{t|T}=E[xₜ|y₁:T] gồm dữ liệu tương lai khi T>t.', ['List the information set used by x_{t|T} and isolate observations y_{t+1:T}.', 'Liệt kê tập thông tin x_{t|T} dùng rồi tách các quan sát y_{t+1:T}.'], ['Compare that set with what exists at the time-t order; this establishes look-ahead leakage.', 'So sánh tập đó với thông tin có lúc đặt lệnh t; điều này xác định leakage nhìn trước.'], ['Replace it with x_{t|t} and require parameter estimation/training to use data available by t or a frozen earlier window.', 'Thay bằng x_{t|t} và yêu cầu ước lượng tham số/huấn luyện chỉ dùng dữ liệu có tới t hoặc cửa sổ trước đã đóng băng.']),
  L('m2-w081-e5', 'A static filter can absorb a fixed sensor offset into its latent level, making post-burn-in innovations look centered despite model mismatch.', 'Bộ lọc trạng thái tĩnh có thể hấp thụ offset cảm biến cố định vào mức ẩn, khiến innovation sau burn-in trông đã tâm dù mô hình sai.', 'With prior θ~N(0,1) and yₜ=5+vₜ, predictive m_{t−1}=Σ_{s<t}y_s/t, so E[rₜ]=5/t→0.', 'Với prior θ~N(0,1) và yₜ=5+vₜ, mean dự báo m_{t−1}=Σ_{s<t}y_s/t nên E[rₜ]=5/t→0.', ['Derive the posterior predictive mean after t−1 observations as the sample mean with the unit prior’s contribution.', 'Suy mean dự báo posterior sau t−1 quan sát như trung bình mẫu có đóng góp prior đơn vị.'], ['Subtract that predictive mean from E[yₜ]=5 to obtain the shrinking pre-update innovation bias.', 'Trừ mean dự báo khỏi E[yₜ]=5 để thu độ chệch innovation trước cập nhật đang giảm.'], ['Explain non-identifiability between true level and sensor offset; require anchoring/calibration or joint identifiability, since a centered histogram cannot separate them.', 'Giải thích không nhận diện giữa mức thật và offset cảm biến; cần neo/hiệu chuẩn hoặc nhận diện chung vì histogram tâm không tách được hai thứ.']),
  L('m2-w082-e1', 'A forecast N(1,1) shifts one unit from the true N(0,1), yielding a fixed excess expected log loss.', 'Dự báo N(1,1) lệch mean một đơn vị so với N(0,1) thật, tạo excess log loss kỳ vọng cố định.', 'For equal-variance normals, KL(N(μ₀,σ²)||N(μ₁,σ²))=(μ₀−μ₁)²/(2σ²).', 'Với hai Gaussian cùng phương sai, KL(N(μ₀,σ²)||N(μ₁,σ²))=(μ₀−μ₁)²/(2σ²).', ['Write the mean difference and shared variance under the true-to-forecast KL direction.', 'Viết chênh mean và phương sai chung theo hướng KL thật đến dự báo.'], ['Substitute the one-unit mean shift and unit variance into the formula.', 'Thế độ lệch mean một và phương sai một vào công thức.'], ['Interpret the nonnegative KL as excess expected negative log score per observation, in nats.', 'Diễn giải KL không âm là excess negative log-score kỳ vọng mỗi quan sát, tính bằng nat.']),
  L('m2-w082-e2', 'Strict propriety of the logarithmic score follows from KL nonnegativity, including careful treatment when the forecast assigns zero density.', 'Tính proper nghiêm ngặt của log score suy từ KL không âm, kể cả xử lý cẩn thận khi forecast gán mật độ bằng không.', 'E_q[−log p(Y)]−E_q[−log q(Y)]=KL(q||p)≥0, with equality iff p=q almost everywhere under the stated support conditions.', 'E_q[−log p(Y)]−E_q[−log q(Y)]=KL(q||p)≥0, đẳng thức khi và chỉ khi p=q hầu khắp nơi dưới điều kiện support đã nêu.', ['If p=0 on a set with positive q-mass, record infinite score divergence as the immediate case.', 'Nếu p=0 trên tập có q-mass dương, ghi nhận divergence điểm bằng vô hạn ngay.'], ['Otherwise restrict integration to A={q>0} and apply −log u≥1−u to u=p/q.', 'Nếu không, giới hạn tích phân trên A={q>0} và áp −log u≥1−u với u=p/q.'], ['Use ∫_A p≤1 to prove nonnegativity; equality forces p=q on A and no forecast mass outside A.', 'Dùng ∫_A p≤1 để chứng minh không âm; đẳng thức buộc p=q trên A và forecast không đặt khối lượng ngoài A.']),
  L('m2-w082-e3', 'For each continuous conditional forecast CDF, transforming its realized outcome by that CDF should produce a conditional uniform variable.', 'Với mỗi CDF forecast có điều kiện liên tục, biến đổi outcome thực tế qua CDF đó tạo biến đều có điều kiện.', 'If Yₜ|Fₜ₋₁ has continuous CDF Fₜ, then P(Fₜ(Yₜ)≤u|Fₜ₋₁)=u for 0<u<1.', 'Nếu Yₜ|Fₜ₋₁ có CDF liên tục Fₜ thì P(Fₜ(Yₜ)≤u|Fₜ₋₁)=u với 0<u<1.', ['Condition on the past so Fₜ becomes a fixed continuous CDF.', 'Điều kiện theo quá khứ để Fₜ trở thành CDF liên tục cố định.'], ['Choose a quantile yᵤ with Fₜ(yᵤ)=u and identify the event up to null sets.', 'Chọn phân vị yᵤ với Fₜ(yᵤ)=u rồi đồng nhất biến cố sai khác tập không.'], ['Evaluate the conditional probability as Fₜ(yᵤ); note continuity is what removes jump/randomization complications.', 'Tính xác suất có điều kiện thành Fₜ(yᵤ); lưu ý tính liên tục loại bỏ vấn đề bước nhảy/cần ngẫu nhiên hóa.']),
  L('m2-w082-e4', 'A forecast issued after seeing the value it scores can encode the outcome and violates the required pre-outcome information timing.', 'Forecast phát hành sau khi xem giá trị được chấm có thể mã hóa outcome và vi phạm thời điểm thông tin trước outcome.', 'A valid Fₜ must be measurable with respect to Fₜ₋₁; score Yₜ only after freezing Fₜ and revealing Yₜ.', 'Fₜ hợp lệ phải đo được theo Fₜ₋₁; chỉ chấm Yₜ sau khi đóng băng Fₜ và tiết lộ Yₜ.', ['Identify that same-time Yₜ is unavailable in the sigma-field Fₜ₋₁ used to form the forecast.', 'Nhận diện Yₜ cùng thời điểm không có trong sigma-field Fₜ₋₁ dùng để lập forecast.'], ['Explain how post-outcome construction leaks the target and invalidates score interpretation.', 'Giải thích lập forecast sau outcome làm rò target và mất ý nghĩa điểm số.'], ['Specify the one-step protocol: predict from past, freeze forecast, reveal outcome, score, then update for t+1.', 'Nêu protocol một bước: dự báo từ quá khứ, đóng băng forecast, lộ outcome, chấm điểm rồi cập nhật cho t+1.']),
  L('m2-w082-e5', 'Alternating U and 1−U values have uniform marginals but deterministic negative serial dependence.', 'Giá trị luân phiên U và 1−U có phân phối biên đều nhưng phụ thuộc chuỗi âm xác định.', 'Marginal Uniform(0,1) does not imply independence; here Uₜ₊₁=1−Uₜ and Corr(Uₜ,Uₜ₊₁)=−1.', 'Biên Uniform(0,1) không suy ra độc lập; ở đây Uₜ₊₁=1−Uₜ và Corr(Uₜ,Uₜ₊₁)=−1.', ['Use symmetry of the uniform distribution to show both U and 1−U are individually uniform.', 'Dùng đối xứng của phân phối đều để chứng minh U và 1−U đều có phân phối biên đều.'], ['Write the deterministic relation across adjacent times and compute its correlation.', 'Viết quan hệ xác định giữa hai thời điểm kề rồi tính tương quan.'], ['Separate a marginal PIT histogram check from serial-independence and conditional-calibration diagnostics.', 'Tách kiểm tra histogram PIT biên khỏi chẩn đoán độc lập chuỗi và hiệu chỉnh có điều kiện.']),
  L('m2-w083-e1', 'A three-day rolling sum reuses innovations in adjacent forecasts; count shared terms at each lag before estimating mean uncertainty.', 'Tổng trượt ba ngày tái sử dụng innovation giữa forecast kề; đếm số hạng chung theo lag trước khi ước lượng bất định mean.', 'If Rₜ=Σ_{j=1}^h ε_{t+j}, IID variance σ², then γ(k)=(h−k)σ² for 0≤k<h and Ω=h²σ².', 'Nếu Rₜ=Σ_{j=1}^h ε_{t+j}, innovation IID phương sai σ², thì γ(k)=(h−k)σ² với 0≤k<h và Ω=h²σ².', ['Count h innovations in one window for Var(Rₜ).', 'Đếm h innovation trong một cửa sổ để tính Var(Rₜ).'], ['At lags one and two, count the shared terms and multiply by σ²; at lag three no terms overlap.', 'Ở lag một và hai, đếm số hạng chung rồi nhân σ²; lag ba không còn chồng.'], ['Sum zero, positive and negative lags to obtain Ω; compare with marginal variance to quantify overlap inflation.', 'Cộng lag không, dương và âm để có Ω; so với phương sai biên để lượng hóa khuếch đại do chồng lấn.']),
  L('m2-w083-e2', 'Variance of a paired average depends on how many pairs of origins are separated by each lag, with IID as the zero-covariance special case.', 'Phương sai trung bình paired phụ thuộc số cặp mốc cách nhau từng lag; IID là trường hợp riêng covariance khác không bằng không.', 'Var(d̄ₙ)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ_d(h); IID leaves γ_d(0)/n.', 'Var(d̄ₙ)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ_d(h); IID chỉ còn γ_d(0)/n.', ['Expand the variance of the sum as a double covariance sum.', 'Khai triển phương sai tổng thành tổng covariance kép.'], ['Count n−|h| pairs at each signed lag and divide by n² for the average.', 'Đếm n−|h| cặp tại mỗi lag có dấu rồi chia n² cho trung bình.'], ['State that under IID nonzero-lag terms vanish, yielding the familiar variance-of-one-observation divided by n.', 'Nêu dưới IID các hạng lag khác không triệt tiêu, thu phương sai một quan sát chia n.']),
  L('m2-w083-e3', 'Five paired forecast-origin differences give a descriptive average, but a dependence-aware interval also needs long-run variance and a justified reference limit.', 'Năm chênh lệch forecast paired cho trung bình mô tả, nhưng khoảng phụ thuộc cần long-run variance và giới hạn tham chiếu hợp lệ.', 'd̄=n⁻¹Σdₜ; under a suitable stationary CLT, SE(d̄)≈√(Ω_d/n).', 'd̄=n⁻¹Σdₜ; dưới CLT dừng thích hợp, SE(d̄)≈√(Ω_d/n).', ['Sum the five supplied paired differences using the stated sign convention.', 'Cộng năm chênh lệch paired theo quy ước dấu đã cho.'], ['Divide by five to compute d̄ and translate a negative sign as lower A loss.', 'Chia năm để tính d̄ và diễn giải dấu âm là loss A thấp hơn.'], ['Name Ω_d and dependence-aware estimator/reference approximation as missing; do not claim five points support reliable asymptotics.', 'Nêu Ω_d và ước lượng phụ thuộc/xấp xỉ tham chiếu là phần còn thiếu; không khẳng định năm điểm đủ asymptotics đáng tin.']),
  L('m2-w083-e4', 'A small paired MSE improvement with an HAC interval touching zero is unresolved statistically and lacks the execution inputs needed for a trading claim.', 'Cải thiện MSE paired nhỏ với khoảng HAC chạm không chưa được phân giải thống kê và thiếu đầu vào thực thi để khẳng định giao dịch.', 'For d=loss_new−loss_base, a 95% interval containing zero does not establish a strictly negative population mean; profit requires a return/cost model.', 'Với d=loss_new−loss_base, khoảng 95% chứa không không chứng minh mean tổng thể âm nghiêm ngặt; lợi nhuận cần mô hình return/chi phí.', ['Read the interval endpoints and note that zero is included.', 'Đọc hai đầu khoảng và nhận thấy có chứa không.'], ['State the descriptive direction separately from the unresolved population comparison.', 'Nêu riêng hướng mô tả với so sánh tổng thể chưa phân giải.'], ['List execution timing/prices and transaction costs plus an explicit return-risk estimand as missing for profitability.', 'Liệt kê thời điểm/giá thực thi, transaction cost và estimand return-risk tường minh còn thiếu để kết luận lợi nhuận.']),
  L('m2-w083-e5', 'One hundred twenty overlapping 12-step labels reuse shocks heavily, so their mean has far fewer IID-equivalent observations than a disjoint IID series.', 'Một trăm hai mươi nhãn chồng lấn 12 bước tái sử dụng shock nhiều, nên trung bình có ít quan sát tương đương IID hơn chuỗi IID rời.', 'For h-step overlapping sums, Ω/γ(0)=h and n_eff≈nγ(0)/Ω=n/h under this model.', 'Với tổng chồng lấn h bước, Ω/γ(0)=h và n_eff≈nγ(0)/Ω=n/h theo mô hình này.', ['Use the IID series’ stated independence to assign n_eff=n under its model.', 'Dùng tính độc lập đã nêu của chuỗi IID để đặt n_eff=n theo mô hình.'], ['Apply the rolling-sum overlap result for h=12 to the second sequence.', 'Áp kết quả tổng trượt chồng lấn với h=12 cho chuỗi thứ hai.'], ['Explain that n_eff is a model-based approximation, not a universal replacement that restores IID concentration or inference.', 'Giải thích n_eff là xấp xỉ theo mô hình, không phải phép thay thế phổ quát khôi phục concentration hay suy luận IID.']),
  L('m2-w084-e1', 'Two adjacent two-point return windows share one innovation, doubling long-run variance relative to the single-window variance.', 'Hai cửa sổ return hai điểm liền nhau chia sẻ một innovation, làm long-run variance gấp đôi phương sai từng cửa sổ.', 'For Rₜ=εₜ+εₜ₊₁ with IID variance one: γ(0)=2, γ(1)=1, Ω=γ(0)+2γ(1)=4, n_eff≈nγ(0)/Ω.', 'Với Rₜ=εₜ+εₜ₊₁, innovation IID phương sai một: γ(0)=2, γ(1)=1, Ω=γ(0)+2γ(1)=4, n_eff≈nγ(0)/Ω.', ['Count two independent shocks in one return to get its marginal variance.', 'Đếm hai shock độc lập trong một return để có phương sai biên.'], ['Count the one shared shock across adjacent returns and set all higher-lag covariance to zero.', 'Đếm shock chung giữa return kề và cho covariance lag cao hơn bằng không.'], ['Sum covariance over signed lags, then use the stated variance-ratio approximation for n_eff.', 'Cộng covariance theo lag có dấu rồi dùng xấp xỉ tỷ số phương sai đã nêu cho n_eff.']),
  L('m2-w084-e2', 'Form A joins Bartlett positive semidefiniteness, an exact one-dependent mean variance and a studentized limit under explicitly bounded dependence.', 'Đề A ghép tính nửa xác định dương Bartlett, phương sai trung bình một phụ thuộc chính xác và giới hạn studentized dưới phụ thuộc bị chặn tường minh.', 'For dₜ=εₜ−εₜ₋₁/2, γ(0)=5/4, γ(±1)=−1/2, nVar(d̄ₙ)=1/4+1/n→Ω=1/4; L→∞, L³/n→0 supports bounded m-dependent HAC consistency.', 'Với dₜ=εₜ−εₜ₋₁/2, γ(0)=5/4, γ(±1)=−1/2, nVar(d̄ₙ)=1/4+1/n→Ω=1/4; L→∞, L³/n→0 hỗ trợ tính nhất quán HAC m-dependent bị chặn.', ['First expand the Bartlett moving-window outer products and count each lag contribution; positivity follows by evaluating any quadratic form as a sum of squares.', 'Trước hết khai triển tích ngoài cửa sổ Bartlett và đếm đóng góp từng lag; tính dương theo dạng toàn phương là tổng bình phương.'], ['For dₜ, compute lag-zero and lag-one covariances, use pair counts for exact nVar, then establish Ω>0 and the bounded one-dependent CLT hypotheses.', 'Với dₜ, tính covariance lag không và một, dùng đếm cặp cho nVar chính xác, rồi xác nhận Ω>0 và giả thiết CLT một phụ thuộc bị chặn.'], ['Invoke the stated L³/n→0 HAC consistency theorem and Slutsky for studentization; explain why finite-sample PSD alone supplies neither consistency nor coverage.', 'Dùng định lý nhất quán HAC với L³/n→0 và Slutsky để studentize; giải thích PSD hữu hạn mẫu không tự cho nhất quán hay coverage.']),
  L('m2-w084-e3', 'A centered weakly stationary paired-loss process has a finite-sample Bartlett-weighted variance, whose long-run limit needs absolute summability.', 'Quá trình loss paired dừng yếu đã tâm có phương sai hữu hạn trọng số Bartlett; giới hạn long-run cần covariance khả tổng tuyệt đối.', 'Var(d̄ₙ)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ(h), and nVar(d̄ₙ)→Ω=Σ_hγ(h) if Σ_h|γ(h)|<∞.', 'Var(d̄ₙ)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ(h), và nVar(d̄ₙ)→Ω=Σ_hγ(h) nếu Σ_h|γ(h)|<∞.', ['Expand Var(d̄ₙ) into n⁻²Σ_{s,t}γ(s−t).', 'Khai triển Var(d̄ₙ) thành n⁻²Σ_{s,t}γ(s−t).'], ['Count n−|h| pairs for each lag to recover the triangular finite-sample weights.', 'Đếm n−|h| cặp cho từng lag để thu trọng số tam giác hữu hạn mẫu.'], ['Use absolute summability and dominated convergence for the long-run limit; retain both positive and negative lags.', 'Dùng khả tổng tuyệt đối và hội tụ bị chặn cho giới hạn long-run; giữ cả lag dương và âm.']),
  L('m2-w084-e4', 'Overlapping five-day paired losses within two volatility regimes should be resampled as within-regime blocks, never across the known break.', 'Loss paired năm ngày chồng lấn trong hai chế độ volatility nên bootstrap thành block bên trong chế độ, tuyệt đối không qua break đã biết.', 'Resample paired dₜ blocks inside one predeclared stationary regime; inference then targets that regime’s mean and long-run variance.', 'Bootstrap block dₜ paired bên trong một chế độ dừng định trước; suy luận nhắm mean và long-run variance của chế độ đó.', ['Keep A and B losses paired at each origin and identify the break boundary before resampling.', 'Giữ loss A/B thành cặp tại mỗi mốc và xác định biên break trước khi bootstrap.'], ['Sample contiguous blocks wholly inside a stable regime, preserving local overlap dependence and avoiding regime mixing.', 'Lấy block liên tiếp hoàn toàn bên trong chế độ ổn định, giữ phụ thuộc chồng lấn cục bộ và tránh trộn chế độ.'], ['State stationarity/weak-dependence and block-length assumptions; limit inference to the selected regime rather than one law for both.', 'Nêu giả thiết dừng/phụ thuộc yếu và độ dài block; giới hạn suy luận trong chế độ chọn thay vì một luật chung.']),
  L('m2-w084-e5', 'A random-walk level has a growing weighted-innovation variance, while its increments provide an IID target for estimating drift.', 'Mức random walk có phương sai tổng innovation có trọng số tăng, còn increments tạo target IID để ước lượng drift.', 'X̄ₙ=δ(n+1)/2+n⁻¹Σ_{j=1}ⁿ(n−j+1)εⱼ; Var(X̄ₙ)=σ²(n+1)(2n+1)/(6n); ΔXₜ=δ+εₜ.', 'X̄ₙ=δ(n+1)/2+n⁻¹Σ_{j=1}ⁿ(n−j+1)εⱼ; Var(X̄ₙ)=σ²(n+1)(2n+1)/(6n); ΔXₜ=δ+εₜ.', ['Rewrite each level Xₜ as its drift plus cumulative innovations, then reverse the sums in X̄ₙ to expose weights n−j+1.', 'Viết mỗi mức Xₜ thành drift cộng innovation tích lũy, rồi đảo tổng trong X̄ₙ để lộ trọng số n−j+1.'], ['Compute mean and variance of the weighted sum; growth of Var(X̄ₙ) rules out stationary shrinking level-mean uncertainty.', 'Tính mean và phương sai tổng có trọng số; Var(X̄ₙ) tăng bác bỏ bất định trung bình mức kiểu dừng giảm dần.'], ['Use increments Yₜ=δ+εₜ for a sample-variance studentized interval; separately show Dₜ=Z+uₜ is stationary but its mean tends to Z, not population zero.', 'Dùng increments Yₜ=δ+εₜ để lập khoảng studentized bằng phương sai mẫu; riêng chứng minh Dₜ=Z+uₜ dừng nhưng mean tiến về Z, không phải population zero.']),
  L('m2-w085-e1', 'ERM performance separates inability of the model class, finite-sample selection error and imperfect optimization of the returned model.', 'Hiệu năng ERM tách hạn chế của lớp mô hình, lỗi chọn do mẫu hữu hạn và tối ưu chưa hết của mô hình trả về.', 'R(f̃)−R*= [inf_F R−R*]+[R(f̂)−inf_F R]+[R(f̃)−R(f̂)] when terms are defined; the exercise’s fixture makes the three pieces nonnegative.', 'R(f̃)−R*= [inf_F R−R*]+[R(f̂)−inf_F R]+[R(f̃)−R(f̂)] khi các hạng được định nghĩa; ví dụ cho ba phần không âm.', ['Compute the approximation gap inf_F R−R* from the class-best risk and benchmark.', 'Tính gap xấp xỉ inf_F R−R* từ risk tốt nhất của lớp và benchmark.'], ['Compute estimation/selection R(f̂)−inf_F R using the empirical minimizer’s population risk.', 'Tính lỗi estimation/selection R(f̂)−inf_F R bằng population risk của empirical minimizer.'], ['Compute returned-iterate gap R(f̃)−R(f̂), add all three and match the telescoping endpoint R(f̃)−R*.', 'Tính gap iterate trả về R(f̃)−R(f̂), cộng cả ba và đối chiếu endpoint R(f̃)−R*.']),
  L('m2-w085-e2', 'A finite search over M bounded-loss models pays a logarithmic complexity cost to control the largest empirical-to-population deviation.', 'Tìm kiếm hữu hạn M mô hình loss bị chặn phải trả chi phí độ phức tạp log để chặn độ lệch empirical-population lớn nhất.', 'For IID data and 0≤ℓ≤1, P(sup_F|R̂−R|>ε)≤2M e^(−2nε²); ε=√[log(2M/δ)/(2n)] gives probability ≤δ.', 'Với dữ liệu IID và 0≤ℓ≤1, P(sup_F|R̂−R|>ε)≤2M e^(−2nε²); ε=√[log(2M/δ)/(2n)] cho xác suất ≤δ.', ['Apply the two-sided Hoeffding inequality to one fixed model f.', 'Áp dụng Hoeffding hai phía cho một mô hình f cố định.'], ['Union-bound across M functions to control the supremum rather than a single preselected candidate.', 'Dùng union bound trên M hàm để chặn supremum thay vì một ứng viên chọn trước.'], ['Set the upper bound equal to δ and solve logarithmically for ε; state bounded loss and IID sampling assumptions.', 'Cho cận trên bằng δ rồi giải ε theo logarithm; nêu giả thiết loss bị chặn và lấy mẫu IID.']),
  L('m2-w085-e3', 'An approximate empirical minimizer can be compared to the best population-risk member by inserting three empirical-risk differences.', 'Nghiệm empirical gần đúng có thể so với phần tử tốt nhất population bằng cách chèn ba chênh lệch risk empirical.', 'If sup_F|R̂−R|≤ε and R̂(f̃)≤min_F R̂+εopt, then R(f̃)−min_F R≤2ε+εopt.', 'Nếu sup_F|R̂−R|≤ε và R̂(f̃)≤min_F R̂+εopt thì R(f̃)−min_F R≤2ε+εopt.', ['Choose a population minimizer f*_F; finiteness ensures it exists.', 'Chọn nghiệm population f*_F; tính hữu hạn bảo đảm nghiệm tồn tại.'], ['Insert R̂(f̃), R̂(f̂) and R̂(f*_F); label the approximate-optimality term and the ERM term separately.', 'Chèn R̂(f̃), R̂(f̂), R̂(f*_F); đánh dấu riêng hạng gần tối ưu và hạng ERM.'], ['Bound the two population-empirical discrepancies by ε and use the empirical optimizer inequality; retain εopt as empirical allowance.', 'Chặn hai sai khác population-empirical bởi ε và dùng bất đẳng thức optimizer empirical; giữ εopt là sai số empirical.']),
  L('m2-w085-e4', 'Expanding a candidate search from twenty to over a million models enlarges the uniform confidence radius even if the winning model happens to be unchanged.', 'Mở rộng tìm kiếm từ hai mươi lên hơn một triệu mô hình làm bán kính tin cậy đều tăng dù mô hình thắng có thể không đổi.', 'ε(M)=√[log(2M/δ)/(2n)] for fixed n and confidence δ.', 'ε(M)=√[log(2M/δ)/(2n)] với n và mức tin cậy δ cố định.', ['Substitute n=1000, δ=.05 and M=20 into the radius formula.', 'Thế n=1000, δ=.05, M=20 vào công thức bán kính.'], ['Repeat with M=2²⁰ and compute the ratio by dividing the logarithms under the square root.', 'Lặp lại với M=2²⁰ và tính tỷ số bằng thương hai logarithm trong căn.'], ['Explain that a larger searched class pays for simultaneous control but does not force the realized selected model to generalize worse.', 'Giải thích lớp tìm rộng hơn trả chi phí kiểm soát đồng thời nhưng không buộc mô hình được chọn thực tế tổng quát hóa tệ hơn.']),
  L('m2-w085-e5', 'Adjacent 20-day labels reuse 19 daily observations, invalidating the IID product-MGF step behind finite-class Hoeffding.', 'Nhãn 20 ngày kề nhau tái sử dụng 19 quan sát ngày, làm sai bước product-MGF IID của Hoeffding cho lớp hữu hạn.', 'The finite-class bound requires IID Z_i; overlap creates dependence, and an informal n_eff substitution supplies no valid tail bound.', 'Cận lớp hữu hạn cần Z_i IID; chồng lấn tạo phụ thuộc, và thay n_eff tùy ý không tạo cận đuôi hợp lệ.', ['Mark the 20-day target window at adjacent origins and count the 19 shared days.', 'Đánh dấu cửa sổ target 20 ngày tại hai mốc kề rồi đếm 19 ngày dùng chung.'], ['Identify independence of empirical summands as the step used by Hoeffding’s MGF multiplication.', 'Nhận diện tính độc lập của số hạng empirical là bước cần cho phép nhân MGF của Hoeffding.'], ['Offer a nonoverlap design with its coarser estimand or a dependence-specific uniform theorem with stated rates; do not merely rename n.', 'Đề xuất thiết kế không chồng lấn với estimand thô hơn hoặc định lý đều phụ thuộc với rate rõ; đừng chỉ đổi tên n.']),
  L('m2-w086-e1', 'A ghost sample replaces the population expectation by a conditional sample average so Jensen controls the supremum deviation.', 'Mẫu ma thay kỳ vọng population bằng trung bình mẫu có điều kiện để Jensen chặn độ lệch supremum.', 'E sup_f|Pₙf−Pf|≤E sup_f|Pₙf−P′ₙf| for an independent IID ghost sample and measurable/separable F.', 'E sup_f|Pₙf−Pf|≤E sup_f|Pₙf−P′ₙf| với ghost sample IID độc lập và F đo được/tách được.', ['Condition on observed sample S and express Pf as E[P′ₙf|S] for each f.', 'Điều kiện theo mẫu S đã quan sát và viết Pf=E[P′ₙf|S] với từng f.'], ['Apply conditional Jensen to absolute value; take the supremum only with the stated measurability/separability justification.', 'Áp Jensen có điều kiện cho trị tuyệt đối; lấy supremum với biện minh đo được/tách được đã nêu.'], ['Take expectation over S to obtain the symmetrization direction; if measurability fails, require outer expectation or a measurable subclass.', 'Lấy kỳ vọng theo S để có chiều symmetrization; nếu thiếu tính đo được thì cần outer expectation hoặc lớp con đo được.']),
  L('m2-w086-e2', 'Exchangeable original and ghost observations permit independent Rademacher signs to swap each pair without changing the joint law.', 'Các cặp quan sát gốc-ma có tính đổi chỗ cho phép dùng dấu Rademacher độc lập hoán đổi từng cặp mà không đổi luật chung.', 'E sup_f|Pₙf−P′ₙf|≤2E sup_f|n⁻¹Σᵢσᵢf(Zᵢ)| with absolute supremum retained.', 'E sup_f|Pₙf−P′ₙf|≤2E sup_f|n⁻¹Σᵢσᵢf(Zᵢ)|, giữ supremum trị tuyệt đối.', ['For each i, note (Zᵢ,Z′ᵢ) is exchangeable, so multiplying its difference by independent σᵢ preserves joint distribution across f.', 'Với từng i, cặp (Zᵢ,Z′ᵢ) đổi chỗ được nên nhân hiệu của nó với σᵢ độc lập giữ nguyên luật chung theo f.'], ['Split the signed difference into original-sample and ghost-sample sums and apply the triangle inequality inside the supremum.', 'Tách hiệu có dấu thành tổng mẫu gốc và ghost rồi áp bất đẳng thức tam giác bên trong supremum.'], ['Take expectations; the two terms have the same distribution, giving factor two and preserving the W87 absolute-complexity convention.', 'Lấy kỳ vọng; hai hạng có cùng phân phối, sinh hệ số hai và giữ quy ước absolute-complexity của W87.']),
  L('m2-w086-e3', 'With a zero function included, empirical Rademacher complexity for the one-vector class reduces to the expected positive part of the four-sign sum.', 'Khi lớp có hàm không, empirical Rademacher complexity của lớp một vector là kỳ vọng phần dương của tổng bốn dấu.', 'R̂_abs(F)=(1/n)Eσ sup_{f∈F}|Σσᵢf(Zᵢ)|; here prompt specifies E max(0,Σσᵢ).', 'R̂_abs(F)=(1/n)Eσ sup_{f∈F}|Σσᵢf(Zᵢ)|; đề yêu cầu E max(0,Σσᵢ).', ['Enumerate the 16 equally likely four-sign vectors and group them by their sum.', 'Liệt kê 16 vector dấu đồng khả năng rồi nhóm theo tổng.'], ['For each sum apply max(0,S); count positive and zero contributions rather than dropping negative outcomes from the denominator.', 'Với mỗi tổng, tính max(0,S); đếm đóng góp dương và không, không bỏ outcome âm khỏi mẫu số.'], ['Divide the expectation by n=4 for the empirical complexity and distinguish this normalization from the unnormalized numerator.', 'Chia kỳ vọng cho n=4 để ra complexity empirical, phân biệt chuẩn hóa này với tử chưa chuẩn hóa.']),
  L('m2-w086-e4', 'A parameter selected from an expanding grid after seeing the data is not covered by convergence statements for each parameter fixed in advance.', 'Tham số chọn từ lưới mở rộng sau khi xem dữ liệu không được bảo đảm bởi hội tụ đúng cho từng tham số cố định trước.', 'Pointwise: for each fixed θ, error(θ)→0; uniform: sup_{θ∈Θₙ}error(θ)→0 controls a data-selected θ̂ₙ∈Θₙ.', 'Điểm: với từng θ cố định, error(θ)→0; đều: sup_{θ∈Θₙ}error(θ)→0 kiểm soát θ̂ₙ chọn theo dữ liệu.', ['State the quantifier order for pointwise convergence: fix θ first, then take the probability limit.', 'Nêu thứ tự lượng từ của hội tụ điểm: cố định θ trước rồi mới lấy giới hạn xác suất.'], ['Explain that the selected θ̂ₙ depends on the same noise and can target its largest fluctuation.', 'Giải thích θ̂ₙ phụ thuộc cùng nhiễu nên có thể chọn dao động lớn nhất.'], ['Give a valid route: uniform control on each sieve plus approximation bias, or independent sample splitting with its altered efficiency.', 'Nêu cách hợp lệ: kiểm soát đều trên từng sieve cộng bias xấp xỉ, hoặc tách mẫu độc lập với hiệu quả dữ liệu thay đổi.']),
  L('m2-w086-e5', 'A learner can memorize each nonatomic training input-label pair yet predict a fixed label on almost every fresh input.', 'Learner có thể ghi nhớ từng cặp input-label mẫu nonatomic nhưng dự báo nhãn cố định trên hầu hết input mới.', 'For finite sample S, define f_S(x)=Yᵢ when x=Xᵢ and 0 otherwise; if X is independent nonatomic, P(X∈{Xᵢ})=0.', 'Với mẫu hữu hạn S, đặt f_S(x)=Yᵢ khi x=Xᵢ, ngược lại 0; nếu X độc lập nonatomic thì P(X∈{Xᵢ})=0.', ['Define the sample-dependent lookup rule and resolve duplicate inputs; nonatomic sampling makes ties probability zero.', 'Định nghĩa luật tra bảng phụ thuộc mẫu và xử lý trùng input; lấy mẫu nonatomic làm xác suất trùng bằng không.'], ['Verify every training point receives its own label, giving zero empirical 0–1 loss.', 'Xác nhận mỗi điểm training nhận đúng nhãn, cho empirical 0–1 loss bằng không.'], ['Use a finite union bound to show a fresh X misses all training inputs, then independence and fair Y give fresh error one-half.', 'Dùng union bound hữu hạn để chứng minh X mới không trùng input training, rồi tính độc lập và Y công bằng cho error một nửa.']),
  L('m2-w087-e1', 'A norm-bounded linear predictor can choose its weight vector in the direction of the signed feature sum, converting a supremum into a dual norm.', 'Predictor tuyến tính có vector trọng số bị chặn chuẩn có thể chọn hướng tổng feature có dấu, đổi supremum thành chuẩn dual.', 'R̂_abs(F_B)=(B/n)E||Σσᵢxᵢ||₂≤(B/n)√Σ||xᵢ||₂²≤BR/√n.', 'R̂_abs(F_B)=(B/n)E||Σσᵢxᵢ||₂≤(B/n)√Σ||xᵢ||₂²≤BR/√n.', ['Use duality sup_{||w||≤B}|wᵀv|=B||v||₂ for the signed feature vector v.', 'Dùng đối ngẫu sup_{||w||≤B}|wᵀv|=B||v||₂ với vector feature có dấu v.'], ['Apply Jensen/Cauchy–Schwarz to bound the expected norm by the square root of its second moment.', 'Áp Jensen/Cauchy–Schwarz chặn kỳ vọng chuẩn bằng căn moment bậc hai.'], ['Expand the square; independent signs cancel cross terms, leaving Σ||xᵢ||²≤nR².', 'Khai triển bình phương; dấu độc lập triệt tiêu hạng chéo, còn Σ||xᵢ||²≤nR².']),
  L('m2-w087-e2', 'Even when a measurable class has no population-risk minimizer, an ε-near-minimizer lets the empirical optimizer inequality prove an excess bound.', 'Dù lớp đo được không có nghiệm population, nghiệm gần ε vẫn cho phép dùng bất đẳng thức optimizer empirical để chặn excess.', 'R(f̂)−inf_F R≤2 sup_g|R̂−R|+ε by comparing f̂ with f_ε and sending ε↓0.', 'R(f̂)−inf_F R≤2 sup_g|R̂−R|+ε bằng cách so f̂ với f_ε rồi cho ε↓0.', ['Choose f_ε whose population risk lies within ε of inf_F R; do not assume the infimum is attained.', 'Chọn f_ε có risk population cách inf_F R không quá ε; không giả sử infimum đạt được.'], ['Insert empirical risks for f̂ and f_ε; the middle empirical difference is nonpositive by exact ERM.', 'Chèn risk empirical của f̂ và f_ε; hiệu empirical ở giữa không dương do ERM chính xác.'], ['Bound the two endpoint deviations by the same supremum, then let ε decrease to zero.', 'Chặn hai sai lệch đầu mút bằng cùng supremum rồi cho ε tiến về không.']),
  L('m2-w087-e3', 'Squared loss composed with bounded linear predictions is Lipschitz over the prediction interval, enabling a contraction-based expected ERM bound.', 'Squared loss ghép với dự báo tuyến tính bị chặn là Lipschitz trên khoảng prediction, cho phép dùng contraction để chặn ERM kỳ vọng.', 'On |u|≤BR, |(u−y)²−y²|≤L|u| with L=2(BR+Y); expected excess≤4R̂_abs(loss)≤8LBR/√n.', 'Trên |u|≤BR, |(u−y)²−y²|≤L|u| với L=2(BR+Y); excess kỳ vọng≤4R̂_abs(loss)≤8LBR/√n.', ['Differentiate ψ_y(u)=(u−y)² on the bounded prediction interval to get L=2(BR+Y); center by ψ_y(0) without changing deviations.', 'Lấy đạo hàm ψ_y(u)=(u−y)² trên khoảng dự báo để được L=2(BR+Y); trừ ψ_y(0) không đổi độ lệch.'], ['Apply the stated absolute contraction factor two and the linear-class bound BR/√n.', 'Áp hệ số contraction trị tuyệt đối hai đã nêu và cận lớp tuyến tính BR/√n.'], ['Apply the W87 expected-excess factor four; multiply factors explicitly and label the result as an expectation bound under bounded assumptions.', 'Áp hệ số excess kỳ vọng bốn của W87; nhân rõ các hệ số và gọi đây là cận kỳ vọng dưới giả thiết bị chặn.']),
  L('m2-w087-e4', 'A richer nested model class cannot worsen approximation error, but its larger capacity term can outweigh that gain.', 'Lớp mô hình lồng phong phú hơn không làm xấu lỗi xấp xỉ, nhưng hạng độ phức tạp lớn hơn có thể lấn át lợi ích.', 'For F₁⊂F₂, inf_{F₂}R≤inf_{F₁}R; a typical bound adds estimation complexity 4E R̂_abs(L∘F) and optimization allowance.', 'Với F₁⊂F₂, inf_{F₂}R≤inf_{F₁}R; cận thường cộng complexity estimation 4E R̂_abs(L∘F) và sai số tối ưu.', ['Write the approximation error as inf_F R−R* and use set inclusion to compare it across classes.', 'Viết lỗi xấp xỉ thành inf_F R−R* rồi dùng quan hệ tập con để so giữa hai lớp.'], ['List estimation complexity and optimization error as separate terms that need not decrease with class enlargement.', 'Liệt kê complexity estimation và lỗi tối ưu là hai hạng riêng, không nhất thiết giảm khi lớp mở rộng.'], ['Conclude total bound or realized test risk may rise; this reasoning makes no claim about economic value.', 'Kết luận tổng cận hoặc test risk thực tế có thể tăng; lập luận này không khẳng định giá trị kinh tế.']),
  L('m2-w087-e5', 'One feature vector of norm n dominates the signed sum, making sample complexity B rather than the usual fixed-feature 1/√n rate.', 'Một vector feature có chuẩn n áp đảo tổng có dấu, tạo complexity B thay vì rate 1/√n khi feature được chặn cố định.', 'R̂_abs(F_B)≤(B/n)√Σ||xᵢ||²; the simplified BR/√n requires a uniform ||xᵢ||≤R independent of n.', 'R̂_abs(F_B)≤(B/n)√Σ||xᵢ||²; dạng BR/√n cần ||xᵢ||≤R đều và R không phụ thuộc n.', ['Substitute one norm-n vector and zero others into the sample-dependent expression.', 'Thế một vector chuẩn n và các vector còn lại bằng không vào biểu thức phụ thuộc mẫu.'], ['Evaluate the result and compare it with the claimed 1/√n form; the fixed-R premise is unavailable.', 'Tính kết quả rồi so với dạng 1/√n được nêu; tiền đề R cố định không có.'], ['Repair by a justified uniform norm/moment bound, target-changing clipping or the sample-dependent expression itself.', 'Sửa bằng chặn chuẩn/moment đều có biện minh, clipping làm đổi target hoặc giữ biểu thức phụ thuộc mẫu.']),
  L('m2-w088-e1', 'A constrained scalar optimum at w=2 is reproduced by a Lagrange penalty with multiplier four, which makes the penalized derivative vanish there.', 'Nghiệm constrained vô hướng w=2 được tái tạo bởi penalty Lagrange multiplier bốn, làm đạo hàm penalized bằng không tại đó.', 'For constraint g(w)=w−2≤0, stationarity is 2(w−4)+λ=0 with λ≥0 and λg(w)=0; L″=2>0.', 'Với g(w)=w−2≤0, stationarity là 2(w−4)+λ=0 với λ≥0 và λg(w)=0; L″=2>0.', ['Find the constrained minimizer by comparing the unconstrained target w=4 with feasible w≤2.', 'Tìm nghiệm constrained bằng cách so target không ràng buộc w=4 với miền khả thi w≤2.'], ['Use stationarity at the active boundary to solve λ, then check sign and complementary slackness.', 'Dùng stationarity tại biên hoạt động để tìm λ rồi kiểm tra dấu và complementary slackness.'], ['Differentiate the explicit penalized function at λ=4 and use positive second derivative to confirm its unique minimizer.', 'Lấy đạo hàm hàm penalized tường minh khi λ=4 và dùng đạo hàm bậc hai dương để xác nhận nghiệm duy nhất.']),
  L('m2-w088-e2', 'A zero subgradient of the convex Lagrangian-penalized objective gives a global minimum because its supporting inequalities add.', 'Dưới-gradient bằng không của mục tiêu Lagrangian-penalty lồi cho cực tiểu toàn cục vì các bất đẳng thức đỡ cộng lại.', 'If 0∈∂L+λ∂Ω at w*, then L(w)+λΩ(w)≥L(w*)+λΩ(w*) for all w.', 'Nếu 0∈∂L+λ∂Ω tại w*, thì L(w)+λΩ(w)≥L(w*)+λΩ(w*) với mọi w.', ['Choose subgradients g∈∂L(w*) and h∈∂Ω(w*) with g+λh=0.', 'Chọn g∈∂L(w*) và h∈∂Ω(w*) sao cho g+λh=0.'], ['Write the support inequality for L and multiply the support inequality for Ω by λ≥0.', 'Viết bất đẳng thức đỡ cho L và nhân bất đẳng thức đỡ cho Ω với λ≥0.'], ['Add them so the linear terms cancel; identify convexity and nonnegative λ as the ingredients.', 'Cộng hai bất đẳng thức để hạng tuyến tính triệt tiêu; nêu tính lồi và λ không âm là các thành phần cần.']),
  L('m2-w088-e3', 'The penalized objective J=R+λΩ and its empirical version share the same penalty, so empirical deviations cancel it while approximation and selection remain distinct.', 'Mục tiêu penalized J=R+λΩ và bản empirical có cùng penalty nên sai lệch empirical triệt tiêu penalty, còn xấp xỉ và chọn lựa vẫn riêng biệt.', 'J(f̃)−J(f*)=[J(f*)−inf J]+[J(f̂)−J(f*)]+[J(f̃)−J(f̂)]; also J(f̃)−J(f*)≤2sup_F|R−R̂|+εopt.', 'J(f̃)−J(f*)=[J(f*)−inf J]+[J(f̂)−J(f*)]+[J(f̃)−J(f̂)]; đồng thời J(f̃)−J(f*)≤2sup_F|R−R̂|+εopt.', ['Write the exact three-term telescoping identity and note its latter two signed terms need not be nonnegative.', 'Viết đồng nhất thức telescoping ba hạng chính xác và lưu ý hai hạng sau có thể âm.'], ['For the bound, insert J-hat at f̃ and f̂; empirical near-optimality bounds the middle term by εopt.', 'Với cận, chèn J-hat tại f̃ và f̂; tính gần tối ưu empirical chặn hạng giữa bởi εopt.'], ['Bound each endpoint deviation by sup|R−R̂| because λΩ cancels, distinguishing class approximation from returned empirical gap.', 'Chặn mỗi sai lệch đầu mút bằng sup|R−R̂| vì λΩ triệt tiêu; phân biệt xấp xỉ lớp với gap empirical của nghiệm trả về.']),
  L('m2-w088-e4', 'Choosing the minimum test loss among eighty penalty values reuses the test set for tuning and makes the reported score selected evidence.', 'Chọn test loss nhỏ nhất trong tám mươi giá trị penalty dùng lại test để tuning, biến score báo cáo thành bằng chứng đã chọn.', 'A valid evaluation freezes model and λ using training/validation data, then evaluates once on an untouched time-ordered test set.', 'Đánh giá hợp lệ đóng băng mô hình và λ bằng training/validation rồi đánh giá một lần trên test theo thứ tự thời gian chưa dùng.', ['Move all 80 λ comparisons into training/validation or nested rolling-origin selection.', 'Chuyển cả 80 so sánh λ vào training/validation hoặc lựa chọn rolling-origin lồng.'], ['Freeze the chosen rule before opening the final chronological holdout.', 'Đóng băng luật đã chọn trước khi mở holdout cuối theo thời gian.'], ['Report test once and account for serial dependence in uncertainty; do not present its minimum as an unbiased estimate.', 'Báo test một lần và tính phụ thuộc chuỗi trong bất định; không trình bày minimum như ước lượng không chệch.']),
  L('m2-w088-e5', 'A quadratic penalty shrinks w toward zero even when the prediction target is ten, so target risk can increase as λ grows.', 'Penalty quadratic co w về không dù target là mười, nên target risk có thể tăng khi λ tăng.', 'Minimizing (w−10)²+λw² gives w_λ=10/(1+λ) and R(w_λ)=(10λ/(1+λ))².', 'Cực tiểu (w−10)²+λw² cho w_λ=10/(1+λ) và R(w_λ)=(10λ/(1+λ))².', ['Differentiate the penalized objective and solve its first-order equation.', 'Lấy đạo hàm mục tiêu penalized rồi giải phương trình bậc nhất.'], ['Substitute w_λ into the unpenalized target risk (w−10)².', 'Thế w_λ vào target risk không penalty (w−10)².'], ['Check λ=0 gives zero target risk and examine monotonicity for λ≥0; optimization of penalized fit does not guarantee lower target risk.', 'Kiểm tra λ=0 cho target risk bằng không và xét tính tăng với λ≥0; tối ưu fit penalized không bảo đảm giảm target risk.']),
  L('m2-w089-e1', 'For diameter one and gradient bound two over 25 rounds, the optimally tuned online-gradient certificate balances its two terms.', 'Với đường kính một, gradient bound hai và 25 vòng, chứng chỉ gradient online tune tối ưu cân bằng hai hạng.', 'Reg_T≤D²/(2η)+ηG²T/2; η*=D/(G√T), giving DG√T.', 'Reg_T≤D²/(2η)+ηG²T/2; η*=D/(G√T), cho DG√T.', ['Substitute D,G,T into η*=D/(G√T).', 'Thế D,G,T vào η*=D/(G√T).'], ['Evaluate each regret-bound term using the chosen step to verify their balance.', 'Tính từng hạng cận regret với bước chọn để kiểm tra chúng cân bằng.'], ['Add them and label the result a worst-case comparator bound, not observed regret or payoff.', 'Cộng hai hạng và gọi kết quả là cận worst-case theo comparator, không phải regret hay payoff quan sát.']),
  L('m2-w089-e2', 'Euclidean projection of an online gradient proposal keeps the next action feasible and compares it with any fixed feasible u.', 'Phép chiếu Euclidean của đề xuất gradient online giữ action kế khả thi và so với mọi u khả thi cố định.', 'xₜ₊₁=Π_K(xₜ−ηgₜ) implies ||xₜ₊₁−u||²≤||xₜ−u||²−2ηgₜᵀ(xₜ−u)+η²||gₜ||².', 'xₜ₊₁=Π_K(xₜ−ηgₜ) suy ra ||xₜ₊₁−u||²≤||xₜ−u||²−2ηgₜᵀ(xₜ−u)+η²||gₜ||².', ['Set y=xₜ−ηgₜ and invoke projection optimality against u∈K.', 'Đặt y=xₜ−ηgₜ và dùng tính tối ưu phép chiếu so với u∈K.'], ['Bound distance from projection xₜ₊₁ to u by distance from y to u.', 'Chặn khoảng cách từ phép chiếu xₜ₊₁ tới u bằng khoảng cách từ y tới u.'], ['Expand the right-hand square and preserve the sign of the gradient inner product when rearranging.', 'Khai triển bình phương vế phải và giữ đúng dấu tích gradient khi biến đổi.']),
  L('m2-w089-e3', 'The OGD loss comparison follows by turning each gradient inner product into a potential decrease, then summing across the sequence.', 'So sánh loss OGD thu được khi biến mỗi tích gradient thành độ giảm potential rồi cộng toàn chuỗi.', 'Reg_T(u)≤D²/(2η)+ηG²T/2; minimizing gives η*=D/(G√T) and Reg≤DG√T.', 'Reg_T(u)≤D²/(2η)+ηG²T/2; cực tiểu cho η*=D/(G√T) và Reg≤DG√T.', ['Rearrange the one-step projection inequality for gₜᵀ(xₜ−u), with aₜ=||xₜ−u||².', 'Biến đổi bất đẳng thức chiếu một bước để chặn gₜᵀ(xₜ−u), với aₜ=||xₜ−u||².'], ['Use convexity fₜ(xₜ)−fₜ(u)≤gₜᵀ(xₜ−u), sum, and telescope the aₜ terms.', 'Dùng lồi fₜ(xₜ)−fₜ(u)≤gₜᵀ(xₜ−u), cộng và telescoping hạng aₜ.'], ['Bound a₁ by D² and each ||gₜ||² by G², then differentiate the two-term bound to optimize η.', 'Chặn a₁ bởi D² và mỗi ||gₜ||² bởi G², rồi lấy đạo hàm cận hai hạng để tối ưu η.']),
  L('m2-w089-e4', 'A learner can remain close to the best fixed weight in cumulative loss yet still have negative net return after transaction fees.', 'Learner có thể gần trọng số cố định tốt nhất về loss tích lũy nhưng vẫn âm return ròng sau phí giao dịch.', 'Static regret compares Σₜℓₜ(xₜ) with min_{u∈K}Σₜℓₜ(u); it is not a net-profit or significance statistic.', 'Static regret so Σₜℓₜ(xₜ) với min_{u∈K}Σₜℓₜ(u); nó không phải statistic lợi nhuận ròng hay ý nghĩa thống kê.', ['Report exactly the benchmark-relative statement “within 4 cumulative loss units.”', 'Báo đúng mệnh đề so benchmark “cách không quá 4 đơn vị loss tích lũy.”'], ['Report negative realized net return separately, including its fee accounting.', 'Báo return ròng thực hiện âm riêng, gồm cách hạch toán phí.'], ['Name uncertainty, timing, risk and cost assumptions needed for significance/profit; regret alone supplies none.', 'Nêu giả thiết bất định, thời điểm, rủi ro và chi phí cần cho ý nghĩa/lợi nhuận; regret không tự cung cấp chúng.']),
  L('m2-w089-e5', 'When preferred signs alternate, the best action chosen with hindsight switches every round while a fixed comparator cannot follow the path.', 'Khi dấu ưa thích luân phiên, action tốt nhất nhìn lại đổi mỗi vòng còn comparator cố định không thể bám đường đi.', 'Static regret compares to one u fixed across t; dynamic regret compares to a sequence uₜ and incurs path movement cost.', 'Static regret so với một u cố định theo t; dynamic regret so với dãy uₜ và chịu chi phí biến thiên đường đi.', ['Count how often either fixed sign loses under an even alternating sequence.', 'Đếm số vòng mỗi dấu cố định bị thua trong chuỗi luân phiên có độ dài chẵn.'], ['Evaluate the per-round hindsight comparator that matches the preferred sign each time.', 'Tính comparator hindsight từng vòng luôn khớp dấu được ưa thích.'], ['Explain that the dynamic oracle uses future knowledge; a static-regret guarantee does not certify tracking.', 'Giải thích oracle động dùng thông tin tương lai; bảo đảm static regret không chứng nhận khả năng tracking.']),
  L('m2-w090-e1', 'At T=10, a schedule-specific logarithmic bound may be numerically larger than the generic square-root bound despite its better asymptotic rate.', 'Tại T=10, cận logarithmic theo lịch cụ thể có thể lớn hơn cận căn tổng quát dù rate tiệm cận tốt hơn.', 'Strong-convex schedule term=(G²/(2μ))(1+ln T)=7.4308; with optional μD²/2=.25 total=7.6808; generic DG√T≈4.7434.', 'Hạng lịch lồi mạnh=(G²/(2μ))(1+ln T)=7.4308; cộng startup tùy chọn μD²/2=.25 được 7.6808; cận tổng quát DG√T≈4.7434.', ['Substitute μ=2,G=3,T=10 into the harmonic/logarithmic expression and compute with natural logarithm.', 'Thế μ=2,G=3,T=10 vào biểu thức harmonic/logarithmic và tính log tự nhiên.'], ['If using the theorem variant with startup, add μD²/2 using D=.5 and distinguish it from the schedule-specific term.', 'Nếu dùng biến thể định lý có startup, cộng μD²/2 với D=.5 và phân biệt với hạng theo lịch.'], ['Compute DG√T independently and compare only at this horizon; finite-T ordering does not negate asymptotic O(log T) versus O(√T).', 'Tính DG√T độc lập rồi chỉ so tại horizon này; thứ tự hữu hạn không bác bỏ O(log T) so với O(√T) tiệm cận.']),
  L('m2-w090-e2', 'For strongly convex online losses and ηₜ=1/(μt), curvature creates a negative distance term that cancels across rounds.', 'Với loss online lồi mạnh và ηₜ=1/(μt), độ cong tạo hạng khoảng cách âm triệt tiêu qua các vòng.', 'Reg_T≤(G²/(2μ))Σ_{t=1}^T1/t≤(G²/(2μ))(1+ln T).', 'Reg_T≤(G²/(2μ))Σ_{t=1}^T1/t≤(G²/(2μ))(1+ln T).', ['Use strong convexity to bound the loss gap by gₜᵀ(xₜ−u)−μaₜ/2.', 'Dùng lồi mạnh chặn gap loss bởi gₜᵀ(xₜ−u)−μaₜ/2.'], ['Insert the projection inequality and ηₜ=1/(μt); collect distance coefficients as (μ/2)[(t−1)aₜ−taₜ₊₁].', 'Thế bất đẳng thức chiếu và ηₜ=1/(μt); gom hệ số khoảng cách thành (μ/2)[(t−1)aₜ−taₜ₊₁].'], ['Sum to cancel all interior distances, discard the nonpositive terminal term and bound the harmonic sum by 1+ln T.', 'Cộng để triệt tiêu mọi khoảng cách nội bộ, bỏ hạng cuối không dương và chặn tổng điều hòa bởi 1+ln T.']),
  L('m2-w090-e3', 'Quadratic online losses with curvature varying between .5 and 2 share the smallest curvature lower bound, while the gradient bound uses the steepest endpoint.', 'Loss quadratic online có độ cong từ .5 tới 2 dùng cận độ cong thấp nhất chung, còn gradient bound dùng đầu mút dốc nhất.', 'For fₜ(x)=aₜx²/2+bₜx on |x|≤1, μ=min aₜ=.5 and |f′ₜ(x)|=|aₜx+bₜ|≤2+B.', 'Với fₜ(x)=aₜx²/2+bₜx trên |x|≤1, μ=min aₜ=.5 và |f′ₜ(x)|=|aₜx+bₜ|≤2+B.', ['Read the uniform lower bound of aₜ to identify strong convexity across every round.', 'Đọc cận dưới đều của aₜ để xác định lồi mạnh qua mọi vòng.'], ['Differentiate fₜ and apply |x|≤1, aₜ≤2 and |bₜ|≤B with triangle inequality.', 'Lấy đạo hàm fₜ rồi áp |x|≤1, aₜ≤2, |bₜ|≤B bằng bất đẳng thức tam giác.'], ['State μ and G as uniform constants suitable for the theorem, not round-specific optimistic values.', 'Nêu μ,G là hằng số đều phù hợp định lý, không phải giá trị lạc quan từng vòng.']),
  L('m2-w090-e4', 'A bounded linear loss on [−1,1] has no curvature, so boundedness alone cannot justify the logarithmic strongly-convex rate.', 'Loss tuyến tính bị chặn trên [−1,1] không có độ cong, nên tính bị chặn đơn thuần không biện minh rate logarithmic lồi mạnh.', 'Strong-convex O(log T) requires μ>0; ordinary convex OGD gives DG√T with domain diameter D=2.', 'Cận lồi mạnh O(log T) cần μ>0; OGD lồi thường cho DG√T với đường kính miền D=2.', ['Compute the second derivative of the linear loss; it is zero, not bounded below by μ>0.', 'Tính đạo hàm bậc hai của loss tuyến tính; bằng không, không có cận dưới μ>0.'], ['Separate bounded domain/gradient from strong convexity; these are different assumptions.', 'Tách miền/gradient bị chặn khỏi lồi mạnh; đây là hai giả thiết khác nhau.'], ['Use the generic OGD guarantee with D=2 and the supplied gradient bound, and state its static-comparator scope.', 'Dùng bảo đảm OGD tổng quát với D=2 và gradient bound đã cho, nêu rõ phạm vi comparator tĩnh.']),
  L('m2-w090-e5', 'A nonzero-slope linear function on an interval cannot satisfy a positive quadratic curvature lower bound between two distinct points.', 'Hàm tuyến tính có slope khác không trên khoảng không thể thỏa cận dưới độ cong quadratic dương giữa hai điểm khác nhau.', 'μ-strong convexity requires f(u)≥f(x)+g(x)(u−x)+(μ/2)|u−x|²; add the inequalities in both directions.', 'Lồi mạnh μ cần f(u)≥f(x)+g(x)(u−x)+(μ/2)|u−x|²; cộng bất đẳng thức theo cả hai hướng.', ['Write strong-convex inequalities for ordered pairs (x,u) and (u,x).', 'Viết bất đẳng thức lồi mạnh cho cặp có thứ tự (x,u) và (u,x).'], ['Add them so the linear function differences cancel, leaving 0≥μ|u−x|².', 'Cộng để hiệu hàm tuyến tính triệt tiêu, còn 0≥μ|u−x|².'], ['Choose distinct x,u and μ>0 to contradict; the missing curvature cannot be manufactured from boundedness.', 'Chọn x,u khác nhau và μ>0 để mâu thuẫn; tính bị chặn không thể tạo curvature còn thiếu.']),
  L('m2-w091-e1', 'A comparator path u=(0,0,1,1,0) changes twice; its movement budget contributes a penalty proportional to total path length.', 'Đường comparator u=(0,0,1,1,0) đổi hai lần; ngân sách chuyển động tạo penalty tỷ lệ tổng độ dài đường đi.', 'P_T=Σ_{t<T}|uₜ₊₁−uₜ|; dynamic bound includes DP_T/η.', 'P_T=Σ_{t<T}|uₜ₊₁−uₜ|; cận dynamic có hạng DP_T/η.', ['Subtract each consecutive comparator coordinate and take absolute values.', 'Lấy hiệu từng tọa độ comparator liên tiếp rồi tính trị tuyệt đối.'], ['Sum only actual changes to obtain P_T.', 'Chỉ cộng những lần đổi thực tế để có P_T.'], ['Multiply D, P_T and 1/η; explain this is a path-cost term, not a free comparator upgrade.', 'Nhân D, P_T và 1/η; giải thích đây là chi phí đường đi, không phải nâng comparator miễn phí.']),
  L('m2-w091-e2', 'When the comparator changes between rounds, the potential difference contains a cross term bounded by the learner-domain diameter.', 'Khi comparator đổi giữa vòng, hiệu potential chứa tích chéo được chặn bởi đường kính miền learner.', '||x−uₜ||²−||x−uₜ₊₁||²=(uₜ₊₁−uₜ)ᵀ(2x−uₜ−uₜ₊₁), with magnitude ≤2D||uₜ₊₁−uₜ||.', '||x−uₜ||²−||x−uₜ₊₁||²=(uₜ₊₁−uₜ)ᵀ(2x−uₜ−uₜ₊₁), trị tuyệt đối ≤2D||uₜ₊₁−uₜ||.', ['Expand both squared distances and factor the difference by uₜ₊₁−uₜ.', 'Khai triển hai khoảng cách bình phương rồi phân tích hiệu theo uₜ₊₁−uₜ.'], ['Apply Cauchy–Schwarz and bound each comparator-to-x distance by D.', 'Áp Cauchy–Schwarz và chặn từng khoảng cách comparator tới x bởi D.'], ['Sum movement terms and account for division by 2η in the potential inequality to get DP_T/η.', 'Cộng hạng chuyển động và tính hệ số chia 2η trong bất đẳng thức potential để được DP_T/η.']),
  L('m2-w091-e3', 'Knowing total comparator variation P changes the step-size tradeoff by adding DP/η to the usual initial-distance term.', 'Biết tổng variation comparator P làm đổi đánh đổi bước bằng cách cộng DP/η vào hạng khoảng cách đầu quen thuộc.', 'B(η)=(D²+2DP)/(2η)+ηG²T/2; η*=√(D²+2DP)/(G√T), B*=G√T√(D²+2DP).', 'B(η)=(D²+2DP)/(2η)+ηG²T/2; η*=√(D²+2DP)/(G√T), B*=G√T√(D²+2DP).', ['Combine the terms proportional to 1/η before differentiating.', 'Gộp các hạng tỷ lệ 1/η trước khi lấy đạo hàm.'], ['Differentiate the two-term expression, set it to zero and solve the positive η.', 'Lấy đạo hàm biểu thức hai hạng, cho bằng không và giải η dương.'], ['Substitute η* and simplify; state the rate uses known P and does not prove the learner can know future comparator movement causally.', 'Thế η* rồi rút gọn; nêu rate dùng P đã biết và không chứng minh learner biết chuyển động tương lai một cách nhân quả.']),
  L('m2-w091-e4', 'A five-session curriculum already allocated to static regret can include dynamic regret only by selecting it as replacement depth.', 'Curriculum năm buổi đã dành cho static regret chỉ có thể thêm dynamic regret bằng cách chọn nó thay nội dung chiều sâu khác.', 'If each scheduled session is fixed at 240 minutes, an elective topic replaces a planned block instead of adding a sixth session.', 'Nếu mỗi buổi đã cố định 240 phút, chủ đề elective thay một khối đã định thay vì thêm buổi thứ sáu.', ['Identify the existing session and static-regret learning objective that the dynamic extension would displace.', 'Xác định buổi hiện có và mục tiêu static-regret mà phần dynamic sẽ thay thế.'], ['Mark the dynamic comparator/variation material as chosen elective within that session’s time budget.', 'Đánh dấu nội dung comparator động/variation là elective được chọn trong ngân sách thời gian buổi đó.'], ['Preserve the five-session core count and avoid presenting the elective as universally proved or required.', 'Giữ số buổi core là năm và tránh trình bày elective như nội dung phổ quát đã chứng minh hay bắt buộc.']),
  L('m2-w091-e5', 'A comparator path labeled by regimes discovered later depends on hindsight, so it cannot be read as an online action guarantee.', 'Comparator theo chế độ chỉ nhận diện sau này phụ thuộc hindsight nên không thể xem là bảo đảm action online.', 'Causal policy xₜ may depend on history through t, whereas a hindsight comparator uₜ may depend on future regime labels.', 'Policy nhân quả xₜ chỉ phụ thuộc lịch sử tới t, còn comparator hindsight uₜ có thể phụ thuộc nhãn chế độ tương lai.', ['Mark which regime identities are known at decision time and which are revealed only afterward.', 'Đánh dấu nhận diện chế độ nào biết khi ra quyết định và nhãn nào chỉ lộ sau.'], ['Explain that a benchmark may be mathematically valid while not implementable as a decision rule.', 'Giải thích benchmark có thể hợp lệ toán học nhưng không triển khai được thành luật quyết định.'], ['Require a causal change-detection protocol and explicit assumptions before claiming real-time tracking.', 'Yêu cầu protocol phát hiện đổi chế độ nhân quả và giả thiết rõ trước khi khẳng định tracking thời gian thực.']),
  L('m2-w092-e1', 'Observed arm counts weight each inferior arm by how often it was selected, converting gaps in expected reward into pseudo-regret.', 'Số lượt arm quan sát nhân gap của từng arm kém theo số lần được chọn, đổi gap reward kỳ vọng thành pseudo-regret.', 'Reg_T=Σ_iΔ_iN_i(T), with Δ_i=μ*−μ_i and Δ_best=0.', 'Reg_T=Σ_iΔ_iN_i(T), với Δ_i=μ*−μ_i và Δ_best=0.', ['Identify μ*=.8 and calculate gaps for the other two arms.', 'Nhận diện μ*=.8 rồi tính gap cho hai arm còn lại.'], ['Multiply each suboptimal gap by its pull count; the best-arm term contributes zero.', 'Nhân gap mỗi arm kém với số lượt; hạng arm tốt nhất bằng không.'], ['Add contributions and label result expected-mean pseudo-regret, distinct from realized reward or profit.', 'Cộng đóng góp và gọi kết quả pseudo-regret theo mean kỳ vọng, khác reward thực tế hay lợi nhuận.']),
  L('m2-w092-e2', 'Inverse-propensity weighting recovers an arm’s mean by dividing its selected reward indicator by a positive selection probability.', 'Trọng số nghịch propensity khôi phục mean arm bằng cách chia reward có chỉ báo được chọn cho xác suất chọn dương.', 'E[1{A=i}Y_i/p_i|history]=p_iμ_i/p_i=μ_i for p_i>0 and conditionally mean-μ_i rewards.', 'E[1{A=i}Y_i/p_i|history]=p_iμ_i/p_i=μ_i với p_i>0 và reward có mean có điều kiện μ_i.', ['Condition on the history so p_i is fixed for the next action.', 'Điều kiện theo lịch sử để p_i cố định cho action kế tiếp.'], ['Expand expectation over the event A=i; its probability contributes p_i.', 'Khai triển kỳ vọng theo biến cố A=i; xác suất của biến cố đóng góp p_i.'], ['Cancel p_i and state positivity plus conditional reward-mean assumptions; without positivity the estimator is undefined.', 'Khử p_i và nêu giả thiết xác suất dương cùng mean reward có điều kiện; thiếu positivity thì estimator không xác định.']),
  L('m2-w092-e3', 'Regret can be rewritten round by round as the optimal mean minus the mean of the arm actually selected.', 'Regret có thể viết lại từng vòng là mean tối ưu trừ mean của arm thực tế được chọn.', 'Tμ*−EΣₜμ_{Aₜ}=Σ_i(μ*−μ_i)E[N_i(T)]=Σ_iΔ_iE[N_i(T)].', 'Tμ*−EΣₜμ_{Aₜ}=Σ_i(μ*−μ_i)E[N_i(T)]=Σ_iΔ_iE[N_i(T)].', ['Distribute Tμ* across T rounds to write a per-round gap.', 'Phân phối Tμ* qua T vòng để viết gap từng vòng.'], ['Condition on the selected arm Aₜ and express its mean gap as Δ_{Aₜ}.', 'Điều kiện theo arm Aₜ được chọn và biểu diễn gap mean là Δ_{Aₜ}.'], ['Group indicators by arm; their sums are pull counts N_i(T), then take expectation.', 'Nhóm chỉ báo theo arm; tổng của chúng là số lượt N_i(T), rồi lấy kỳ vọng.']),
  L('m2-w092-e4', 'A policy’s low stationary pseudo-regret does not prevent negative net trading return after fees or resolve return uncertainty.', 'Pseudo-regret dừng thấp của policy không ngăn return giao dịch ròng âm sau phí và không giải quyết bất định return.', 'Pseudo-regret compares expected arm means under a stationary model; net return additionally depends on timing, costs, constraints and risk.', 'Pseudo-regret so mean arm kỳ vọng dưới mô hình dừng; return ròng còn phụ thuộc thời điểm, chi phí, ràng buộc và rủi ro.', ['State the benchmark-relative low-regret conclusion under the stationary expected-return model.', 'Nêu kết luận regret thấp so benchmark dưới mô hình return kỳ vọng dừng.'], ['Report the observed net loss after fees as a separate outcome, not a contradiction in the regret definition.', 'Báo lỗ ròng sau phí như kết quả riêng, không coi là mâu thuẫn định nghĩa regret.'], ['Name required return uncertainty, execution timing, transaction costs, portfolio constraints and risk estimand before any profitability claim.', 'Nêu bất định return, thời điểm thực thi, chi phí, ràng buộc danh mục và estimand rủi ro cần có trước claim lợi nhuận.']),
  L('m2-w092-e5', 'Pooling rewards from adaptively chosen arms mixes different means according to the policy’s selection history.', 'Gộp reward từ arm chọn thích nghi trộn các mean khác nhau theo lịch sử chọn của policy.', 'E[Y|A=i,history]=μ_i under the model; a pooled sample mean weights arms by policy-dependent selection frequencies.', 'E[Y|A=i,history]=μ_i theo mô hình; mean mẫu gộp cân các arm theo tần suất chọn phụ thuộc policy.', ['Identify that arm choice is history-dependent and observed arm proportions are policy-selected.', 'Nhận diện chọn arm phụ thuộc lịch sử và tỷ lệ arm quan sát do policy chọn.'], ['Explain how different arm means make a pooled mean unsuitable for a like-for-like arm comparison.', 'Giải thích mean arm khác nhau làm mean gộp không phù hợp so sánh ngang hàng.'], ['Use arm-specific conditional estimates or propensity correction with positivity; state the model behind either repair.', 'Dùng ước lượng có điều kiện theo arm hoặc propensity correction kèm positivity; nêu mô hình đằng sau mỗi cách.']),
  L('m2-w093-e1', 'At t=100 the less-tested arm B receives a larger UCB bonus, so optimism can select it despite its lower empirical mean.', 'Tại t=100 arm B ít được thử hơn nhận bonus UCB lớn, nên optimism có thể chọn dù mean empirical thấp hơn.', 'UCB_i=μ̂_i+√(2log(t)/n_i); choose the arm with largest upper-confidence index.', 'UCB_i=μ̂_i+√(2log(t)/n_i); chọn arm có upper-confidence index lớn nhất.', ['Compute the common numerator √(2log100) once.', 'Tính tử chung √(2log100) một lần.'], ['Divide by √25 and √4 respectively, then add each bonus to its own empirical mean.', 'Chia lần lượt cho √25 và √4 rồi cộng bonus vào mean empirical tương ứng.'], ['Compare indices rather than empirical means; explain exploration comes from uncertainty radius.', 'So chỉ số thay vì mean empirical; giải thích exploration đến từ bán kính bất định.']),
  L('m2-w093-e2', 'Hoeffding’s two tails produce a confidence radius for one fixed bounded-mean estimate.', 'Hai đuôi Hoeffding tạo bán kính tin cậy cho một ước lượng mean bị chặn cố định.', 'For IID observations in [0,1], P(|μ̂−μ|≥r)≤2e^(−2nr²); solve r=√[log(2/δ)/(2n)].', 'Với quan sát IID trong [0,1], P(|μ̂−μ|≥r)≤2e^(−2nr²); giải r=√[log(2/δ)/(2n)].', ['Apply the one-sided Hoeffding bound to the upper tail.', 'Áp Hoeffding một phía cho đuôi trên.'], ['Apply it to the lower tail and union-bound to obtain the factor two.', 'Áp cho đuôi dưới rồi union-bound để có hệ số hai.'], ['Set the result to δ and solve for r, retaining IID and bounded-reward assumptions.', 'Cho cận bằng δ và giải r, giữ giả thiết reward bị chặn IID.']),
  L('m2-w093-e3', 'On simultaneous confidence coverage, the optimal arm’s upper index is below the selected arm’s index, yielding the correct gap bound.', 'Trên coverage confidence đồng thời, upper index của arm tối ưu không vượt index arm được chọn, suy ra cận gap đúng.', 'μ*=μ_j≤UCB_j≤UCB_i=μ̂_i+r_i≤μ_i+2r_i, hence Δ_i≤2r_i.', 'μ*=μ_j≤UCB_j≤UCB_i=μ̂_i+r_i≤μ_i+2r_i, nên Δ_i≤2r_i.', ['Use coverage on optimal j to upper-bound μ* by its UCB_j.', 'Dùng coverage của arm tối ưu j để chặn trên μ* bằng UCB_j.'], ['Use selection: i maximizes the upper index, so UCB_j≤UCB_i.', 'Dùng quy tắc chọn: i cực đại upper index nên UCB_j≤UCB_i.'], ['Use coverage for i to bound UCB_i by μ_i+2r_i; the lower confidence endpoint cannot upper-bound μ*.', 'Dùng coverage của i để chặn UCB_i bởi μ_i+2r_i; lower endpoint không thể chặn trên μ*.']),
  L('m2-w093-e4', 'Selecting the smallest fixed-time p-value among 1,000 arm-look pairs introduces multiplicity and repeated-look selection.', 'Chọn p-value thời điểm cố định nhỏ nhất trong 1,000 cặp arm-lần xem tạo multiplicity và chọn qua nhiều lần nhìn.', 'For M tested claims, familywise control can use Bonferroni α/M; repeated looks need alpha spending or a time-uniform bound.', 'Với M claim kiểm tra, kiểm soát familywise có thể dùng Bonferroni α/M; xem lặp cần alpha spending hoặc cận time-uniform.', ['Count the searched arm-time claims, not only the final displayed p-value.', 'Đếm số claim arm-thời điểm đã tìm, không chỉ p-value cuối được hiển thị.'], ['Explain that the minimum is selected and its nominal fixed-time calibration no longer controls the familywise event.', 'Giải thích minimum đã được chọn nên hiệu chỉnh thời điểm cố định danh nghĩa không còn chặn biến cố familywise.'], ['Choose a remedy matching the protocol: simultaneous union adjustment, prespecified alpha spending or a valid time-uniform method.', 'Chọn cách sửa khớp protocol: hiệu chỉnh union đồng thời, alpha spending định trước hoặc phương pháp time-uniform hợp lệ.']),
  L('m2-w093-e5', 'After a mean switch, the accumulated sample mean can remain centered on the old regime while the UCB radius shrinks with the growing count.', 'Sau khi mean đổi, mean mẫu tích lũy còn quanh chế độ cũ trong khi bán kính UCB giảm theo số lượt tăng.', 'Stationary UCB uses μ̂_i,n around one fixed μ_i with radius r(n); drift invalidates that fixed-mean coverage target.', 'UCB dừng dùng μ̂_i,n quanh một μ_i cố định với bán kính r(n); drift làm sai target coverage mean cố định đó.', ['Separate the historical average from the current post-switch mean.', 'Tách trung bình lịch sử khỏi mean hiện tại sau switch.'], ['Observe that increasing n shrinks the nominal radius even when old observations dominate the regime change.', 'Nhận thấy n tăng làm bán kính danh nghĩa co dù quan sát cũ vẫn áp đảo sau đổi chế độ.'], ['Name nonstationarity as the failed premise and require an explicit window/change model with its own guarantee.', 'Nêu phi dừng là tiền đề thất bại và yêu cầu mô hình cửa sổ/phát hiện đổi với bảo đảm riêng.']),
  L('m2-w094-e1', 'Six successes and four failures update a Beta prior by adding counts to its two shape parameters.', 'Sáu lần thành công và bốn thất bại cập nhật prior Beta bằng cách cộng số đếm vào hai tham số shape.', 'Beta(α,β) with s successes and f failures becomes Beta(α+s,β+f), mean (α+s)/(α+β+s+f).', 'Beta(α,β) với s thành công và f thất bại thành Beta(α+s,β+f), mean (α+s)/(α+β+s+f).', ['Add successes to α and failures to β, preserving their meanings.', 'Cộng thành công vào α, thất bại vào β, giữ đúng ý nghĩa từng tham số.'], ['Compute the posterior shape pair and sum its parameters.', 'Tính cặp shape posterior và tổng hai tham số.'], ['Divide the first shape by the total for predictive mean; check that it lies between zero and one.', 'Chia shape đầu cho tổng để có mean dự báo; kiểm tra kết quả nằm trong [0,1].']),
  L('m2-w094-e2', 'Bernoulli data multiply a Beta prior kernel by success and failure powers, leaving another Beta kernel.', 'Dữ liệu Bernoulli nhân kernel prior Beta với lũy thừa thành công/thất bại, tạo kernel Beta khác.', 'Prior kernel θ^(α−1)(1−θ)^(β−1) times likelihood θˢ(1−θ)^f yields Beta(α+s,β+f).', 'Kernel prior θ^(α−1)(1−θ)^(β−1) nhân likelihood θˢ(1−θ)^f cho Beta(α+s,β+f).', ['Write the likelihood for s successes and f failures, omitting only constants independent of θ.', 'Viết likelihood cho s thành công và f thất bại, chỉ bỏ hằng số độc lập θ.'], ['Multiply powers and add exponents for θ and 1−θ separately.', 'Nhân các lũy thừa và cộng số mũ riêng cho θ và 1−θ.'], ['Match the posterior kernel to Beta shape convention; distinguish kernel identification from normalizing constant calculation.', 'Đối chiếu kernel posterior với quy ước shape Beta; phân biệt nhận diện kernel với tính hằng số chuẩn hóa.']),
  L('m2-w094-e3', 'Thompson sampling chooses arm one when its independent posterior draw exceeds the other arm’s draw.', 'Thompson sampling chọn arm một khi draw posterior độc lập của nó vượt draw arm kia.', 'P(A=1)=P(θ̃₁≥θ̃₂)=∫F₂(x)dF₁(x), with an explicit tie convention.', 'P(A=1)=P(θ̃₁≥θ̃₂)=∫F₂(x)dF₁(x), với quy ước hòa tường minh.', ['Express the action event as an inequality between the two independent posterior draws.', 'Biểu diễn biến cố chọn arm bằng bất đẳng thức giữa hai draw posterior độc lập.'], ['Condition on θ̃₁=x and use F₂(x) for the probability the second draw is no larger.', 'Điều kiện theo θ̃₁=x rồi dùng F₂(x) cho xác suất draw thứ hai không lớn hơn.'], ['Integrate with respect to F₁ and specify how exact ties are handled; posterior means alone do not give this probability.', 'Lấy tích phân theo F₁ và nêu cách xử lý hòa chính xác; posterior mean đơn thuần không cho xác suất này.']),
  L('m2-w094-e4', 'A three-round-delayed Bernoulli reward updates only when it is revealed, so earlier actions use a posterior based solely on observed outcomes.', 'Reward Bernoulli trễ ba vòng chỉ cập nhật khi được tiết lộ, nên action trước đó dùng posterior từ outcome đã quan sát.', 'Posterior after revealed counts is Beta(α+s_revealed,β+f_revealed); pending rewards are not yet likelihood observations.', 'Posterior sau số đếm đã lộ là Beta(α+s_revealed,β+f_revealed); reward đang pending chưa phải quan sát likelihood.', ['Record the selected arm and attach the unobserved reward to its pending assignment.', 'Ghi arm được chọn và gắn reward chưa thấy vào assignment đang chờ.'], ['Before its reveal, sample actions from the posterior using only revealed successes/failures.', 'Trước lúc lộ, lấy mẫu action từ posterior chỉ dùng thành công/thất bại đã lộ.'], ['Update once on reveal and state that immediate-feedback regret results do not directly cover the delayed protocol.', 'Cập nhật một lần khi lộ và nêu kết quả regret feedback tức thời không trực tiếp bao phủ protocol trễ.']),
  L('m2-w094-e5', 'One observation barely changes highly concentrated Beta(100,1) and Beta(1,100) priors, so early Thompson allocation is prior-dominated.', 'Một quan sát hầu như không đổi prior Beta(100,1) và Beta(1,100) tập trung cao, nên phân bổ Thompson ban đầu bị prior chi phối.', 'Posterior shapes add one observed count to prior shapes; posterior draw distributions remain concentrated when prior concentration is large.', 'Shape posterior cộng số đếm quan sát vào shape prior; phân phối draw posterior vẫn tập trung khi tổng shape prior lớn.', ['Update each arm with its single observation and compare the added count with the prior total concentration.', 'Cập nhật mỗi arm với một quan sát rồi so số đếm thêm với tổng concentration prior.'], ['Reason about posterior draw overlap rather than replacing Thompson draws by posterior-mean greedy choices.', 'Lập luận về độ chồng lấn posterior draw thay vì thay Thompson bằng chọn greedy theo mean.'], ['Identify prior sensitivity and recommend prior justification plus sensitivity analysis before interpreting early allocations.', 'Nhận diện độ nhạy prior và đề xuất biện minh prior cùng phân tích độ nhạy trước khi diễn giải phân bổ ban đầu.']),
  L('m2-w095-e1', 'With one action per round and maximum reveal delay four, the newest four chosen outcomes can remain pending and each provisional loss can err by at most one.', 'Với một action mỗi vòng và độ trễ lộ tối đa bốn, bốn outcome mới chọn có thể còn pending và mỗi loss tạm lệch tối đa một.', 'At most d pending actions; if provisional and true losses lie in [0,1], total ledger discrepancy is at most d.', 'Tối đa d action pending; nếu loss tạm và thật thuộc [0,1], sai khác tổng ledger không quá d.', ['Identify the latest d rounds as the only possible origins of unrevealed actions.', 'Nhận diện d vòng gần nhất là nơi duy nhất có thể phát sinh action chưa lộ.'], ['Use one action per round to count at most d pending outcomes.', 'Dùng một action mỗi vòng để đếm tối đa d outcome pending.'], ['Bound each provisional-versus-true loss discrepancy by the unit range, then sum across pending items; this is bookkeeping, not regret.', 'Chặn chênh loss tạm-thật mỗi phần bởi range một rồi cộng trên pending; đây là hạch toán, không phải regret.']),
  L('m2-w095-e2', 'A single switch changes the arm-mean vector once; the variation definition adds the largest coordinate movement at that time.', 'Một lần switch đổi vector mean arm một lần; định nghĩa variation cộng chuyển động tọa độ lớn nhất tại thời điểm đó.', 'V_T=Σ_{t<T}max_i|μ_{i,t+1}−μ_{i,t}|.', 'V_T=Σ_{t<T}max_i|μ_{i,t+1}−μ_{i,t}|.', ['Mark the one time increment where arm means change; all other increments contribute zero.', 'Đánh dấu increment thời gian duy nhất mean arm thay đổi; các increment khác đóng góp không.'], ['Take the maximum absolute change across arms at that increment.', 'Lấy độ lớn thay đổi lớn nhất qua các arm tại increment đó.'], ['Sum over time to get V_T; do not add the two arm changes when the definition uses a maximum.', 'Cộng theo thời gian để có V_T; không cộng thay đổi hai arm khi định nghĩa dùng maximum.']),
  L('m2-w095-e3', 'The maximum-delay rule limits how many actions can be unresolved at once, and bounded losses convert that count into a ledger-error bound.', 'Quy tắc độ trễ tối đa giới hạn số action chưa có kết quả đồng thời; loss bị chặn đổi số đếm thành cận sai số ledger.', 'At cutoff t with delay d and one action/round, pending origins are among the latest d; Σ_pending|aₛ−ℓₛ|≤d when aₛ,ℓₛ∈[0,1].', 'Tại cutoff t với delay d và một action/vòng, origin pending thuộc d vòng gần nhất; Σ_pending|aₛ−ℓₛ|≤d nếu aₛ,ℓₛ∈[0,1].', ['Show that any action older than the last d rounds must already have been revealed under the deterministic delay convention.', 'Chứng minh action cũ hơn d vòng cuối phải được tiết lộ theo quy ước độ trễ xác định.'], ['Count at most one unresolved action in each of those d rounds.', 'Đếm tối đa một action chưa giải quyết trong mỗi d vòng đó.'], ['Use |aₛ−ℓₛ|≤1 per pending action and sum; explicitly state that arm quality/regret is unconstrained by this argument.', 'Dùng |aₛ−ℓₛ|≤1 cho mỗi action pending rồi cộng; nêu lập luận không chặn chất lượng arm/regret.']),
  L('m2-w095-e4', 'After a permanent mean switch, best fixed arm and per-round oracle answer different questions: long-run choice versus hindsight tracking.', 'Sau switch mean vĩnh viễn, arm cố định tốt nhất và oracle từng vòng trả lời hai câu khác nhau: chọn dài hạn và tracking hindsight.', 'Static comparator: argmin_iΣₜℓ_{i,t}; per-round oracle: Σₜmin_iℓ_{i,t}; the latter uses future outcomes/regimes.', 'Comparator tĩnh: argmin_iΣₜℓ_{i,t}; oracle từng vòng: Σₜmin_iℓ_{i,t}; loại sau dùng outcome/chế độ tương lai.', ['Define the best fixed arm over the full horizon and interpret its average-regime target.', 'Định nghĩa arm cố định tốt nhất cả horizon và diễn giải target chế độ trung bình.'], ['Define the per-round oracle and identify its hindsight access unavailable to the policy.', 'Định nghĩa oracle từng vòng và nhận diện quyền hindsight policy không có.'], ['For a deployable tracking goal, state variation/change assumptions, causal information and switching costs.', 'Với mục tiêu tracking triển khai được, nêu giả thiết variation/change, thông tin nhân quả và chi phí chuyển arm.']),
  L('m2-w095-e5', 'After arm one drops from mean .9 to .1, its long history can still keep the empirical estimate above arm two’s stable .5 mean.', 'Sau khi mean arm một giảm từ .9 xuống .1, lịch sử dài vẫn có thể giữ estimate empirical cao hơn mean .5 của arm hai.', 'Stationary UCB radius shrinks like √(log t/N_i) around a fixed-mean target; arbitrary drift invalidates that coverage interpretation.', 'Bán kính UCB dừng co như √(log t/N_i) quanh target mean cố định; drift tùy ý làm sai diễn giải coverage.', ['Compare arm one’s old-regime reward count with only ten post-switch observations at t=910.', 'So số reward arm một từ chế độ cũ với chỉ mười quan sát sau switch tại t=910.'], ['Explain how the cumulative estimate is stale while a larger N_i makes its nominal bonus smaller.', 'Giải thích estimate tích lũy bị cũ trong khi N_i lớn làm bonus danh nghĩa nhỏ.'], ['Name the stationarity failure and avoid applying fixed-mean Hoeffding coverage to the drifting mean.', 'Nêu lỗi giả thiết dừng và tránh áp coverage Hoeffding mean cố định cho mean đang trôi.']),
  L('m2-w096-e1', 'For gap .25, the confidence-radius crossing formula gives a good-event upper pull threshold at horizon 1000.', 'Với gap .25, công thức điểm cắt bán kính confidence cho ngưỡng lượt trên biến cố tốt tại horizon 1000.', 'If Δ≤2√(c logT/N), then N≤4c logT/Δ².', 'Nếu Δ≤2√(c logT/N) thì N≤4c logT/Δ².', ['Square both positive sides of the gap inequality.', 'Bình phương hai vế dương của bất đẳng thức gap.'], ['Rearrange for N and insert Δ=.25,c=1,T=1000 using natural logarithm.', 'Biến đổi tìm N rồi thế Δ=.25,c=1,T=1000 với logarithm tự nhiên.'], ['Label the result as a good-event upper threshold with theorem constants, not an exact pull count or expected regret.', 'Gọi kết quả là ngưỡng trên biến cố tốt theo hằng số định lý, không phải số lượt chính xác hay regret kỳ vọng.']),
  L('m2-w096-e2', 'A finite-horizon stochastic UCB regret proof unions concentration over every arm and pre-generated reward prefix, then charges the bad event separately.', 'Chứng minh regret UCB stochastic hữu hạn horizon union concentration trên mọi arm và prefix reward sinh trước, rồi tính riêng biến cố xấu.', 'With radius √(2logT/n), P(Eᶜ)≤2K/T³; on E, N_i(T)≤2+8logT/Δ_i² and regret≤Σ_{Δ_i>0}Δ_i(2+8logT/Δ_i²)+2K/T² for rewards in [0,1].', 'Với bán kính √(2logT/n), P(Eᶜ)≤2K/T³; trên E, N_i(T)≤2+8logT/Δ_i² và regret≤Σ_{Δ_i>0}Δ_i(2+8logT/Δ_i²)+2K/T² với reward [0,1].', ['For each arm and prefix n≤T, apply two-sided Hoeffding with the fixed-horizon radius; union over K·T events gives the stated failure probability.', 'Với từng arm và prefix n≤T, áp Hoeffding hai phía với bán kính horizon cố định; union K·T biến cố cho xác suất lỗi đã nêu.'], ['Explain adaptive pulls reveal prefixes of pre-generated arm streams; on simultaneous event use μ*≤UCB_best≤UCB_selected≤μ_i+2r_i to bound suboptimal pulls, including initialization/crossing allowance.', 'Giải thích lượt chọn thích nghi chỉ lộ prefix của stream arm sinh trước; trên biến cố đồng thời dùng μ*≤UCB_tốt≤UCB_chọn≤μ_i+2r_i để chặn lượt arm kém, tính lượt khởi tạo/vượt ngưỡng.'], ['Sum gap-weighted good-event pulls; on failure charge at most T regret times P(Eᶜ), and keep the expected pseudo-regret decomposition explicit.', 'Cộng lượt trên biến cố tốt có trọng số gap; khi lỗi chặn tối đa T regret nhân P(Eᶜ), giữ tường minh phân rã pseudo-regret kỳ vọng.']),
  L('m2-w096-e3', 'Once a suboptimal arm’s confidence radius is at most half its gap, its upper index cannot stay above the optimal mean on the coverage event.', 'Khi bán kính confidence của arm kém không quá nửa gap, upper index không thể giữ trên mean tối ưu trên biến cố coverage.', 'Δ_i≤2√(c logT/N_i) implies N_i≤4c logT/Δ_i².', 'Δ_i≤2√(c logT/N_i) suy ra N_i≤4c logT/Δ_i².', ['Square the inequality, keeping Δ_i>0 for a suboptimal arm.', 'Bình phương bất đẳng thức, giữ Δ_i>0 vì arm kém.'], ['Multiply by N_i and divide by Δ_i² to isolate the count.', 'Nhân với N_i rồi chia Δ_i² để tách số lượt.'], ['Interpret this as a crossing threshold after which the good-event index argument limits pulls; it is not equality for realized N_i.', 'Diễn giải đây là ngưỡng cắt sau đó lập luận index trên biến cố tốt chặn lượt; không phải đẳng thức cho N_i thực tế.']),
  L('m2-w096-e4', 'A citation to a Thompson-sampling book is not itself a proof that a particular regret theorem applies to a reported experiment.', 'Trích sách về Thompson sampling tự nó không chứng minh định lý regret cụ thể áp dụng cho thí nghiệm được báo cáo.', 'A theorem claim needs model assumptions, algorithm/protocol, comparator, horizon and bound constants; otherwise label it sourced/assumed.', 'Claim định lý cần giả thiết mô hình, thuật toán/protocol, comparator, horizon và hằng số cận; nếu không hãy ghi là dẫn/giả định.', ['Identify the exact cited theorem and record its reward model, stationarity, feedback and prior assumptions.', 'Nhận diện đúng định lý được dẫn và ghi mô hình reward, tính dừng, feedback và giả thiết prior.'], ['Match the implemented algorithm and evaluated comparator to those hypotheses one by one.', 'Đối chiếu thuật toán triển khai và comparator đánh giá với từng giả thiết đó.'], ['If the proof is not reproduced or assumptions cannot be verified, mark the theorem as assumed and separate pseudo-regret from realized reward.', 'Nếu không trình bày chứng minh hoặc chưa xác minh giả thiết, ghi theorem là giả định và tách pseudo-regret khỏi reward thực tế.']),
  L('m2-w096-e5', 'A lower empirical loss over thirty overlapping dates is only a sample description until dependence, selection and forecast timing are addressed.', 'Loss empirical thấp hơn trên ba mươi ngày chồng lấn chỉ là mô tả mẫu cho đến khi xử lý phụ thuộc, chọn lựa và thời điểm forecast.', 'Inference on mean loss difference requires a defined estimand, dependence-valid uncertainty and selection control; a profit claim also needs causal timing and costs.', 'Suy luận mean chênh loss cần estimand xác định, bất định hợp lệ dưới phụ thuộc và kiểm soát lựa chọn; claim lợi nhuận còn cần timing nhân quả và chi phí.', ['Compute/report the paired sample contrast as descriptive evidence only.', 'Tính/báo chênh paired mẫu chỉ như bằng chứng mô tả.'], ['Account for overlapping-label dependence with a justified HAC/block method and state its assumptions.', 'Tính phụ thuộc nhãn chồng lấn bằng HAC/block có biện minh và nêu giả thiết.'], ['Address multiple model/threshold selection and information timing; require execution costs and a return estimand for any profit conclusion.', 'Xử lý chọn nhiều mô hình/ngưỡng và thời điểm thông tin; yêu cầu chi phí thực thi và estimand return cho kết luận lợi nhuận.']),
];

const lessons = Object.fromEntries(rows) as Record<string, TeachingEntry>;
const canonicalExercises = optimizationAuthor.weeks
  .filter((week) => week.week >= 61 && week.week <= 96)
  .flatMap((week) => week.exercises.map((exercise) => exercise.id));
const gateExercises = (optimizationAuthor.assessments ?? [])
  .filter((assessment) => assessment.week >= 61 && assessment.week <= 96)
  .flatMap((assessment) => assessment.forms.flatMap((form) => form.exerciseIds));
const missing = [...canonicalExercises, ...gateExercises].filter((id) => !(id in lessons));
const extra = Object.keys(lessons).filter((id) => !canonicalExercises.includes(id));
if (missing.length || extra.length || canonicalExercises.length !== rows.length) {
  throw new Error(`Optimization teaching coverage mismatch: missing=${missing.join(',')}; extra=${extra.join(',')}; exercises=${canonicalExercises.length}; lessons=${rows.length}`);
}

export default lessons;
